    func testCoordinatorSeedingPatternProducesCorrectDisplayTextForExistingSavedAmount() {
        // Reproduces exactly what Coordinator.init does (seed a CurrencyInputState via `load`)
        // followed by what the fixed makeUIView now does (read displayText()) — proving the data
        // this fix pushes into the field's initial text is correct for a real saved amount.
        var state = CurrencyInputState(allowsNegative: false, allowsZero: true, minimum: nil, maximum: nil)
        state.load(1000)
        XCTAssertEqual(state.amount, 1000)
        XCTAssertEqual(state.displayText(locale: Locale(identifier: "en_US")), "$1,000.00", "a $1,000 saved Savings Goal must display as formatted currency immediately, never $0.00")
    }

    func testCoordinatorSeedingNilAmountStillProducesEmptyDisplay() {
        var state = CurrencyInputState(allowsNegative: false, allowsZero: true, minimum: nil, maximum: nil)
        state.load(nil)
        XCTAssertNil(state.amount)
        XCTAssertEqual(state.displayText(), "", "a nil/new amount must still display empty (placeholder), not \"$0.00\"")
    }

    func testCoordinatorSeedingTrueZeroAmountDisplaysAsZeroNotEmpty() {
        var state = CurrencyInputState(allowsNegative: false, allowsZero: true, minimum: nil, maximum: nil)
        state.load(Decimal(0))
        XCTAssertEqual(state.amount, 0)
        XCTAssertEqual(state.displayText(locale: Locale(identifier: "en_US")), "$0.00", "a genuinely saved $0 must still display as $0.00, distinct from an empty/nil field")
    }

    func testCentsFirstTypingStillUnaffectedByInitialDisplayFix() {
        // CurrencyInputState.enterDigit is untouched by this fix — locks in no regression.
        var state = CurrencyInputState(allowsNegative: false, allowsZero: true, minimum: nil, maximum: nil)
        state.enterDigit(1)
        state.enterDigit(2)
        state.enterDigit(3)
        XCTAssertEqual(state.amount, 1.23)
    }

