        XCTAssertEqual(settings.monthlyGoal, 1000)
        XCTAssertEqual(settings.weeklySpendingLimit, 0)
    }

    func testAlreadyClampedRemainingProducesZeroWeekly() {
        // monthlySpendRemaining is always clamped at 0 upstream (see
        // MonthlyPlanCalculator.monthlySpendRemaining) — this locks in that
        // applyMonthlyPlanAutoCalculate never re-introduces a negative weeklySpendingLimit even
        // if called with 0 directly.
        let settings = BudgetSettings()
        settings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: 1000, monthlySpendRemaining: 0)
        XCTAssertEqual(settings.monthlyGoal, 1000)
        XCTAssertEqual(settings.weeklySpendingLimit, 0, "must never display/persist a negative weekly limit")
    }

    func testWeeklyLimitFormulaDividesByExactlyFourNeverFourPointThreeThree() {
        let settings = BudgetSettings()
        settings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: 0, monthlySpendRemaining: 433)
        // 433 / 4 = 108.25 exactly; 433 / 4.33 would be 100 exactly — the two are distinguishable.
        XCTAssertEqual(settings.weeklySpendingLimit, Decimal(433) / Decimal(4))
        XCTAssertNotEqual(settings.weeklySpendingLimit, 100, "must never use the 4.33 weeks-per-month approximation")
    }

    func testChangingMonthlyPlanGoalPropagatesToBudgetSettingsAndRecalculatesWeeklyLimitUsingCurrentSpendRemaining() {
        let settings = BudgetSettings()
        settings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: 1000, monthlySpendRemaining: 1800)
        XCTAssertEqual(settings.monthlyGoal, 1000)
        XCTAssertEqual(settings.weeklySpendingLimit, 450)

        // Monthly Plan goal changes to 1200; the caller recomputes Monthly Spend Remaining
        // (which itself subtracts the goal) and passes the new result in — here simulated as an
        // unrelated new remaining value to prove the goal alone doesn't drive the division.
        settings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: 1200, monthlySpendRemaining: 1600)
        XCTAssertEqual(settings.monthlyGoal, 1200)
        XCTAssertEqual(settings.weeklySpendingLimit, 400)
    }

    func testCalculatorInputChangesAffectingActualSpendingUpdateWeeklyLimit() {
        let calendar = Self.calendar(timeZoneIdentifier: "America/New_York")
        let month = DateInterval(start: calendar.date(from: DateComponents(year: 2026, month: 7, day: 1))!, end: calendar.date(from: DateComponents(year: 2026, month: 8, day: 1))!)
        let income = MonthlyPlanCalculator.estimatedMonthlyIncome([], in: month)
        let fixedExpenses = MonthlyPlanCalculator.estimatedMonthlyFixedExpenses([], in: month)
        let moneyAfterBills = MonthlyPlanCalculator.moneyAfterBills(income: income + 2000, fixedExpenses: fixedExpenses + 500)
        let spendingBudget = MonthlyPlanCalculator.monthlySpendingBudget(moneyAfterBills: moneyAfterBills, savingsGoal: 1000, bufferAmount: 0)
        let remainingBefore = MonthlyPlanCalculator.monthlySpendRemaining(monthlySpendingBudget: spendingBudget, actualMonthlySpending: 200)
        let settings = BudgetSettings()
        settings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: 1000, monthlySpendRemaining: remainingBefore)
        let weeklyBefore = settings.weeklySpendingLimit

        // Simulate a legitimate calculator-input change (more actual spending this month lowers Monthly Spend Remaining).
        let remainingAfter = MonthlyPlanCalculator.monthlySpendRemaining(monthlySpendingBudget: spendingBudget, actualMonthlySpending: 700)
        settings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: 1000, monthlySpendRemaining: remainingAfter)
        XCTAssertNotEqual(settings.weeklySpendingLimit, weeklyBefore, "a legitimate change to actual monthly spending must update the derived Weekly Spending Limit")
        XCTAssertEqual(settings.weeklySpendingLimit, remainingAfter / 4)
    }

    func testExistingCalculatorDerivedProjectedMonthlySavingsFormulaRemainsUnchanged() {
        // Locks in the pre-existing, unmodified formula: projectedMonthlySavings = income - fixedExpenses - actualSpentThisMonth.
        XCTAssertEqual(MonthlyPlanCalculator.projectedMonthlySavings(income: 5000, fixedExpenses: 2000, actualSpentThisMonth: 800), 2200)
        XCTAssertEqual(MonthlyPlanCalculator.projectedMonthlySavings(income: 3000, fixedExpenses: 3000, actualSpentThisMonth: 0), 0)
    }

    /// WEEKLY SPENDING UNIFICATION — supersedes the prior
    /// `testMonthlyPlanViewSourcesMonthlySpendRemainingFromExistingCalculatorSummaryNotAReimplementation`:
    /// the actual-spending-adjusted `monthlySpendRemaining` formula this test used to lock in was
    /// the root cause of Weekly Budget's $1,042.25 defect (it ignored a custom Planned Weekly
    /// Spending override entirely and silently shrank as spending came in). `applyBudgetAutoCalculateIfNeeded`
    /// now derives the weekly limit from `plannedWeeklySpending`/`plannedMonthlySpending` — the
    /// same override-aware values the Hero Card/Planning section/Week-by-Week already use — never
    /// reimplemented, and the underlying `BudgetSettings.applyMonthlyPlanAutoCalculate` function
    /// itself remains completely unchanged (see `testBudgetSettingsAutoCalculateComputesWeeklyLimitInline`).
    func testMonthlyPlanViewDerivesWeeklyLimitFromEffectivePlannedWeeklySpending() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let range = source.range(of: "private func applyBudgetAutoCalculateIfNeeded()") else {
            XCTFail("applyBudgetAutoCalculateIfNeeded not found"); return
        }
        let section = String(source[range.lowerBound...].prefix(600))
        XCTAssertTrue(section.contains("let expectedWeeklyLimit = plannedWeeklySpending"), "must reuse the existing, already-authoritative plannedWeeklySpending, never a duplicated actual-spending-adjusted formula")
        XCTAssertTrue(section.contains("budgetSettings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: goal, monthlySpendRemaining: plannedMonthlySpending)"), "must pass the override-aware plannedMonthlySpending through the calculator's own unchanged /4 formula")
        XCTAssertFalse(source.contains("private var monthlySpendRemaining: Decimal"), "the legacy actual-spending-adjusted computed property must no longer exist in this view")
    }

    func testNoSecondWriterCanOverwriteTheDerivedWeeklySpendingLimit() throws {
        // MonthlyPlanCalculator.applyRecommendedWeeklyLimit remains defined (do not redesign the
        // calculator itself) but must no longer be called from MonthlyPlanView's lifecycle.
        let sourceURL = URL(fileURLWithPath: #filePath)
