    }

    func testAutoUpdateWeeklyBudgetFromPlanCanNoLongerConflictWithDerivedWeeklyLimit() {
        // The calculator function itself is intentionally unchanged (do not redesign
        // MonthlyPlanCalculator) — it can still be called directly and would still overwrite the
        // value if invoked. What matters is that no production call site invokes it anymore
        // (verified above); this test locks in that the derived formula, once applied, is not
        // silently reverted by simply having autoUpdateWeeklyBudgetFromPlan set to true.
        let planSettings = MonthlyPlanSettings(monthlySavingsGoal: 1200, autoUpdateWeeklyBudgetFromPlan: true)
        let budgetSettings = BudgetSettings()
        budgetSettings.applyMonthlyPlanAutoCalculate(monthlyPlanSavingsGoal: planSettings.monthlySavingsGoal, monthlySpendRemaining: 1800)
        XCTAssertEqual(budgetSettings.weeklySpendingLimit, 450)
        XCTAssertEqual(budgetSettings.monthlyGoal, 1200)
    }

