    // MARK: - Monthly Plan: Fixed Bills Timing Filter (presentation filtering only)

    func testFixedBillsTimingFilterDefaultsToAll() throws {
        // MonthlyPlanView's @State declares `PlanTiming?` with no explicit assignment, so it
        // defaults to nil ("All") on every fresh view — exactly the spec's "defaulting back to
        // All when the view is recreated is acceptable," with no persistence of any kind.
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        XCTAssertTrue(source.contains("@State private var fixedBillsTimingFilter: PlanTiming?"), "the filter must be plain, unpersisted, view-local @State defaulting to nil (All)")
        XCTAssertFalse(source.contains("@AppStorage") && source.contains("fixedBillsTimingFilter"), "must never persist the filter selection via AppStorage/UserDefaults")
    }

    func testFixedBillsTimingFilterAllReturnsEveryBillUnchangedAndInOrder() {
        let bills = [
            RecurringExpense(name: "Rent", amount: 1800, timing: .beginningMonth),
            RecurringExpense(name: "Phone", amount: 60, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 220, timing: .endMonth)
        ]
        let filtered = FixedBillsTimingFilter.apply(bills, timing: nil)
        XCTAssertEqual(filtered.map(\.id), bills.map(\.id), "All (nil) must return every bill, in the exact same order")
    }

    func testFixedBillsTimingFilterEachExistingTimingValueFiltersCorrectly() {
        let beginning = RecurringExpense(name: "Rent", amount: 1800, timing: .beginningMonth)
        let mid = RecurringExpense(name: "Phone", amount: 60, timing: .midMonth)
        let end = RecurringExpense(name: "Insurance", amount: 220, timing: .endMonth)
        let weekly = RecurringExpense(name: "Groceries", amount: 100, timing: .weekly)
        let custom = RecurringExpense(name: "Car Repair", amount: 450, timing: .customDate)
        let bills = [beginning, mid, end, weekly, custom]

        for timing in PlanTiming.allCases {
            let filtered = FixedBillsTimingFilter.apply(bills, timing: timing)
            XCTAssertEqual(filtered.count, 1, "exactly one fixture bill uses \(timing.rawValue)")
            XCTAssertEqual(filtered.first?.timing, timing)
        }
    }

    func testFixedBillsTimingFilterMidMonthReturnsOnlyMidMonthBills() {
        let rent = RecurringExpense(name: "Rent", amount: 1800, timing: .beginningMonth)
        let phone = RecurringExpense(name: "Phone", amount: 60, timing: .midMonth)
        let streaming = RecurringExpense(name: "Streaming", amount: 15, timing: .midMonth)
        let insurance = RecurringExpense(name: "Insurance", amount: 220, timing: .endMonth)

        let filtered = FixedBillsTimingFilter.apply([rent, phone, streaming, insurance], timing: .midMonth)

        XCTAssertEqual(Set(filtered.map(\.id)), Set([phone.id, streaming.id]))
        XCTAssertTrue(filtered.allSatisfy { $0.timing == .midMonth })
    }

    func testFixedBillsTimingFilterNeverMutatesStoredBills() {
        let phone = RecurringExpense(name: "Phone", amount: 60, timing: .midMonth)
        let originalAmount = phone.amount
        let originalTiming = phone.timing
        let originalName = phone.name

        _ = FixedBillsTimingFilter.apply([phone], timing: .midMonth)
        _ = FixedBillsTimingFilter.apply([phone], timing: .endMonth)
        _ = FixedBillsTimingFilter.apply([phone], timing: nil)

        XCTAssertEqual(phone.amount, originalAmount, "filtering must never mutate a bill's amount")
        XCTAssertEqual(phone.timing, originalTiming, "filtering must never mutate a bill's stored timing")
        XCTAssertEqual(phone.name, originalName, "filtering must never mutate a bill's name")
    }

    func testFixedBillsTimingFilterDoesNotChangeMonthlyPlanCalculatorInputOrOutput() throws {
        // MonthlyPlanView's `summary` must always feed MonthlyPlanCalculator the unfiltered
        // `allRecurringExpenses`/`allIncomeSources` — never `filteredRecurringExpenses` — so
        // selecting a Fixed Bills filter can never change the Hero Card, savings, or weekly-limit
        // math. Proven directly against the calculator (unaffected by any filter selection,
        // since the filter is never passed to it at all) and by source-scanning the call site.
        let interval = DateRangeHelper.currentMonthRange()
        let rent = RecurringExpense(name: "Rent", amount: 1800, timing: .beginningMonth)
        let phone = RecurringExpense(name: "Phone", amount: 60, timing: .midMonth)
        let allBills = [rent, phone]

        let unfilteredTotal = MonthlyPlanCalculator.estimatedMonthlyFixedExpenses(allBills, in: interval)
        // Even though a filter would narrow the DISPLAYED list to just `phone`, the calculator
        // must always be called with the full, unfiltered set — simulated here by confirming the
        // calculator's own result reflects every bill regardless of what a filter would show.
        XCTAssertEqual(unfilteredTotal, 1860, "the calculator input must remain every active bill, never a filtered subset")

        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let summaryRange = source.range(of: "MonthlyPlanCalculator.summary(") else {
            XCTFail("MonthlyPlanCalculator.summary call site not found"); return
        }
        let summarySection = String(source[summaryRange.lowerBound...].prefix(400))
        XCTAssertTrue(summarySection.contains("recurringExpenses: allRecurringExpenses"), "the calculator must always be fed allRecurringExpenses, never the filtered list")
        XCTAssertFalse(summarySection.contains("filteredRecurringExpenses"), "the calculator must never receive the filtered Fixed Bills list")
    }

    func testFixedBillsTimingFilterEmptyMatchingResultReturnsEmptyArray() {
        let rent = RecurringExpense(name: "Rent", amount: 1800, timing: .beginningMonth)
        let filtered = FixedBillsTimingFilter.apply([rent], timing: .weekly)
