    }

    func testFixedBillsTimingFilterPreservesOriginalOrderWithinFilteredResult() {
        let first = RecurringExpense(name: "Phone", amount: 60, timing: .midMonth, createdAt: Date(timeIntervalSince1970: 1))
        let second = RecurringExpense(name: "Streaming", amount: 15, timing: .midMonth, createdAt: Date(timeIntervalSince1970: 2))
        let third = RecurringExpense(name: "Gym", amount: 40, timing: .midMonth, createdAt: Date(timeIntervalSince1970: 3))
        // Deliberately pre-sorted by createdAt, matching @Query's own sort — filtering must not
        // reorder this within the result.
        let sortedBills = [first, second, third]

        let filtered = FixedBillsTimingFilter.apply(sortedBills, timing: .midMonth)

        XCTAssertEqual(filtered.map(\.id), [first.id, second.id, third.id])
    }

