    // MARK: - Monthly Plan: Scenario Mode

    private func makeScenarioFixture(
        incomeSources: [IncomeSource]? = nil,
        recurringExpenses: [RecurringExpense]? = nil,
        planSettings: MonthlyPlanSettings? = nil,
        weeklyBudgetLimit: Decimal = 0,
        transactions: [FinanceTransaction] = []
    ) -> MonthlyPlanScenarioViewModel {
        let month = DateRangeHelper.currentMonthRange()
        let week = DateRangeHelper.currentWeekRange(weekStartsOnSunday: true)
        let income = incomeSources ?? [
            IncomeSource(name: "Paycheck", amount: 2500, frequency: .monthly, timing: .midMonth),
            IncomeSource(name: "Second Income", amount: 1000, frequency: .monthly, timing: .beginningMonth)
        ]
        let expenses = recurringExpenses ?? [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Insurance", amount: 250, frequency: .monthly, timing: .endMonth)
        ]
        return MonthlyPlanScenarioViewModel(
            incomeSources: income,
            recurringExpenses: expenses,
            planSettings: planSettings,
            weeklyBudgetLimit: weeklyBudgetLimit,
            transactions: transactions,
            month: month,
            weekInterval: week,
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70
        )
    }

    func testScenarioStartsEquivalentToCurrentMonthlyPlan() {
        let viewModel = makeScenarioFixture()
        let scenario = viewModel.scenarioSummary
        let current = viewModel.currentSummary
        XCTAssertEqual(scenario.estimatedMonthlyIncome, current.estimatedMonthlyIncome)
        XCTAssertEqual(scenario.estimatedMonthlyFixedExpenses, current.estimatedMonthlyFixedExpenses)
        XCTAssertEqual(scenario.flexibleSpendingAvailable, current.flexibleSpendingAvailable)
        XCTAssertEqual(scenario.projectedMonthlySavings, current.projectedMonthlySavings)
        XCTAssertEqual(scenario.recommendedWeeklySpendingLimit, current.recommendedWeeklySpendingLimit)
    }

    func testScenarioUsesAllActiveFixedBillsRegardlessOfMonthlyPlanViewTimingFilter() throws {
        // MonthlyPlanView must feed the Scenario sheet the COMPLETE, unfiltered arrays
        // (allIncomeSources/allRecurringExpenses), never filteredRecurringExpenses/
        // activeRecurringExpenses — proven both behaviorally (below) and via source scan.
        let midMonthOnly = [RecurringExpense(name: "Phone", amount: 60, frequency: .monthly, timing: .midMonth)]
        let allBills = midMonthOnly + [RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth)]
        let viewModel = makeScenarioFixture(recurringExpenses: allBills)
        XCTAssertEqual(viewModel.engine.baselineItems.filter { $0.ledger == .expense }.count, 2, "Scenario must start from every active bill, not a Timing-filtered subset")

        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let sheetRange = source.range(of: "MonthlyPlanScenarioView(") else {
            XCTFail("MonthlyPlanScenarioView( call site not found"); return
        }
        let sheetSection = String(source[sheetRange.lowerBound...].prefix(500))
        XCTAssertTrue(sheetSection.contains("incomeSources: allIncomeSources"), "must pass the complete, unfiltered income array")
