    ) -> (items: [ScenarioLineItem], month: DateInterval, week: DateInterval) {
        let income = incomeSources ?? [
            IncomeSource(name: "Paycheck", amount: 2500, frequency: .monthly, timing: .midMonth),
            IncomeSource(name: "Second Income", amount: 1000, frequency: .monthly, timing: .beginningMonth)
        ]
        let expenses = recurringExpenses ?? [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Phone", amount: 60, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 250, frequency: .monthly, timing: .endMonth)
        ]
        let items = ScenarioLineItemFactory.baseline(incomeSources: income, recurringExpenses: expenses)
        return (items, DateRangeHelper.currentMonthRange(), DateRangeHelper.currentWeekRange(weekStartsOnSunday: true))
    }

