    /// A test-only conforming type — no production code implements `ScenarioAction` yet ("Do NOT
    /// begin implementing Add, Remove, or Change yet"). This exists solely to prove the extension
    /// point itself works end-to-end: a future phase's action type needs nothing from
    /// `ScenarioEngine` except this protocol conformance to plug in.
    private struct TestExcludeAllAction: ScenarioAction {
        let id = UUID()
        let name = "Test: Exclude All"
        func apply(to items: [ScenarioLineItem]) -> [ScenarioLineItem] {
            items.map { item in
                var copy = item
                copy.isIncluded = false
                return copy
            }
        }
    }

    func testScenarioEngineDispatchesArbitraryFutureActionWithoutEngineModification() {
        let fixture = makeScenarioArchitectureFixture()
        let engine = ScenarioEngine(baselineItems: fixture.items)

        engine.apply(TestExcludeAllAction())

        XCTAssertTrue(engine.items.allSatisfy { !$0.isIncluded }, "A future ScenarioAction must be able to mutate scenario state purely via the protocol, with no engine changes")
        XCTAssertTrue(engine.baselineItems.allSatisfy(\.isIncluded), "Applying an action must never mutate the baseline snapshot")
    }

    func testScenarioEngineResetDiscardsAppliedActions() {
        let fixture = makeScenarioArchitectureFixture()
        let engine = ScenarioEngine(baselineItems: fixture.items)

        engine.apply(TestExcludeAllAction())
        XCTAssertTrue(engine.items.allSatisfy { !$0.isIncluded })

        engine.reset()

        XCTAssertEqual(engine.items, engine.baselineItems, "Reset must completely discard every applied action and restore the exact baseline")
        XCTAssertTrue(engine.items.allSatisfy(\.isIncluded))
    }

    func testScenarioSummaryBuilderMatchesDirectCalculatorCallForBaseline() {
        let fixture = makeScenarioArchitectureFixture()
        let engineSummary = ScenarioSummaryBuilder.summary(
            for: fixture.items,
            month: fixture.month,
            planSettings: nil,
            weeklyBudgetLimit: 0,
            transactions: [],
            weekInterval: fixture.week,
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70
        )

        let income = [
            IncomeSource(name: "Paycheck", amount: 2500, frequency: .monthly, timing: .midMonth),
            IncomeSource(name: "Second Income", amount: 1000, frequency: .monthly, timing: .beginningMonth)
        ]
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Phone", amount: 60, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 250, frequency: .monthly, timing: .endMonth)
        ]
        let directSummary = MonthlyPlanCalculator.summary(
            month: fixture.month,
            incomeSources: income,
            recurringExpenses: expenses,
            planSettings: nil,
            weeklyBudgetLimit: 0,
            transactions: [],
            weekInterval: fixture.week,
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70
        )

        XCTAssertEqual(engineSummary.estimatedMonthlyIncome, directSummary.estimatedMonthlyIncome, "ScenarioSummaryBuilder must reuse MonthlyPlanCalculator's own math unchanged, never a new formula")
        XCTAssertEqual(engineSummary.estimatedMonthlyFixedExpenses, directSummary.estimatedMonthlyFixedExpenses)
        XCTAssertEqual(engineSummary.flexibleSpendingAvailable, directSummary.flexibleSpendingAvailable)
        XCTAssertEqual(engineSummary.projectedMonthlySavings, directSummary.projectedMonthlySavings)
