    // MARK: - Scenario Builder Phase 2: Connect Engine + Add/Remove/Change

    // MARK: Architecture and migration

    func testActiveScenarioFeatureUsesScenarioEngineAsAuthoritativeState() {
        let viewModel = makeScenarioFixture()
        let target = viewModel.engine.baselineItems.first { $0.ledger == .income }!
        viewModel.changeItemAmount(target.id, newAmount: target.amount + 42)
        XCTAssertEqual(viewModel.engine.items.first { $0.id == target.id }?.amount, target.amount + 42, "Builder mutations must land in ScenarioEngine.items")
        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyIncome, viewModel.currentSummary.estimatedMonthlyIncome + 42, "the summary shown must be derived from that same engine state")
    }

    func testNoCompetingOldCalculationPathRemains() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Services/MonthlyPlanScenarioViewModel.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        for obsolete in ["struct ScenarioIncomeItem", "struct ScenarioExpenseItem", "baselineIncomeItems", "baselineExpenseItems", "func setIncomeAmount", "func setExpenseAmount"] {
            XCTAssertFalse(source.contains(obsolete), "the old parallel array-based Scenario state (\(obsolete)) must be fully removed, not left alongside ScenarioEngine")
        }
        XCTAssertTrue(source.contains("let engine: ScenarioEngine"), "MonthlyPlanScenarioViewModel must hold ScenarioEngine as its one scenario state")
    }

    func testScenarioSummariesRouteThroughMonthlyPlanCalculator() {
        let income = [IncomeSource(name: "Paycheck", amount: 3000, frequency: .monthly, timing: .midMonth)]
        let expenses = [RecurringExpense(name: "Rent", amount: 1000, frequency: .monthly, timing: .beginningMonth)]
        let viewModel = makeScenarioFixture(incomeSources: income, recurringExpenses: expenses)

        let direct = MonthlyPlanCalculator.summary(
            month: DateRangeHelper.currentMonthRange(), incomeSources: income, recurringExpenses: expenses,
            planSettings: nil, weeklyBudgetLimit: 0, transactions: [],
            weekInterval: DateRangeHelper.currentWeekRange(weekStartsOnSunday: true), weekStartsOnSunday: true,
            includePending: true, warningThreshold: 0.70
        )
        XCTAssertEqual(viewModel.currentSummary.estimatedMonthlyIncome, direct.estimatedMonthlyIncome)
        XCTAssertEqual(viewModel.currentSummary.estimatedMonthlyFixedExpenses, direct.estimatedMonthlyFixedExpenses)
        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyIncome, direct.estimatedMonthlyIncome, "with no active actions, scenario must equal the direct calculator call")
    }

