        XCTAssertFalse(viewModel.addHypotheticalIncome(name: "Valid Name", amount: -5), "negative amount must be rejected for Add")
        XCTAssertEqual(viewModel.engine.items.count, beforeCount)
        XCTAssertTrue(viewModel.addHypotheticalIncome(name: "Valid Name", amount: 1), "a valid positive amount must be accepted")
