    func testRemovingModificationFromActiveChangesRestoresBaselineItem() {
        let viewModel = makeScenarioFixture()
        let target = viewModel.engine.baselineItems.first { $0.ledger == .income }!
        viewModel.removeItem(target.id)
        XCTAssertFalse(viewModel.engine.items.first { $0.id == target.id }!.isIncluded)

        viewModel.removeModification(target.id)

        XCTAssertTrue(viewModel.engine.items.first { $0.id == target.id }!.isIncluded, "removing the active Remove modification must restore the item to baseline")
