    func testReChangingSameItemUpdatesReplacesPriorChange() {
        let viewModel = makeScenarioFixture()
        let target = viewModel.engine.baselineItems.first { $0.ledger == .income }!
        viewModel.changeItemAmount(target.id, newAmount: target.amount + 100)
        viewModel.changeItemAmount(target.id, newAmount: target.amount + 500)
        XCTAssertEqual(viewModel.engine.activeActions.filter { $0.id == target.id }.count, 1, "re-Change must replace, never stack")
        XCTAssertEqual(viewModel.engine.items.first { $0.id == target.id }!.amount, target.amount + 500, "the LATEST Change must win")
    }

    func testChangeAndRemoveCannotCoexistForSameItem() {
        let viewModel = makeScenarioFixture()
        let target = viewModel.engine.baselineItems.first { $0.ledger == .income }!

        viewModel.changeItemAmount(target.id, newAmount: target.amount + 100)
        viewModel.removeItem(target.id)
        XCTAssertEqual(viewModel.engine.activeActions.filter { $0.id == target.id }.count, 1, "Remove must replace an existing Change for the same item")
        XCTAssertFalse(viewModel.engine.items.first { $0.id == target.id }!.isIncluded, "Remove (the later action) must win")

        viewModel.changeItemAmount(target.id, newAmount: target.amount + 200)
        XCTAssertEqual(viewModel.engine.activeActions.filter { $0.id == target.id }.count, 1, "Change must replace an existing Remove for the same item")
        let final = viewModel.engine.items.first { $0.id == target.id }!
        XCTAssertTrue(final.isIncluded, "a later Change must bring a removed item back")
        XCTAssertEqual(final.amount, target.amount + 200)
    }

    // MARK: Combined scenarios

    func testMultipleActionsAcrossCategoriesCombineCorrectly() {
        let income = [
            IncomeSource(name: "Primary", amount: 3000, frequency: .monthly, timing: .beginningMonth),
            IncomeSource(name: "Secondary", amount: 800, frequency: .monthly, timing: .beginningMonth)
        ]
        let expenses = [
            RecurringExpense(name: "Electric", amount: 180, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Subscription", amount: 15, frequency: .monthly, timing: .endMonth)
        ]
        let viewModel = makeScenarioFixture(incomeSources: income, recurringExpenses: expenses)

        let secondaryIncome = viewModel.engine.baselineItems.first { $0.name == "Secondary" }!
        let electric = viewModel.engine.baselineItems.first { $0.name == "Electric" }!
        let subscription = viewModel.engine.baselineItems.first { $0.name == "Subscription" }!

        viewModel.removeItem(secondaryIncome.id)
        viewModel.changeItemAmount(electric.id, newAmount: 250)
        viewModel.addHypotheticalFixedBill(name: "New Mid-Month Bill", amount: 125, timing: .midMonth)
        viewModel.removeItem(subscription.id)

        XCTAssertEqual(viewModel.engine.activeActions.count, 4)
        XCTAssertEqual(
            viewModel.scenarioSummary.estimatedMonthlyIncome,
            viewModel.currentSummary.estimatedMonthlyIncome - secondaryIncome.amount
        )
        XCTAssertEqual(
            viewModel.scenarioSummary.estimatedMonthlyFixedExpenses,
            viewModel.currentSummary.estimatedMonthlyFixedExpenses + (250 - 180) + 125 - 15
        )
    }

    func testActionOrderingIsDeterministic() {
        let fixture = makeScenarioArchitectureFixture()
        let engineA = ScenarioEngine(baselineItems: fixture.items)
        let engineB = ScenarioEngine(baselineItems: fixture.items)
        let targetA = fixture.items.first { $0.ledger == .income }!
        let targetB = fixture.items.filter { $0.ledger == .expense }.first!

        engineA.apply(ChangeScenarioItemAmountAction(id: targetA.id, newAmount: targetA.amount + 10))
        engineA.apply(ChangeScenarioItemAmountAction(id: targetB.id, newAmount: targetB.amount + 20))

        engineB.apply(ChangeScenarioItemAmountAction(id: targetB.id, newAmount: targetB.amount + 20))
        engineB.apply(ChangeScenarioItemAmountAction(id: targetA.id, newAmount: targetA.amount + 10))

        XCTAssertEqual(engineA.items.first { $0.id == targetA.id }!.amount, engineB.items.first { $0.id == targetA.id }!.amount, "final state must not depend on application order for non-conflicting actions")
        XCTAssertEqual(engineA.items.first { $0.id == targetB.id }!.amount, engineB.items.first { $0.id == targetB.id }!.amount)
    }

    func testRemovingOneActiveActionRebuildsFromBaselinePlusRemaining() {
        let viewModel = makeScenarioFixture()
        let income = viewModel.engine.baselineItems.first { $0.ledger == .income }!
        let expense = viewModel.engine.baselineItems.first { $0.ledger == .expense }!

        viewModel.changeItemAmount(income.id, newAmount: income.amount + 500)
        viewModel.changeItemAmount(expense.id, newAmount: expense.amount + 200)
        XCTAssertEqual(viewModel.engine.activeActions.count, 2)

        viewModel.removeModification(income.id)

        XCTAssertEqual(viewModel.engine.activeActions.count, 1, "only the removed modification's action should be gone")
        XCTAssertEqual(viewModel.engine.items.first { $0.id == income.id }!.amount, income.amount, "the removed modification's effect must be gone")
        XCTAssertEqual(viewModel.engine.items.first { $0.id == expense.id }!.amount, expense.amount + 200, "the remaining modification's effect must still apply")
    }

    func testResetRestoresExactBaselineResults() {
        let fixture = makeScenarioArchitectureFixture()
        let engine = ScenarioEngine(baselineItems: fixture.items)
        let target = fixture.items.first { $0.ledger == .income }!
        engine.apply(ChangeScenarioItemAmountAction(id: target.id, newAmount: target.amount + 1000))
        XCTAssertNotEqual(engine.items, engine.baselineItems)

        engine.reset()

        XCTAssertEqual(engine.items, engine.baselineItems)
    }

    func testResetClearsActiveActionList() {
        let fixture = makeScenarioArchitectureFixture()
        let engine = ScenarioEngine(baselineItems: fixture.items)
        let target = fixture.items.first { $0.ledger == .income }!
        engine.apply(RemoveScenarioItemAction(id: target.id))
        XCTAssertEqual(engine.activeActions.count, 1)

        engine.reset()

        XCTAssertEqual(engine.activeActions.count, 0)
    }

    // MARK: Timing safety

    func testBeginningWeeklyCustomDateItemsRemainInBaselineCalculations() {
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Gym", amount: 40, frequency: .monthly, timing: .weekly),
            RecurringExpense(name: "Annual Fee", amount: 100, frequency: .monthly, timing: .customDate)
        ]
        let viewModel = makeScenarioFixture(incomeSources: [], recurringExpenses: expenses)
        XCTAssertEqual(viewModel.currentSummary.estimatedMonthlyFixedExpenses, 1200 + 40 + 100, "unsupported-category items must still be counted in Current")
        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyFixedExpenses, 1200 + 40 + 100, "and in Scenario, with no active actions")
        XCTAssertEqual(viewModel.engine.baselineItems.count, 3, "all three must be present in baseline even though none maps to a named category")
    }

    func testUnsupportedTimingCategoriesNotMappedToMidOrEndMonth() {
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Gym", amount: 40, frequency: .monthly, timing: .weekly),
            RecurringExpense(name: "Annual Fee", amount: 100, frequency: .monthly, timing: .customDate)
        ]
        let viewModel = makeScenarioFixture(incomeSources: [], recurringExpenses: expenses)
        XCTAssertTrue(viewModel.engine.items(in: .midMonth).isEmpty, "none of these must be forced into Mid Month")
        XCTAssertTrue(viewModel.engine.items(in: .endMonth).isEmpty, "none of these must be forced into End Month")
        XCTAssertTrue(viewModel.engine.baselineItems.allSatisfy { $0.category == nil }, "each must map to no named category, never a wrong one")
    }

    func testOnlyIncomeMidMonthEndMonthAreEditableCategories() {
        // Phase 3 adds a 4th category (Monthly Savings Goal) — see
        // testMonthlySavingsGoalAppearsAsScenarioCategory/testMonthlySavingsGoalHasNoLineItemsToAddOrRemove
        // for its own coverage. Income/Mid Month/End Month remain the only three categories backed
        // by real ScenarioLineItems (Add/Remove/Change all apply); still no Beginning/Weekly/Custom
        // Date category.
        XCTAssertEqual(Set(ScenarioCategory.allCases), Set([.income, .midMonth, .endMonth, .monthlySavingsGoal]))
        let lineItemBackedCategories: [ScenarioCategory] = [.income, .midMonth, .endMonth]
        XCTAssertEqual(Set(lineItemBackedCategories), Set([.income, .midMonth, .endMonth]))
    }

