    func testNoRealIncomeSourceMutatedByBuilderActions() {
        let income = IncomeSource(name: "Paycheck", amount: 2500, frequency: .monthly, timing: .midMonth)
        let originalAmount = income.amount
        let viewModel = makeScenarioFixture(incomeSources: [income], recurringExpenses: [])
        let target = viewModel.engine.baselineItems.first!
        viewModel.changeItemAmount(target.id, newAmount: 1)
        viewModel.removeItem(target.id)
