    func testNoSwiftDataInsertSaveDeleteInScenarioFiles() throws {
        for fileName in ["MonthlyPlanScenarioViewModel.swift", "ScenarioEngine.swift", "ScenarioModificationActions.swift", "ScenarioLineItem.swift", "ScenarioCategory.swift", "ScenarioAction.swift"] {
            let sourceURL = URL(fileURLWithPath: #filePath)
                .deletingLastPathComponent()
                .appendingPathComponent("../FinanceTrack/Services/\(fileName)")
                .standardized
            let source = try String(contentsOf: sourceURL, encoding: .utf8)
            for forbidden in [".insert(", ".save()", ".delete(", "modelContext"] {
                XCTAssertFalse(source.contains(forbidden), "\(fileName) must never call \(forbidden)")
            }
        }
    }

    func testNoSupabaseOrBackendCodeReferencedInScenarioFiles() throws {
        for fileName in ["MonthlyPlanScenarioViewModel.swift", "ScenarioEngine.swift", "ScenarioModificationActions.swift", "MonthlyPlanScenarioView.swift"] {
            let path = fileName.hasSuffix("View.swift") && !fileName.hasSuffix("ViewModel.swift")
                ? "../FinanceTrack/Views/MonthlyPlan/\(fileName)"
                : "../FinanceTrack/Services/\(fileName)"
            let sourceURL = URL(fileURLWithPath: #filePath).deletingLastPathComponent().appendingPathComponent(path).standardized
            let source = try String(contentsOf: sourceURL, encoding: .utf8)
            for forbidden in ["Supabase", "URLSession", "HouseholdSharingService", "sharing_permissions"] {
                XCTAssertFalse(source.contains(forbidden), "\(fileName) must remain purely local — no backend/sharing reference")
            }
        }
    }

