    // MARK: - Scenario Builder: Mid-Month/End-of-Month Total must display actual expenses, not abs(net)

    func testMidMonthCurrentDisplaysExpensesNotAbsNet() {
        let income = [IncomeSource(name: "Side Gig", amount: 1000, frequency: .monthly, timing: .midMonth)]
        let expenses = [RecurringExpense(name: "Phone", amount: 2500, frequency: .monthly, timing: .midMonth)]
        let viewModel = makeScenarioFixture(incomeSources: income, recurringExpenses: expenses)
        let total = viewModel.currentTiming(.midMonth)
        XCTAssertEqual(total.net, -1500, "net remains the true signed cash-flow figure — unrelated to what's displayed")
        XCTAssertEqual(total.expenses, 2500, "the displayed Current value must be the actual expense total, not abs(net) (which would incorrectly read $1,500)")
    }

    func testMidMonthScenarioDisplaysExpensesNotAbsNet() {
        let income = [IncomeSource(name: "Side Gig", amount: 1000, frequency: .monthly, timing: .midMonth)]
