    func testTimedIncomeDoesNotReduceDisplayedExpenseTotal() {
        // The required example: $1,000 timed income, $2,500 timed expenses. abs(net) would
        // incorrectly show $1,500; the correct display is the actual expense total, $2,500.
        let income = [IncomeSource(name: "Side Gig", amount: 1000, frequency: .monthly, timing: .midMonth)]
        let expenses = [RecurringExpense(name: "Phone", amount: 2500, frequency: .monthly, timing: .midMonth)]
        let viewModel = makeScenarioFixture(incomeSources: income, recurringExpenses: expenses)
        XCTAssertEqual(viewModel.currentTiming(.midMonth).expenses, 2500)
        XCTAssertNotEqual(viewModel.currentTiming(.midMonth).expenses, abs(viewModel.currentTiming(.midMonth).net), "displayed expenses must not equal abs(net) when timed income is nonzero")
    }

    func testEqualExpenseTotalsProduceZeroDifference() {
        let expenses = [RecurringExpense(name: "Phone", amount: 60, frequency: .monthly, timing: .midMonth)]
        let viewModel = makeScenarioFixture(incomeSources: [], recurringExpenses: expenses)
        let current = viewModel.currentTiming(.midMonth).expenses
        let scenario = viewModel.scenarioTiming(.midMonth).expenses
        XCTAssertEqual(scenario - current, 0, "identical Current and Scenario expense totals must produce a zero Difference")
    }

    /// The required example, increase direction: timed income $1,000 in both Current and
    /// Scenario; expenses rise from $2,500 to $2,700. Proves the difference is computed from
    /// `expenses`, not `abs(net)` — under the old (incorrect) `abs(net)` approach this would have
    /// been `abs(1000-2700) - abs(1000-2500) = 1700 - 1500 = +200`, which happens to match here
    /// only by coincidence of these particular numbers; the assertions below pin the actual
    /// expense values themselves, which `abs(net)` would NOT have reported correctly (it would
    /// have shown $1,500 → $1,700, not the true $2,500 → $2,700).
    func testIncreasedScenarioExpensesProduceUnfavorablePositiveDifference() {
        let income = [
            IncomeSource(name: "Side Gig", amount: 1000, frequency: .monthly, timing: .midMonth)
        ]
        let expenses = [RecurringExpense(name: "Electric", amount: 2500, frequency: .monthly, timing: .midMonth)]
        let viewModel = makeScenarioFixture(incomeSources: income, recurringExpenses: expenses)
        let target = viewModel.engine.baselineItems.first { $0.ledger == .expense }!
        viewModel.changeItemAmount(target.id, newAmount: 2700)

        let current = viewModel.currentTiming(.midMonth).expenses
        let scenario = viewModel.scenarioTiming(.midMonth).expenses
        XCTAssertEqual(current, 2500, "Current must show the true expense total, not abs(net) = $1,500")
        XCTAssertEqual(scenario, 2700, "Scenario must show the true expense total, not abs(net) = $1,700")
        XCTAssertEqual(scenario - current, 200, "Difference must be +$200")
        XCTAssertGreaterThan(scenario, current, "a higher expense total must read as unfavorable direction (higherIsBetter: false)")
    }

    /// The required example, decrease direction: expenses fall from $2,500 to $2,200.
    func testDecreasedScenarioExpensesProduceFavorableNegativeDifference() {
        let expenses = [RecurringExpense(name: "Electric", amount: 2500, frequency: .monthly, timing: .midMonth)]
        let viewModel = makeScenarioFixture(incomeSources: [], recurringExpenses: expenses)
        let target = viewModel.engine.baselineItems.first!
        viewModel.changeItemAmount(target.id, newAmount: 2200)

        let current = viewModel.currentTiming(.midMonth).expenses
        let scenario = viewModel.scenarioTiming(.midMonth).expenses
        XCTAssertEqual(current, 2500)
        XCTAssertEqual(scenario, 2200)
        XCTAssertEqual(scenario - current, -300, "Difference must be -$300")
        XCTAssertLessThan(scenario, current, "a lower expense total must read as favorable direction (higherIsBetter: false)")
    }

    func testIncomeSavingsFlexibleSpendingAndWeeklyLimitFormattingUnaffectedByExpenseTotalFix() {
        let income = [IncomeSource(name: "Paycheck", amount: 3000, frequency: .monthly, timing: .beginningMonth)]
        let expenses = [RecurringExpense(name: "Rent", amount: 1000, frequency: .monthly, timing: .beginningMonth)]
        let viewModel = makeScenarioFixture(incomeSources: income, recurringExpenses: expenses)
        // None of these route through ScenarioTimingTotal at all — they come straight from
        // MonthlyPlanCalculator.Summary, untouched by this fix.
        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyIncome, 3000)
        XCTAssertEqual(viewModel.scenarioSummary.flexibleSpendingAvailable, viewModel.currentSummary.flexibleSpendingAvailable)
        XCTAssertEqual(viewModel.scenarioSummary.projectedMonthlySavings, viewModel.currentSummary.projectedMonthlySavings)
        XCTAssertEqual(viewModel.scenarioSummary.recommendedWeeklySpendingLimit, viewModel.currentSummary.recommendedWeeklySpendingLimit)
    }

    func testScenarioTimingTotalNetRemainsUnchangedAndMathematicallyCorrect() {
        // net (income - expenses) must remain byte-for-byte the same formula it always was.
        // ScenarioTimingTotal no longer carries any derived-magnitude helper at all — net and
        // expenses are the only two figures used, each for its own distinct purpose.
        let total = ScenarioTimingTotal(income: 500, expenses: 300)
        XCTAssertEqual(total.net, 200)
        XCTAssertEqual(total.expenses, 300)

        let negativeTotal = ScenarioTimingTotal(income: 0, expenses: 300)
        XCTAssertEqual(negativeTotal.net, -300, "net must remain the true signed value")
        XCTAssertEqual(negativeTotal.expenses, 300)
    }

    /// Supplements (never replaces) the behavioral tests above — confirms the view actually wires
    /// the corrected raw-amount Bill Group total (SCENARIO MONTHLY PLANNING CORRECTION) into its
