    func testRemovingIncomePlusChangingSavingsGoalCombinesCorrectly() {
        // The exact example from the task brief: Income $7000, Expenses $3659, Savings Goal $1000
        // -> Flexible $2341. Remove $2600 income -> -259. Then goal 1000 -> 0 -> ~741.
        let secondaryIncome = IncomeSource(name: "Secondary Income", amount: 2600, frequency: .monthly, timing: .beginningMonth)
        let income = [
            IncomeSource(name: "Primary Income", amount: 4400, frequency: .monthly, timing: .beginningMonth),
            secondaryIncome
        ]
        let expenses = [RecurringExpense(name: "Bills", amount: 3659, frequency: .monthly, timing: .beginningMonth)]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: 1000)
        let viewModel = makeScenarioFixture(incomeSources: income, recurringExpenses: expenses, planSettings: settings)

        XCTAssertEqual(viewModel.currentSummary.estimatedMonthlyIncome, 7000)
        XCTAssertEqual(viewModel.currentSummary.flexibleSpendingAvailable, 2341)

        viewModel.removeItem(secondaryIncome.id)
        XCTAssertEqual(viewModel.scenarioSummary.flexibleSpendingAvailable, -259)

        viewModel.changeMonthlySavingsGoal(0)
        XCTAssertEqual(viewModel.scenarioSummary.flexibleSpendingAvailable, 741, "removing income plus zeroing the savings goal must combine additively")
        XCTAssertEqual(viewModel.activeModifications.count, 2)
    }

    func testScenarioBuilderRecalculatesUsingTemporarySavingsGoalNotRealGoal() {
        // Reuses the existing MonthlyPlanCalculator.summary path directly (never a fork) — proves
        // the Scenario figure matches what the SAME calculator produces for a real MonthlyPlanSettings
        // carrying the hypothetical goal.
        let income = [IncomeSource(name: "Paycheck", amount: 5000, frequency: .monthly, timing: .beginningMonth)]
        let expenses = [RecurringExpense(name: "Rent", amount: 2000, frequency: .monthly, timing: .beginningMonth)]
