        viewModel.changeMonthlySavingsGoal(1500)

        let month = DateRangeHelper.currentMonthRange()
        let week = DateRangeHelper.currentWeekRange(weekStartsOnSunday: true)
        let hypotheticalSettings = MonthlyPlanSettings(monthlySavingsGoal: 1500)
        let direct = MonthlyPlanCalculator.summary(
            month: month, incomeSources: income, recurringExpenses: expenses, planSettings: hypotheticalSettings,
            weeklyBudgetLimit: 0, transactions: [], weekInterval: week, weekStartsOnSunday: true,
            includePending: true, warningThreshold: 0.70
        )
        XCTAssertEqual(viewModel.scenarioSummary.flexibleSpendingAvailable, direct.flexibleSpendingAvailable)
        XCTAssertEqual(realSettings.monthlySavingsGoal, 500, "the real settings object must remain untouched throughout")
    }

