    func testTrueOverBudgetBehaviorStillWorks() {
        let comparisonWithSpending = MonthlyPlanCalculator.WeeklyPlanComparison(
            weekInterval: DateRangeHelper.currentWeekRange(weekStartsOnSunday: true),
            recommendedLimit: 0,
            actualSpent: 50,
            status: .over
