    // MARK: Fixed Bills across every PlanTiming (10-19)

    private func makeFixedBillsFixture() -> MonthlyPlanScenarioViewModel {
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Phone", amount: 60, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 250, frequency: .monthly, timing: .endMonth),
            RecurringExpense(name: "Gym", amount: 40, frequency: .monthly, timing: .weekly),
            // 1200/12 = an exact 100, deliberately avoiding a repeating-decimal amount (e.g. 100/12)
            // — Decimal preserves per-operation significant-digit metadata, so two independently
            // computed but mathematically-equal repeating values (e.g. summed different ways) can
            // legitimately fail XCTAssertEqual on trailing-digit count alone. That is a Decimal
            // precision-representation quirk in the TEST fixture, not a calculation bug.
            RecurringExpense(name: "Annual Fee", amount: 1200, frequency: .yearly, timing: .customDate)
        ]
        return makePhase4Fixture(incomeSources: [], recurringExpenses: expenses)
    }

