    func testPhase4CombinedIncomeRemovalAndSavingsGoalZero() {
        // Exact fixture from the task's own required arithmetic example.
        let income = [
            IncomeSource(name: "Primary", amount: 4400, frequency: .monthly, timing: .beginningMonth),
            IncomeSource(name: "VA Income", amount: 2600, frequency: .monthly, timing: .beginningMonth)
        ]
        let expenses = [RecurringExpense(name: "Bills", amount: 3659, frequency: .monthly, timing: .beginningMonth)]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: 1000)
        let viewModel = makePhase4Fixture(incomeSources: income, recurringExpenses: expenses, planSettings: settings)

        XCTAssertEqual(viewModel.currentSummary.flexibleSpendingAvailable, 2341, "current flexible spending must be the exact authoritative Decimal result")

        let vaIncome = viewModel.removableIncomeItems().first { $0.name == "VA Income" }!
        viewModel.removeItem(vaIncome.id)
        XCTAssertTrue(viewModel.changeMonthlySavingsGoal(0))

        XCTAssertEqual(viewModel.scenarioSummary.flexibleSpendingAvailable, 741, "exact Decimal result: (4400 - 3659 - 0) = 741")
        let difference = viewModel.scenarioSummary.flexibleSpendingAvailable - viewModel.currentSummary.flexibleSpendingAvailable
        XCTAssertEqual(difference, -1600, "combined net effect must be exactly -1600, not the raw -2600 income removal")
    }

