    // MARK: Timing / Extra Spending (26-31)

    func testPhase4ExtraSpendingAfterMidMonthBillsUsesAuthoritativeInputsWithoutDoubleCounting() {
        // Beginning+Mid-Month income/bills only (End-of-Month/Weekly/Custom-Date excluded — see
        // extraSpendingThroughCutoff's own header) minus the FULL, un-prorated savings goal —
        // independently computed by hand, exact Decimal result, per this phase's own requirement
        // to use exact values rather than re-deriving the formula under test.
        let income = [
            IncomeSource(name: "Paycheck", amount: 3000, frequency: .monthly, timing: .beginningMonth),
            IncomeSource(name: "Late Bonus", amount: 400, frequency: .monthly, timing: .endMonth)
        ]
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Phone", amount: 60, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 250, frequency: .monthly, timing: .endMonth)
        ]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: 500)
        let viewModel = makePhase4Fixture(incomeSources: income, recurringExpenses: expenses, planSettings: settings)
        // Eligible (Beginning+Mid only): income 3000 (Late Bonus excluded, End-of-Month), expenses
        // 1200+60=1260 (Insurance excluded, End-of-Month). 3000 - 1260 - 500 (goal) - 0 (buffer) = 1240.
        XCTAssertEqual(viewModel.currentExtraSpendingAfter(.midMonth), 1240)
        // Proof of no double-counting: Rent/Phone are NOT also subtracted a second time beyond
        // their one appearance in the 1260 eligible-expenses figure.
        XCTAssertEqual(viewModel.currentTiming(.midMonth).expenses, 60, "the Mid-Month bill TOTAL (Phone alone) is a different figure from the cutoff calculation, which also includes the earlier Beginning-Month Rent")
    }

    func testPhase4ExtraSpendingAfterEndOfMonthBillsUsesAuthoritativeInputsWithoutDoubleCounting() {
        // End-of-Month is the true whole-month figure — flexibleSpendingAvailable itself, which
        // already includes Rent, Phone, AND Insurance exactly once each.
        let income = [IncomeSource(name: "Paycheck", amount: 3000, frequency: .monthly, timing: .beginningMonth)]
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Phone", amount: 60, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 250, frequency: .monthly, timing: .endMonth)
        ]
        let viewModel = makePhase4Fixture(incomeSources: income, recurringExpenses: expenses)
        // 3000 - (1200+60+250) - 0 (no goal) - 0 (no buffer) = 1490.
        XCTAssertEqual(viewModel.currentExtraSpendingAfter(.endMonth), 1490)
        XCTAssertEqual(viewModel.currentExtraSpendingAfter(.endMonth), viewModel.currentSummary.flexibleSpendingAvailable, "End-of-Month must equal the true whole-month flexibleSpendingAvailable, never a further subtraction from it")
    }

