    // MARK: Custom Date Range (32-50)

    private func day(_ year: Int, _ month: Int, _ dayOfMonth: Int, calendar: Calendar = .current) -> Date {
        calendar.date(from: DateComponents(year: year, month: month, day: dayOfMonth))!
    }

    func testPhase4DateRangeSameDayRange() {
        let anchor = day(2026, 6, 15)
