    func testPhase4ExpenseIncreaseDecreaseColorSemanticsCorrect() {
        // higherIsBetter: false for expense rows — a positive difference (bill went up) must be
        // unfavorable, matching this file's own comparisonRow logic under test via its inputs.
        let current: Decimal = 180
        let scenarioUp: Decimal = 250
        let differenceUp = scenarioUp - current
        XCTAssertTrue((differenceUp > 0) == true, "an increase must produce a positive difference number")
        let scenarioDown: Decimal = 100
        let differenceDown = scenarioDown - current
        XCTAssertTrue((differenceDown > 0) == false, "a decrease must produce a negative difference number")
    }

    func testPhase4IncomeIncreaseDecreaseColorSemanticsCorrect() {
        let current: Decimal = 3000
        let scenarioUp: Decimal = 3500
        XCTAssertGreaterThan(scenarioUp - current, 0, "income increase must be a positive (favorable) difference")
        let scenarioDown: Decimal = 2500
        XCTAssertLessThan(scenarioDown - current, 0, "income decrease must be a negative (unfavorable) difference")
    }

    func testPhase4SavingsGoalIncreaseDecreaseSemanticsCorrect() {
        let settings = MonthlyPlanSettings(monthlySavingsGoal: 1000)
        let viewModel = makePhase4Fixture(planSettings: settings)
        viewModel.changeMonthlySavingsGoal(1500)
        XCTAssertLessThan(viewModel.scenarioSummary.flexibleSpendingAvailable, viewModel.currentSummary.flexibleSpendingAvailable, "a higher savings goal must reduce flexible spending")
    }

