    // MARK: - Scenario Builder Phase 4 Corrective Review

    /// Shared fixture for the corrective-review test cluster: total monthly income is known
    /// (Salary 5000 + End Bonus 400 = 5400), Beginning/Mid-Month/End-of-Month bills are each
    /// distinct amounts, and the Monthly Savings Goal is nonzero (600).
    private func makeCorrectiveFixture() -> MonthlyPlanScenarioViewModel {
        let income = [
            IncomeSource(name: "Salary", amount: 5000, frequency: .monthly, timing: .beginningMonth),
            IncomeSource(name: "End Bonus", amount: 400, frequency: .monthly, timing: .endMonth)
        ]
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1500, frequency: .monthly, timing: .beginningMonth),
            RecurringExpense(name: "Phone", amount: 80, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 300, frequency: .monthly, timing: .endMonth)
        ]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: 600)
        return makePhase4Fixture(incomeSources: income, recurringExpenses: expenses, planSettings: settings)
    }

    // Required test coverage 1-6

    func testCorrectiveMidMonthRemainingMoneyDoesNotDoubleCountMidMonthBills() {
        let viewModel = makeCorrectiveFixture()
        // Eligible (Beginning+Mid): income 5000, expenses 1500+80=1580. 5000-1580-600-0 = 2820.
        XCTAssertEqual(viewModel.currentExtraSpendingAfter(.midMonth), 2820)
        // Proof against double-counting: this is NOT flexibleSpendingAvailable (which subtracts
        // ALL bills including End-of-Month Insurance) minus the Mid-Month bill total a second time.
        let doubleCountedValue = viewModel.currentSummary.flexibleSpendingAvailable - viewModel.currentTiming(.midMonth).expenses
        XCTAssertNotEqual(viewModel.currentExtraSpendingAfter(.midMonth), doubleCountedValue, "must not match the old double-counting formula")
    }

    func testCorrectiveEndOfMonthRemainingMoneyDoesNotDoubleCountAnyBills() {
        let viewModel = makeCorrectiveFixture()
        // 5400 (all income) - 1880 (all bills: 1500+80+300) - 600 (goal) - 0 (buffer) = 2920.
        XCTAssertEqual(viewModel.currentSummary.flexibleSpendingAvailable, 2920)
        XCTAssertEqual(viewModel.currentExtraSpendingAfter(.endMonth), 2920, "End-of-Month must equal the true whole-month figure, each bill counted exactly once")
    }

    func testCorrectiveEndOfMonthBillChangeDoesNotAffectMidMonthCutoff() {
        let viewModel = makeCorrectiveFixture()
        let beforeMidMonth = viewModel.currentExtraSpendingAfter(.midMonth)
        let insurance = viewModel.changeableFixedBills(timingFilter: .endMonth).first!
        viewModel.changeItemAmount(insurance.id, newAmount: 1000)
        XCTAssertEqual(viewModel.scenarioExtraSpendingAfter(.midMonth), beforeMidMonth, "an End-of-Month-only change must never move the Mid-Month cutoff result")
        XCTAssertNotEqual(viewModel.scenarioExtraSpendingAfter(.endMonth), viewModel.currentExtraSpendingAfter(.endMonth), "but it must move the End-of-Month (whole-month) result")
    }

    func testCorrectiveMidMonthBillChangeAffectsMidMonthAndLaterResults() {
        let viewModel = makeCorrectiveFixture()
        let phone = viewModel.changeableFixedBills(timingFilter: .midMonth).first!
        viewModel.changeItemAmount(phone.id, newAmount: 180)
        // Mid-Month cutoff: 5000 - (1500+180) - 600 = 2720 (was 2820, decreased by 100 = the +100 bill increase).
        XCTAssertEqual(viewModel.scenarioExtraSpendingAfter(.midMonth), 2720)
        // End-of-Month (whole month) must also reflect the same +100 bill increase.
        XCTAssertEqual(viewModel.scenarioExtraSpendingAfter(.endMonth), viewModel.currentExtraSpendingAfter(.endMonth) - 100)
    }

    func testCorrectiveIncomeRemovalChangesBothCutoffResultsInCorrectDirection() {
        let viewModel = makeCorrectiveFixture()
        let beforeMid = viewModel.currentExtraSpendingAfter(.midMonth)
        let beforeEnd = viewModel.currentExtraSpendingAfter(.endMonth)
        let salary = viewModel.removableIncomeItems().first { $0.name == "Salary" }!
        viewModel.removeItem(salary.id)
        XCTAssertLessThan(viewModel.scenarioExtraSpendingAfter(.midMonth), beforeMid, "removing Beginning-Month income must reduce the Mid-Month cutoff (Salary is eligible there)")
        XCTAssertLessThan(viewModel.scenarioExtraSpendingAfter(.endMonth), beforeEnd, "and must also reduce the whole-month End-of-Month figure")
        XCTAssertEqual(beforeMid - viewModel.scenarioExtraSpendingAfter(.midMonth), 5000)
        XCTAssertEqual(beforeEnd - viewModel.scenarioExtraSpendingAfter(.endMonth), 5000)
    }

    func testCorrectiveSavingsGoalChangeAffectsBothCutoffResultsPerAuthoritativeRule() {
        let viewModel = makeCorrectiveFixture()
        let beforeMid = viewModel.currentExtraSpendingAfter(.midMonth)
        let beforeEnd = viewModel.currentExtraSpendingAfter(.endMonth)
        XCTAssertTrue(viewModel.changeMonthlySavingsGoal(0))
        // The full, un-prorated goal (600) is removed from BOTH cutoffs — never a fraction —
        // matching flexibleSpendingAvailable's own never-prorated treatment of the goal.
        XCTAssertEqual(viewModel.scenarioExtraSpendingAfter(.midMonth), beforeMid + 600)
        XCTAssertEqual(viewModel.scenarioExtraSpendingAfter(.endMonth), beforeEnd + 600)
    }

    // Required test coverage 7-14 (recurrence safety)

    func testCorrectiveTwiceMonthlyIsNotEstimatedFromInventedFifteenDayRule() throws {
        // INCOME SCHEDULING PHASE: Twice-Monthly is no longer unsupported — it now uses two REAL,
        // explicitly user-configured deposit days (`countTwiceMonthlyOccurrences`, resolved via
        // `MonthlyDepositDay`), never a guessed "anchor + 15 days" heuristic. The original invented
        // pattern this test guarded against (`value: 15` as a hardcoded day offset) remains fully
        // absent; the literal string "countTwiceMonthly" is no longer banned since a real,
        // legitimately-named function now exists — this test now checks for the specific invented
        // pattern rather than banning a name that's since become genuinely correct.
        //
        // EXACT-DATES PHASE renamed the underlying function from `countTwiceMonthlyOccurrences` to
        // `twiceMonthlyDates` (it now returns the actual occurrence dates, not just a count — see
        // `ScenarioDateRangeCalculator.occurrenceDates(for:start:end:calendar:)`'s own header) —
        // updated to check for the current name.
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Services/ScenarioDateRangeCalculator.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        XCTAssertFalse(source.contains("value: 15, to:"), "the invented anchor+15-days twice-monthly rule must be fully removed")
        XCTAssertTrue(source.contains("twiceMonthlyDates"), "Twice-Monthly must now be counted from real configured deposit days")
    }

    func testCorrectiveTwiceMonthlyFrequencyIsUnsupportedAndReturnsZeroNotAnEstimate() {
        // INCOME SCHEDULING PHASE: Twice-Monthly is now a fully supported FREQUENCY (the engine can
        // count it exactly, given a complete schedule) — see `isFrequencySupported`'s own updated
        // header. Per-ITEM eligibility (whether THIS item's schedule is actually complete) is the
        // new `isItemSchedulable(_:)` check, exercised by the dedicated Income Scheduling tests
        // below. An item with no configured deposit days still correctly returns 0, never a guess.
        XCTAssertTrue(ScenarioDateRangeCalculator.isFrequencySupported(.twiceMonthly))
        let incompleteItem = ScenarioLineItem(id: UUID(), name: "Pay", amount: 1000, frequency: .twiceMonthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertFalse(ScenarioDateRangeCalculator.isItemSchedulable(incompleteItem))
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: incompleteItem, start: day(2026, 6, 1), end: day(2026, 6, 30)), 0, "an incomplete schedule must be an honest zero, never a guessed nonzero value")
    }

    func testCorrectiveUnsupportedItemsAreIdentifiedNotSilentlyDropped() {
        let income = [IncomeSource(name: "Twice Monthly Pay", amount: 1000, frequency: .twiceMonthly, timing: .beginningMonth, nextPayDate: day(2026, 6, 1))]
        let items = ScenarioLineItemFactory.baseline(incomeSources: income, recurringExpenses: [])
        let unsupported = ScenarioDateRangeCalculator.unsupportedItems(in: items)
        XCTAssertEqual(unsupported.map(\.name), ["Twice Monthly Pay"])
        let totals = ScenarioDateRangeCalculator.totals(for: items, start: day(2026, 6, 1), end: day(2026, 6, 30))
        XCTAssertEqual(totals.income, 0, "the unsupported item must contribute exactly 0, never an invented estimate")
    }

    func testCorrectiveWeeklyRecurrenceStillCountsExactOccurrences() {
        let anchor = day(2026, 6, 1)
        let count = ScenarioDateRangeCalculator.occurrenceCount(anchor: anchor, frequency: .weekly, start: day(2026, 6, 1), end: day(2026, 6, 30))
        XCTAssertEqual(count, 5, "weekly recurrence — grounded in the one stored anchor date — remains supported and unchanged")
    }

    func testCorrectiveBiweeklyRecurrenceStillCountsExactOccurrences() {
        let anchor = day(2026, 6, 1)
        let count = ScenarioDateRangeCalculator.occurrenceCount(anchor: anchor, frequency: .biweekly, start: day(2026, 6, 1), end: day(2026, 6, 30))
        XCTAssertEqual(count, 3, "Jun 1, 15, 29")
    }

    func testCorrectiveMonthlyRecurrenceHandles28thThrough31stSafely() {
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(anchor: day(2026, 1, 28), frequency: .monthly, start: day(2026, 1, 1), end: day(2026, 3, 31)), 3)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(anchor: day(2026, 1, 29), frequency: .monthly, start: day(2026, 1, 1), end: day(2026, 3, 31)), 3)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(anchor: day(2026, 1, 30), frequency: .monthly, start: day(2026, 1, 1), end: day(2026, 3, 31)), 3)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(anchor: day(2026, 1, 31), frequency: .monthly, start: day(2026, 1, 1), end: day(2026, 3, 31)), 3, "Jan 31 → Calendar's own standard clamp to Feb 28 → Mar 31, never skipped or double-counted")
    }

    func testCorrectiveLeapDayBehaviorRemainsCorrect() {
        let count = ScenarioDateRangeCalculator.occurrenceCount(anchor: day(2024, 2, 29), frequency: .yearly, start: day(2024, 1, 1), end: day(2025, 12, 31))
        XCTAssertEqual(count, 2, "Feb 29 2024, then Calendar's standard Feb 28 2025 clamp for the non-leap year")
    }

    func testCorrectiveMonthAndYearBoundariesAreInclusiveAndExact() {
