    // MARK: - Scenario Builder Phase 5: True multi-modification builder, income modification, dynamic categories

    private func makePhase5Fixture() -> MonthlyPlanScenarioViewModel {
        let income = [
            IncomeSource(name: "Salary", amount: 5000, frequency: .monthly, timing: .beginningMonth),
            IncomeSource(name: "VA Income", amount: 2600, frequency: .monthly, timing: .beginningMonth)
        ]
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1500, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Electric", amount: 180, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Insurance", amount: 300, frequency: .monthly, timing: .endMonth)
        ]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: 1000)
        return makePhase4Fixture(incomeSources: income, recurringExpenses: expenses, planSettings: settings)
    }

    func testPhase5MultipleModificationsCanCoexist() {
        let viewModel = makePhase5Fixture()
        let vaIncome = viewModel.removableIncomeItems().first { $0.name == "VA Income" }!
        let electric = viewModel.changeableFixedBills(timingFilter: .midMonth).first { $0.name == "Electric" }!
        viewModel.removeItem(vaIncome.id)
        viewModel.changeMonthlySavingsGoal(0)
        viewModel.changeItemAmount(electric.id, newAmount: 240)
        XCTAssertEqual(viewModel.activeModifications.count, 3, "all three modifications must coexist simultaneously")
        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyIncome, 5000, "VA Income removal must still be in effect")
        XCTAssertEqual(viewModel.scenarioSummary.monthlySavingsGoal, 0, "the savings-goal change must still be in effect")
        XCTAssertTrue(viewModel.engine.items.contains { $0.name == "Electric" && $0.amount == 240 }, "the Electric bill change must still be in effect")
    }

