        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyIncome, 5000 + 1600, "VA Income must be reduced from 2600 to 1600, not removed entirely")
        XCTAssertEqual(viewModel.currentSummary.estimatedMonthlyIncome, 5000 + 2600, "the real/Current income must be unaffected")
    }

