    func testPhase5SavingsGoalAndIncomeChangesCombineCorrectly() {
        let viewModel = makePhase5Fixture()
        let vaIncome = viewModel.changeableIncomeItems().first { $0.name == "VA Income" }!
        XCTAssertTrue(viewModel.changeItemAmount(vaIncome.id, newAmount: 1600))
        XCTAssertTrue(viewModel.changeMonthlySavingsGoal(0))
        // Current flexible spending: (5000+2600) - (1500+180+300) - 1000 = 4620.
        XCTAssertEqual(viewModel.currentSummary.flexibleSpendingAvailable, 4620)
        // Scenario: (5000+1600) - 1980 - 0 = 4620. Net effect of -1000 income + +1000 saved goal = 0 net change.
        XCTAssertEqual(viewModel.scenarioSummary.flexibleSpendingAvailable, 4620)
    }

