        let viewModel = makePhase4Fixture(incomeSources: [income], recurringExpenses: [expense], planSettings: settings)
        viewModel.removeItem(viewModel.removableIncomeItems().first!.id)
        viewModel.changeItemAmount(viewModel.changeableFixedBills(timingFilter: .midMonth).first!.id, newAmount: 240)
