        XCTAssertEqual(income.amount, originalIncomeAmount)
        XCTAssertEqual(expense.amount, originalExpenseAmount)
        XCTAssertEqual(settings.monthlySavingsGoal, originalGoal)
        XCTAssertTrue(income.isActive)
        XCTAssertTrue(expense.isActive)
    }

