    func testPhase6EditHypotheticalIncomeUpdatesInPlaceRatherThanDuplicating() {
        let viewModel = makePhase5Fixture()
        XCTAssertTrue(viewModel.addHypotheticalIncome(name: "Freelance", amount: 400))
        XCTAssertEqual(viewModel.activeModifications.count, 1)
        let addedID = viewModel.activeModifications.first!.id

        XCTAssertTrue(viewModel.editHypotheticalIncome(id: addedID, name: "Freelance", amount: 900))

        XCTAssertEqual(viewModel.activeModifications.count, 1, "editing must replace the existing Add action, not append a second one")
        XCTAssertEqual(viewModel.activeModifications.first!.newAmount, 900)
        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyIncome, viewModel.currentSummary.estimatedMonthlyIncome + 900)
    }

