    func testPhase6DeletingOneModificationLeavesOthersActive() {
        let viewModel = makePhase5Fixture()
        let vaIncome = viewModel.removableIncomeItems().first { $0.name == "VA Income" }!
        let electric = viewModel.changeableFixedBills(timingFilter: .midMonth).first { $0.name == "Electric" }!
        viewModel.removeItem(vaIncome.id)
        viewModel.changeMonthlySavingsGoal(0)
        viewModel.changeItemAmount(electric.id, newAmount: 240)
        XCTAssertEqual(viewModel.activeModifications.count, 3)

        let goalModificationID = viewModel.activeModifications.first { $0.itemName == "Monthly Savings Goal" }!.id
        viewModel.removeModification(goalModificationID)

        XCTAssertEqual(viewModel.activeModifications.count, 2, "deleting one modification must remove ONLY that modification")
        XCTAssertEqual(viewModel.scenarioSummary.monthlySavingsGoal, viewModel.currentSummary.monthlySavingsGoal, "the deleted savings-goal change must no longer be in effect")
        XCTAssertEqual(viewModel.scenarioSummary.estimatedMonthlyIncome, 5000, "the VA Income removal (not deleted) must still be in effect")
        XCTAssertTrue(viewModel.engine.items.contains { $0.name == "Electric" && $0.amount == 240 }, "the Electric bill change (not deleted) must still be in effect")
    }

