    func testPhase7BillsTotalExplanationListsContributingBills() {
        let items = [
            ScenarioLineItem(id: UUID(), name: "Rent", amount: 1200, frequency: .monthly, timing: .midMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .expense),
            ScenarioLineItem(id: UUID(), name: "Electric", amount: 100, frequency: .monthly, timing: .midMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .expense),
            ScenarioLineItem(id: UUID(), name: "Insurance", amount: 80, frequency: .monthly, timing: .endMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .expense),
            ScenarioLineItem(id: UUID(), name: "Salary", amount: 5000, frequency: .monthly, timing: .midMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income)
        ]
        let text = ScenarioSummaryText.billsTotalExplanation(for: .midMonth, items: items)
