    func testPhase7ExtraSpendingExplanationForEndMonthDescribesWholeMonth() {
        // .endMonth routes to flexibleSpendingAvailable directly (the whole-month figure) — the
        // explanation must reflect that by including EVERY included item, even ones with no
        // cutoff ordinal (.weekly/.customDate), unlike every other cutoff.
        let items = [
            ScenarioLineItem(id: UUID(), name: "Salary", amount: 5000, frequency: .monthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income),
            ScenarioLineItem(id: UUID(), name: "Gym", amount: 40, frequency: .monthly, timing: .weekly, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .expense)
        ]
        let text = ScenarioSummaryText.extraSpendingExplanation(for: .endMonth, items: items)
        XCTAssertTrue(text.contains("Salary"))
        XCTAssertTrue(text.contains("Gym"), "a weekly bill DOES count toward the whole-month End-of-Month figure, unlike Mid-Month")
        XCTAssertTrue(text.lowercased().contains("whole month"))
    }

