    // MARK: - Scenario Builder Cash-Flow Corrective Phase

    /// Scott (biweekly, $2000, anchor June 5 — one occurrence by Mid-Month, two by End-Month),
    /// Lisa (biweekly, $2000, anchor June 12 — one occurrence by Mid-Month, two by End-Month), VA
    /// (monthly, $2600, anchor June 30 — end-of-month only, zero occurrences by Mid-Month).
    /// Mortgage ($1500, anchor June 1), Electric ($180, anchor June 10), HOA Fee ($897, anchor
    /// June 12) all land at or before Mid-Month; Insurance ($300, anchor June 25) lands only by
    /// End-Month. Mid-Month: income $4000 (Scott + Lisa) − bills $2577 (Mortgage + Electric + HOA
    /// Fee) = $1423 — the exact worked example from this phase's own brief. End-Month: income
    /// $10600 (2×Scott + 2×Lisa + VA) − bills $2877 (+ Insurance) − Monthly Savings Goal.
    private func makeCashFlowFixture(monthlySavingsGoal: Decimal = 1000) -> (viewModel: MonthlyPlanScenarioViewModel, month: DateInterval) {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let income = [
            IncomeSource(name: "Scott Paycheck", amount: 2000, frequency: .biweekly, timing: .beginningMonth, nextPayDate: day(2026, 6, 5)),
            IncomeSource(name: "Lisa Paycheck", amount: 2000, frequency: .biweekly, timing: .beginningMonth, nextPayDate: day(2026, 6, 12)),
            IncomeSource(name: "VA Income", amount: 2600, frequency: .monthly, timing: .endMonth, nextPayDate: day(2026, 6, 30))
        ]
        let expenses = [
            RecurringExpense(name: "Mortgage", amount: 1500, frequency: .monthly, timing: .beginningMonth, dueDate: day(2026, 6, 1)),
            RecurringExpense(name: "Electric", amount: 180, frequency: .monthly, timing: .midMonth, dueDate: day(2026, 6, 10)),
            RecurringExpense(name: "HOA Fee", amount: 897, frequency: .monthly, timing: .midMonth, dueDate: day(2026, 6, 12)),
            RecurringExpense(name: "Insurance", amount: 300, frequency: .monthly, timing: .endMonth, dueDate: day(2026, 6, 25))
        ]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: monthlySavingsGoal)
        let viewModel = MonthlyPlanScenarioViewModel(
            incomeSources: income,
            recurringExpenses: expenses,
            planSettings: settings,
            weeklyBudgetLimit: 0,
            transactions: [],
            month: month,
            weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)),
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70
        )
        return (viewModel, month)
    }

    // 1. Mid-Month income includes only occurrences on or before the Mid-Month cutoff.
    func testCashFlowMidMonthIncomeIncludesOnlyOccurrencesOnOrBeforeCutoff() {
        let fixture = makeCashFlowFixture()
        let breakdown = fixture.viewModel.currentMidMonthCashFlow()
        XCTAssertEqual(breakdown.totalIncome, 4000, "Scott ($2000, June 5) + Lisa ($2000, June 12) only — VA (June 30) must not count")
        XCTAssertEqual(Set(breakdown.incomeContributors.map(\.name)), Set(["Scott Paycheck", "Lisa Paycheck"]))
    }

    // 2. MONTHLY OUTLOOK + SCENARIO PERIOD-CASH-FLOW CORRECTION: End-of-Month income is now the
    // End-of-Month PERIOD only (excludes the Mid-Month range), never cumulative from month start
    // — Scott/Lisa's FIRST deposits (already counted in Mid-Month) must not appear again here.
    func testCashFlowEndMonthPeriodIncomeExcludesMidMonthOccurrences() {
        let fixture = makeCashFlowFixture()
        let breakdown = fixture.viewModel.currentEndMonthCashFlow()
        XCTAssertEqual(breakdown.totalIncome, 6600, "Scott's 2nd (June 19, $2000) + Lisa's 2nd (June 26, $2000) + VA (June 30, $2600) = $6600 — never $10600")
        XCTAssertEqual(Set(breakdown.incomeContributors.map(\.name)), Set(["Scott Paycheck", "Lisa Paycheck", "VA Income"]))
    }

    // 3. End-Month-only VA income does not affect Mid-Month cash flow.
    func testCashFlowEndMonthOnlyVAIncomeDoesNotAffectMidMonth() {
        let fixture = makeCashFlowFixture()
        XCTAssertFalse(fixture.viewModel.currentMidMonthCashFlow().incomeContributors.contains { $0.name == "VA Income" })
    }

    // 4. Removing VA income changes End-Month but not Mid-Month.
    func testCashFlowRemovingVAChangesEndMonthNotMidMonth() {
        let fixture = makeCashFlowFixture()
        let beforeMidMonth = fixture.viewModel.scenarioMidMonthCashFlow().totalIncome
        let beforeEndMonth = fixture.viewModel.scenarioEndMonthCashFlow().totalIncome
        let va = fixture.viewModel.removableIncomeItems().first { $0.name == "VA Income" }!
        fixture.viewModel.removeItem(va.id)
        XCTAssertEqual(fixture.viewModel.scenarioMidMonthCashFlow().totalIncome, beforeMidMonth, "Mid-Month must be unaffected — VA was never counted there")
        XCTAssertEqual(fixture.viewModel.scenarioEndMonthCashFlow().totalIncome, beforeEndMonth - 2600, "End-Month must decrease by exactly the removed VA amount")
    }

    // 5. Reducing VA from $2,600 to $1,600 changes End-Month by exactly $1,000.
    func testCashFlowReducingVAChangesEndMonthByExactlyTheDelta() {
        let fixture = makeCashFlowFixture()
        let before = fixture.viewModel.scenarioEndMonthCashFlow().totalIncome
        let va = fixture.viewModel.changeableIncomeItems().first { $0.name == "VA Income" }!
        XCTAssertTrue(fixture.viewModel.changeItemAmount(va.id, newAmount: 1600))
        XCTAssertEqual(before - fixture.viewModel.scenarioEndMonthCashFlow().totalIncome, 1000)
    }

    // 6. MONTHLY OUTLOOK + SCENARIO PERIOD-CASH-FLOW CORRECTION: Mid-Month bills are now the
    // Mid-Month Bill Group ONLY (Electric + HOA Fee, $1,077) — Mortgage (Beginning-of-Month
    // timing) is no longer included, since it belongs to a different Bill Group.
    func testCashFlowMidMonthWorkedExampleMatchesExactExpectedRemaining() {
        let fixture = makeCashFlowFixture()
        let breakdown = fixture.viewModel.currentMidMonthCashFlow()
        XCTAssertEqual(breakdown.totalIncome, 4000)
        XCTAssertEqual(breakdown.totalBills, 1077, "Electric ($180) + HOA Fee ($897) — the Mid-Month Bill Group only")
        XCTAssertNil(breakdown.savingsAllocated, "Mid-Month has no established partial-month savings rule")
        XCTAssertEqual(breakdown.remaining, 2923)
    }

    // 7. Mid-Month bills are counted exactly once, using the Bill Group (never date-occurrence).
    func testCashFlowMidMonthBillsCountedExactlyOnce() {
        let fixture = makeCashFlowFixture()
        let breakdown = fixture.viewModel.currentMidMonthCashFlow()
        XCTAssertEqual(breakdown.billContributors.filter { $0.name == "Electric" }.count, 1)
        XCTAssertEqual(breakdown.billContributors.filter { $0.name == "HOA Fee" }.count, 1)
        XCTAssertEqual(breakdown.totalBills, 1077)
    }

    // 8. End-Month bills are counted exactly once, using the End-of-Month Bill Group only.
    func testCashFlowEndMonthBillsCountedExactlyOnce() {
        let fixture = makeCashFlowFixture()
        let breakdown = fixture.viewModel.currentEndMonthCashFlow()
        XCTAssertEqual(breakdown.billContributors.filter { $0.name == "Insurance" }.count, 1)
        XCTAssertEqual(breakdown.totalBills, 300, "Insurance ($300) — the End-of-Month Bill Group only")
    }

    // 9. MONTHLY OUTLOOK + SCENARIO PERIOD-CASH-FLOW CORRECTION (Part 6): a Beginning-of-Month
    // bill must NOT appear in either period card — period cards use the Bill Group exclusively,
    // never a cumulative through-cutoff total that would re-include an earlier timing group.
    func testCashFlowBeginningBillsExcludedFromBothPeriodCards() {
        let fixture = makeCashFlowFixture()
        XCTAssertFalse(fixture.viewModel.currentMidMonthCashFlow().billContributors.contains { $0.name == "Mortgage" })
        XCTAssertFalse(fixture.viewModel.currentEndMonthCashFlow().billContributors.contains { $0.name == "Mortgage" }, "a Beginning-of-Month bill must never appear in the End-of-Month period card")
    }

    // 10. End-Month bills do not affect the Mid-Month result.
    func testCashFlowEndMonthBillsDoNotAffectMidMonthResult() {
        let fixture = makeCashFlowFixture()
        XCTAssertFalse(fixture.viewModel.currentMidMonthCashFlow().billContributors.contains { $0.name == "Insurance" }, "Insurance (due June 25) must not count toward Mid-Month")
        XCTAssertTrue(fixture.viewModel.currentEndMonthCashFlow().billContributors.contains { $0.name == "Insurance" })
    }

