    // 18. SCENARIO MONTHLY PLANNING CORRECTION (Part 2) — the Monthly Savings Goal is no longer
    // allocated inside the End-of-Month Period card at all, so a Savings Goal change now has ZERO
    // effect on End-of-Month Remaining (it only affects Available After Planned Savings, at the
    // monthly level — see the SCENARIO MONTHLY PLANNING CORRECTION test block).
    func testCashFlowSavingsGoalChangeReleasesExactAmountAtEndMonth() {
        let fixture = makeCashFlowFixture(monthlySavingsGoal: 1000)
        let before = fixture.viewModel.scenarioEndMonthCashFlow().remaining
        XCTAssertTrue(fixture.viewModel.changeMonthlySavingsGoal(0))
        XCTAssertEqual(fixture.viewModel.scenarioEndMonthCashFlow().remaining - before, 0, "the Monthly Savings Goal must never move End-of-Month Period Remaining")
        // Mid-Month has no established savings rule — unaffected either way.
        XCTAssertNil(fixture.viewModel.scenarioMidMonthCashFlow().savingsAllocated)
        XCTAssertNil(fixture.viewModel.scenarioEndMonthCashFlow().savingsAllocated, "End-of-Month no longer allocates the goal inside its own Breakdown")
    }

    // 19. SCENARIO MONTHLY PLANNING CORRECTION — combining VA removal and a Savings Goal change now
    // produces only the income effect on End-of-Month Remaining; the goal itself contributes $0
    // here (it moves Available After Planned Savings instead, at the monthly level).
    func testCashFlowCombiningVARemovalAndSavingsGoalZeroProducesExactNetEffect() {
        let fixture = makeCashFlowFixture(monthlySavingsGoal: 1000)
        let baselineEndRemaining = fixture.viewModel.currentEndMonthCashFlow().remaining
        let va = fixture.viewModel.removableIncomeItems().first { $0.name == "VA Income" }!
        fixture.viewModel.removeItem(va.id)
        XCTAssertTrue(fixture.viewModel.changeMonthlySavingsGoal(0))
        // Net effect: -2600 (VA removed) + 0 (savings goal no longer applies inside this period) = -2600.
        XCTAssertEqual(fixture.viewModel.scenarioEndMonthCashFlow().remaining, baselineEndRemaining - 2600)
    }

