        let viewModel = MonthlyPlanScenarioViewModel(
            incomeSources: [income], recurringExpenses: [expense], planSettings: settings, weeklyBudgetLimit: 0,
            transactions: [], month: month, weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)),
            weekStartsOnSunday: true, includePending: true, warningThreshold: 0.70
        )
        viewModel.removeItem(viewModel.removableIncomeItems().first!.id)
        XCTAssertTrue(viewModel.changeItemAmount(viewModel.changeableFixedBills(timingFilter: nil).first!.id, newAmount: 999))
        XCTAssertTrue(viewModel.changeMonthlySavingsGoal(0))
