    // MARK: - Income Scheduling Phase: complete deposit-schedule model

    // -- Model and migration (1-9) --

    func testIncomeSchedulingExistingWeeklyRecordRemainsReadable() {
        let source = IncomeSource(name: "Gig", amount: 200, frequency: .weekly, nextPayDate: day(2026, 6, 5))
        XCTAssertEqual(source.frequency, .weekly)
        XCTAssertEqual(source.nextPayDate, day(2026, 6, 5))
    }

    func testIncomeSchedulingExistingBiweeklyRecordRemainsReadable() {
        let source = IncomeSource(name: "Paycheck", amount: 2000, frequency: .biweekly, nextPayDate: day(2026, 6, 5))
        XCTAssertEqual(source.frequency, .biweekly)
        XCTAssertEqual(source.nextPayDate, day(2026, 6, 5))
    }

    func testIncomeSchedulingExistingMonthlyRecordRemainsReadable() {
        let source = IncomeSource(name: "Pension", amount: 1500, frequency: .monthly, dayOfMonth: 1, nextPayDate: day(2026, 6, 1))
        XCTAssertEqual(source.frequency, .monthly)
        XCTAssertEqual(source.dayOfMonth, 1)
    }

    func testIncomeSchedulingExistingYearlyRecordRemainsReadable() {
        let source = IncomeSource(name: "Bonus", amount: 5000, frequency: .yearly, nextPayDate: day(2026, 6, 10))
        XCTAssertEqual(source.frequency, .yearly)
        XCTAssertEqual(source.nextPayDate, day(2026, 6, 10))
    }

    func testIncomeSchedulingExistingTwiceMonthlyRecordWithOneDateIsMarkedIncomplete() {
        // A pre-this-phase Twice-Monthly record only ever had `nextPayDate` — neither new day
        // field was ever set.
        let source = IncomeSource(name: "Pension", amount: 1500, frequency: .twiceMonthly, nextPayDate: day(2026, 6, 1))
        XCTAssertFalse(source.isTwiceMonthlyScheduleComplete)
    }

    func testIncomeSchedulingNoUnknownSecondDateIsFabricated() {
        let source = IncomeSource(name: "Pension", amount: 1500, frequency: .twiceMonthly, nextPayDate: day(2026, 6, 1))
        XCTAssertNil(source.twiceMonthlyFirstDeposit)
        XCTAssertNil(source.twiceMonthlySecondDeposit)
    }

    func testIncomeSchedulingNewTwiceMonthlyDefaultsToFirstAndFifteenthOnlyThroughNewRecordPath() {
        // The 1st/15th default is a UI-layer concern (AddEditIncomeSourceView's own init) for a
        // brand-new record only — the model itself never fabricates a default; explicit
        // configuration is what makes a schedule complete.
        let source = IncomeSource(
            name: "Pension", amount: 1500, frequency: .twiceMonthly,
            twiceMonthlyFirstDayNumber: 1, twiceMonthlySecondDayNumber: 15
        )
        XCTAssertEqual(source.twiceMonthlyFirstDeposit, .numericDay(1))
        XCTAssertEqual(source.twiceMonthlySecondDeposit, .numericDay(15))
        XCTAssertTrue(source.isTwiceMonthlyScheduleComplete)
    }

    func testIncomeSchedulingUserAUserBScheduleIsolation() {
        let contextA = makeAutosaveTestContext()
        let contextB = makeAutosaveTestContext()
        let sourceA = IncomeSource(name: "A Pay", amount: 1000, frequency: .twiceMonthly, twiceMonthlyFirstDayNumber: 1, twiceMonthlySecondDayNumber: 15)
        contextA.insert(sourceA)
        try! contextA.save()

        let fetchedB = try! contextB.fetch(FetchDescriptor<IncomeSource>())
        XCTAssertTrue(fetchedB.isEmpty, "User B's isolated context must never see User A's income schedule")
    }

    func testIncomeSchedulingSignOutStoreDetachRemainsSafe() {
        // Simulates detach-and-reattach: the same schedule fields must read back identically from
        // a freshly-opened context against the same underlying data, with no crash and no loss.
        let source = IncomeSource(name: "Pension", amount: 1500, frequency: .twiceMonthly, twiceMonthlyFirstDayNumber: 1, twiceMonthlySecondDayNumber: 15)
        let context = makeAutosaveTestContext()
        context.insert(source)
        try! context.save()
        let refetched = try! context.fetch(FetchDescriptor<IncomeSource>()).first!
        XCTAssertTrue(refetched.isTwiceMonthlyScheduleComplete)
    }

    // -- Weekly (10-13) --

    func testIncomeSchedulingWeeklySevenDayRecurrence() {
        let item = ScenarioLineItem(id: UUID(), name: "Gig", amount: 200, frequency: .weekly, timing: .weekly, referenceDate: day(2026, 6, 1), isIncluded: true, isHypothetical: false, ledger: .income)
        let count = ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 6, 1), end: day(2026, 6, 30))
        XCTAssertEqual(count, 5, "June 1, 8, 15, 22, 29")
    }

    func testIncomeSchedulingWeeklyOccurrenceOnPeriodStartIncluded() {
        let item = ScenarioLineItem(id: UUID(), name: "Gig", amount: 200, frequency: .weekly, timing: .weekly, referenceDate: day(2026, 6, 1), isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 6, 1), end: day(2026, 6, 1)), 1)
    }

    func testIncomeSchedulingWeeklyOccurrenceOnPeriodEndIncluded() {
        // June 29 is a genuine occurrence (June 1 + 4×7 days); a range ending exactly there must
        // include it.
        let item = ScenarioLineItem(id: UUID(), name: "Gig", amount: 200, frequency: .weekly, timing: .weekly, referenceDate: day(2026, 6, 1), isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 6, 29), end: day(2026, 6, 29)), 1)
    }

    func testIncomeSchedulingWeeklyOutsideOccurrenceExcluded() {
        // July 6 (June 1 + 5×7 days) IS a genuine occurrence, so the excluded-range check must
        // stop short of it.
        let item = ScenarioLineItem(id: UUID(), name: "Gig", amount: 200, frequency: .weekly, timing: .weekly, referenceDate: day(2026, 6, 1), isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 7, 1), end: day(2026, 7, 5)), 0)
    }

