    func testIncomeSchedulingTwiceMonthlyNumeric31ClampsInFebruary() {
        let item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .twiceMonthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income, twiceMonthlyFirstDeposit: .numericDay(1), twiceMonthlySecondDeposit: .numericDay(31))
        // Feb 2026 (non-leap) has 28 days — the 31st clamps to Feb 28.
        let count = ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 2, 28), end: day(2026, 2, 28))
        XCTAssertEqual(count, 1, "the clamped 31st must land on Feb 28")
    }

    func testIncomeSchedulingTwiceMonthlyLastDayResolvesInLeapAndNonLeapYears() {
        XCTAssertEqual(MonthlyDepositDay.lastDayOfMonth.resolvedDate(inMonthContaining: day(2024, 2, 1)), day(2024, 2, 29), "2024 is a leap year")
        XCTAssertEqual(MonthlyDepositDay.lastDayOfMonth.resolvedDate(inMonthContaining: day(2026, 2, 1)), day(2026, 2, 28), "2026 is not a leap year")
    }

    func testIncomeSchedulingTwoRulesClampingToSameDateCountOnce() {
        // 30th and 31st both clamp to Feb 28 in a non-leap year — the DUPLICATE-OCCURRENCE RULE.
        let item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .twiceMonthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income, twiceMonthlyFirstDeposit: .numericDay(30), twiceMonthlySecondDeposit: .numericDay(31))
        let count = ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 2, 1), end: day(2026, 2, 28))
        XCTAssertEqual(count, 1, "both configured days resolve to the same Feb 28 — one occurrence, not two")
    }

    func testIncomeSchedulingDifferentDatesInLongerMonthCountTwice() {
        // The SAME 30th/31st pair, in a 31-day month, resolves to two genuinely different dates.
        let item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .twiceMonthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income, twiceMonthlyFirstDeposit: .numericDay(30), twiceMonthlySecondDeposit: .numericDay(31))
        let count = ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 1, 1), end: day(2026, 1, 31))
        XCTAssertEqual(count, 2, "January has both the 30th and the 31st as distinct dates")
    }

    func testIncomeSchedulingIncompleteLegacyScheduleIsExcludedAndDisclosed() {
        let item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .twiceMonthly, timing: .beginningMonth, referenceDate: day(2026, 6, 1), isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertFalse(ScenarioDateRangeCalculator.isItemSchedulable(item))
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 6, 1), end: day(2026, 6, 30)), 0)
        XCTAssertTrue(ScenarioCashFlowCalculator.excludedItems(in: [item]).contains { $0.id == item.id })
    }

    func testIncomeSchedulingCompletingScheduleImmediatelyMakesItEligible() {
        var item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .twiceMonthly, timing: .beginningMonth, referenceDate: day(2026, 6, 1), isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertFalse(ScenarioDateRangeCalculator.isItemSchedulable(item))
        item.twiceMonthlyFirstDeposit = .numericDay(1)
        item.twiceMonthlySecondDeposit = .numericDay(15)
        XCTAssertTrue(ScenarioDateRangeCalculator.isItemSchedulable(item))
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 6, 1), end: day(2026, 6, 30)), 2)
    }

