        let item = ScenarioLineItem(id: UUID(), name: "VA", amount: 2600, frequency: .monthly, timing: .endMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income, monthlyDepositDay: .lastDayOfMonth)
        let count = ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 6, 30), end: day(2026, 6, 30))
        XCTAssertEqual(count, 1)
    }

    func testIncomeSchedulingMonthlyDay31Clamping() {
        // Jan 31 → Feb 28 → the NEXT month (Mar) must independently resolve to Mar 31, not drift
        // to Mar 28 via cumulative stepping from the clamped Feb date.
        let item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .monthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income, monthlyDepositDay: .numericDay(31))
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 2, 28), end: day(2026, 2, 28)), 1, "clamps to Feb 28")
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 3, 31), end: day(2026, 3, 31)), 1, "March must independently resolve to the 31st, not drift to the 28th")
    }

    func testIncomeSchedulingMonthlyFebruaryLeapBehavior() {
        let item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .monthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income, monthlyDepositDay: .numericDay(30))
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2024, 2, 29), end: day(2024, 2, 29)), 1, "2024 leap year clamps the 30th to Feb 29")
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 2, 28), end: day(2026, 2, 28)), 1, "2026 non-leap year clamps the 30th to Feb 28")
    }

    func testIncomeSchedulingMonthlyExactlyOneOccurrencePerMonth() {
        let item = ScenarioLineItem(id: UUID(), name: "Pension", amount: 1500, frequency: .monthly, timing: .beginningMonth, referenceDate: nil, isIncluded: true, isHypothetical: false, ledger: .income, monthlyDepositDay: .numericDay(10))
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2026, 1, 1), end: day(2026, 6, 30)), 6, "once each in Jan-Jun")
    }

