    func testIncomeSchedulingYearlyExactAnnualDate() {
        let item = ScenarioLineItem(id: UUID(), name: "Bonus", amount: 5000, frequency: .yearly, timing: .beginningMonth, referenceDate: day(2026, 6, 10), isIncluded: true, isHypothetical: false, ledger: .income)
