        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2027, 1, 1), end: day(2027, 6, 9)), 0)
    }

    func testIncomeSchedulingYearlyFebruary29ClampsInNonLeapYears() {
        let item = ScenarioLineItem(id: UUID(), name: "Bonus", amount: 5000, frequency: .yearly, timing: .beginningMonth, referenceDate: day(2024, 2, 29), isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2024, 2, 29), end: day(2024, 2, 29)), 1, "2024 is leap — exact Feb 29")
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2025, 2, 28), end: day(2025, 2, 28)), 1, "2025 is not leap — clamps to Feb 28")
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2028, 2, 29), end: day(2028, 2, 29)), 1, "2028 is leap again — must independently show Feb 29, not stay drifted at the 28th")
    }

    func testIncomeSchedulingYearlyExactlyOneOccurrencePerYear() {
        let item = ScenarioLineItem(id: UUID(), name: "Bonus", amount: 5000, frequency: .yearly, timing: .beginningMonth, referenceDate: day(2024, 6, 10), isIncluded: true, isHypothetical: false, ledger: .income)
        XCTAssertEqual(ScenarioDateRangeCalculator.occurrenceCount(for: item, start: day(2024, 1, 1), end: day(2026, 12, 31)), 3, "once each in 2024, 2025, 2026")
    }

