    func testIncomeSchedulingOneTimeNotAvailableForNewRecurringIncome() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/MonthlyPlan/AddEditIncomeSourceView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        XCTAssertTrue(source.contains("frequencyOptions"), "the Frequency picker must filter its own options")
        XCTAssertTrue(source.contains("$0 != .oneTime"), "One-Time must be excluded from the selectable options for new income")
    }

