    }

    func testIncomeSchedulingWeeklyShowsOneDateField() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/MonthlyPlan/AddEditIncomeSourceView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        // SCHEDULE UX PHASE: Weekly and Biweekly each get their own explanatory text (7-day vs.
        // 14-day recurrence) even though they share the same field title, so the switch no longer
        // combines them into one `case .weekly, .biweekly:` — updated to check the actual title.
        XCTAssertTrue(source.contains("case .weekly:\n                    nextDepositDateField(title: \"First or Next Deposit Date\")"))
    }

