    func testIncomeSchedulingDuplicateTwiceMonthlyDaySelectionIsRejected() {
        let messages = AutosaveCommitter.incomeSourceValidationMessages(
            name: "Pension", amount: 1500, frequency: .twiceMonthly, hasNextPayDate: false,
            twiceMonthlyFirstDeposit: .numericDay(15), twiceMonthlySecondDeposit: .numericDay(15)
        )
        XCTAssertTrue(messages.contains { $0.contains("must be different") })
    }

    func testIncomeSchedulingIncompleteRequiredSchedulePreventsSave() {
        let monthlyMessages = AutosaveCommitter.incomeSourceValidationMessages(name: "Pension", amount: 1500, frequency: .monthly, hasNextPayDate: false, monthlyDepositDay: nil)
        XCTAssertFalse(monthlyMessages.isEmpty, "Monthly with no deposit day configured must block Save")

        let twiceMonthlyMessages = AutosaveCommitter.incomeSourceValidationMessages(name: "Pension", amount: 1500, frequency: .twiceMonthly, hasNextPayDate: false, twiceMonthlyFirstDeposit: nil, twiceMonthlySecondDeposit: nil)
        XCTAssertFalse(twiceMonthlyMessages.isEmpty, "Twice-Monthly with neither day configured must block Save")

        let weeklyMessages = AutosaveCommitter.incomeSourceValidationMessages(name: "Gig", amount: 200, frequency: .weekly, hasNextPayDate: false)
        XCTAssertFalse(weeklyMessages.isEmpty, "Weekly with no next deposit date must block Save")
    }

    func testIncomeSchedulingAmountRemainsAmountPerDeposit() {
        // Biweekly $2000 must remain exactly $2000 per deposit — never annualized/averaged —
        // exactly the amount stored and the amount used per occurrence.
        let source = IncomeSource(name: "Scott", amount: 2000, frequency: .biweekly, nextPayDate: day(2026, 6, 5))
        XCTAssertEqual(source.amount, 2000)
        let item = ScenarioLineItemFactory.baseline(incomeSources: [source], recurringExpenses: []).first!
        XCTAssertEqual(item.amount, 2000, "the per-occurrence amount used by the scheduling engine must be the raw per-deposit amount, never a monthly-equivalent conversion")
    }

    // -- Cash flow (47-56) --

    private func makeIncomeSchedulingCashFlowFixture(vaAmount: Decimal = 2600) -> (viewModel: MonthlyPlanScenarioViewModel, month: DateInterval) {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let income = [
            IncomeSource(name: "Scott Paycheck", amount: 2000, frequency: .biweekly, nextPayDate: day(2026, 6, 5)),
            IncomeSource(name: "Lisa Paycheck", amount: 2000, frequency: .biweekly, nextPayDate: day(2026, 6, 12)),
            IncomeSource(name: "VA Disability", amount: vaAmount, frequency: .monthly, monthlyDepositDayIsLastDay: true)
        ]
        let viewModel = MonthlyPlanScenarioViewModel(
            incomeSources: income, recurringExpenses: [], planSettings: MonthlyPlanSettings(monthlySavingsGoal: 0), weeklyBudgetLimit: 0,
            transactions: [], month: month, weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)),
