    private func makeSchedulePart12Fixture(monthlySavingsGoal: Decimal) -> (viewModel: MonthlyPlanScenarioViewModel, month: DateInterval) {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let income = [
            IncomeSource(name: "Beginning Income", amount: 2000, frequency: .monthly, timing: .beginningMonth, nextPayDate: day(2026, 6, 1)),
            IncomeSource(name: "Mid Income", amount: 1900, frequency: .monthly, timing: .midMonth, nextPayDate: day(2026, 6, 15)),
            IncomeSource(name: "VA Income", amount: 2600, frequency: .monthly, timing: .endMonth, nextPayDate: day(2026, 6, 30))
        ]
        let expenses = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth, dueDate: day(2026, 6, 1)),
            RecurringExpense(name: "Utilities", amount: 749, frequency: .monthly, timing: .midMonth, dueDate: day(2026, 6, 15)),
            RecurringExpense(name: "Big Bill", amount: 2333, frequency: .monthly, timing: .endMonth, dueDate: day(2026, 6, 28))
        ]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: monthlySavingsGoal)
        let viewModel = MonthlyPlanScenarioViewModel(
            incomeSources: income,
            recurringExpenses: expenses,
            planSettings: settings,
            weeklyBudgetLimit: 0,
            transactions: [],
            month: month,
            weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)),
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70
        )
        return (viewModel, month)
    }

    // MONTHLY OUTLOOK + SCENARIO PERIOD-CASH-FLOW CORRECTION: this fixture's income sources are
    // all `.monthly` (a SINGLE occurrence per month each), not `.twiceMonthly`/`.biweekly`, so
    // "Beginning Income" (June 1) and "Mid Income" (June 15) each occur exactly once, entirely
    // within the Mid-Month period — neither recurs into the End-of-Month period. Bills now use
    // the Bill Group (timing) directly, never a cumulative through-cutoff sum — updated to the
    // current, correct period-only numbers for this specific fixture (see
    // testCorrectionsScottLisaTwiceMonthlyPeriodSplitMatchesRequiredExample below for the
    // dedicated fixture matching this task's own $3,900/$6,500 worked example).
    func testSchedulePart12MidMonthFixtureMatchesRequiredNumbers() {
        let fixture = makeSchedulePart12Fixture(monthlySavingsGoal: 500)
        let breakdown = fixture.viewModel.currentMidMonthCashFlow()
        XCTAssertEqual(breakdown.totalIncome, 3900)
        XCTAssertEqual(breakdown.totalBills, 749, "Utilities only — the Mid-Month Bill Group; Rent is Beginning-of-Month timing")
        XCTAssertNil(breakdown.savingsAllocated, "no established Mid-Month partial-savings rule exists")
        XCTAssertEqual(breakdown.remaining, 3151)
    }

    func testSchedulePart12EndMonthFixtureMatchesRequiredNumbersBeforeSavings() {
        let fixture = makeSchedulePart12Fixture(monthlySavingsGoal: 500)
        let breakdown = fixture.viewModel.currentEndMonthCashFlow()
        XCTAssertEqual(breakdown.totalIncome, 2600, "VA Income only — Beginning/Mid Income's single monthly occurrences already fell in the Mid-Month period")
        XCTAssertEqual(breakdown.totalBills, 2333, "Big Bill only — the End-of-Month Bill Group")
        XCTAssertEqual(breakdown.totalIncome - breakdown.totalBills, 267, "remaining before savings")
    }

    // SCENARIO MONTHLY PLANNING CORRECTION (Part 2) — the Monthly Savings Goal is no longer
    // allocated inside the End-of-Month Period Breakdown at all; it now applies once, at the
    // monthly level, via `MonthlyPlanScenarioViewModel.currentAvailableAfterPlannedSavings`/
    // `scenarioAvailableAfterPlannedSavings` (see the SCENARIO MONTHLY PLANNING CORRECTION test
    // block). Renamed to reflect what it now proves.
    func testSchedulePart12EndMonthSavingsGoalNoLongerAppliedInsideThePeriodBreakdown() {
        let fixture = makeSchedulePart12Fixture(monthlySavingsGoal: 500)
        let breakdown = fixture.viewModel.currentEndMonthCashFlow()
        XCTAssertNil(breakdown.savingsAllocated)
        XCTAssertEqual(breakdown.remaining, 267)
    }

    // Reproduces the exact physical-device figures ($6,211 Bills Due / $4,282 End-of-Month Bills
    // Total) with a controlled fixture, proving these are two DIFFERENT correct definitions (a
    // cumulative through-month-end total vs. a single endMonth-only timing bucket) rather than a
    // double-counting defect — Part 8's own required proof.
    func testSchedulePart12PhysicalDeviceScenarioReproduced() {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let items = [
            ScenarioLineItem(id: UUID(), name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth, referenceDate: day(2026, 6, 1), isIncluded: true, isHypothetical: false, ledger: .expense, monthlyDepositDay: .numericDay(1)),
            ScenarioLineItem(id: UUID(), name: "Utilities", amount: 729, frequency: .monthly, timing: .midMonth, referenceDate: day(2026, 6, 15), isIncluded: true, isHypothetical: false, ledger: .expense, monthlyDepositDay: .numericDay(15)),
            ScenarioLineItem(id: UUID(), name: "Mortgage/CC", amount: 4282, frequency: .monthly, timing: .endMonth, referenceDate: day(2026, 6, 30), isIncluded: true, isHypothetical: false, ledger: .expense, monthlyDepositDay: .lastDayOfMonth)
        ]
        let cumulativeBillsDue = ScenarioCashFlowCalculator.endMonthCashFlow(items: items, month: month, planSettings: nil).totalBills
        let endMonthBucketOnly = items.filter { $0.timing == .endMonth }.reduce(Decimal(0)) { $0 + $1.amount }
        XCTAssertEqual(cumulativeBillsDue, 6211, "cumulative through month-end: Rent + Utilities + Mortgage/CC")
        XCTAssertEqual(endMonthBucketOnly, 4282, "the End-of-Month Bill Group is only the endMonth-timing bucket, by design")
        XCTAssertNotEqual(cumulativeBillsDue, endMonthBucketOnly, "the two figures measure genuinely different things — not a double-counting bug")
    }

    func testSchedulePart12FlexibleSpendingIsMonthlyAverageNotCutoffBased() {
        // Confirms Part 9's audit finding directly against MonthlyPlanCalculator: Flexible
        // Spending uses frequency-to-monthly-equivalent conversion, so it does NOT move when only
        // a real actual-date cash-flow input (e.g. adding a mid-month-only expense) changes the
        // Mid-Month/End-of-Month Cash Flow cards without changing the underlying monthly total.
        let income = [IncomeSource(name: "Paycheck", amount: 2000, frequency: .monthly, timing: .beginningMonth, nextPayDate: day(2026, 6, 1))]
        let expenses = [RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth, dueDate: day(2026, 6, 1))]
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let monthlyIncome = MonthlyPlanCalculator.estimatedMonthlyIncome(income, in: month)
        let monthlyExpenses = MonthlyPlanCalculator.estimatedMonthlyFixedExpenses(expenses, in: month)
        XCTAssertEqual(monthlyIncome, 2000)
        XCTAssertEqual(monthlyExpenses, 1200)
        let flexible = MonthlyPlanCalculator.flexibleSpendingAvailable(income: monthlyIncome, fixedExpenses: monthlyExpenses, savingsGoal: 100, bufferAmount: 0)
        XCTAssertEqual(flexible, 2000 - 1200 - 100, "income - expenses - savings goal - buffer(0), a pure monthly-equivalent formula")
    }

