    // Part 11: reducing VA by $1,000 while releasing the Monthly Savings Goal by exactly $1,000
    // must net to a $0.00 End-of-Month difference — the income decrease and the savings-goal
    // decrease exactly cancel in the `remaining` formula.
    // SCENARIO MONTHLY PLANNING CORRECTION (Part 2) — the Monthly Savings Goal no longer applies
    // inside the End-of-Month Period Breakdown, so releasing it here has ZERO effect on this
    // period's Remaining — only the $1,000 income reduction moves it now.
    func testExactDatesVAAndSavingsGoalCombinedNetsToZeroEndMonthDifference() {
        let fixture = makeExactDatesCombineFixture(vaAmount: 2600, monthlySavingsGoal: 1000)
        let before = fixture.viewModel.currentEndMonthCashFlow().remaining
        XCTAssertTrue(fixture.viewModel.changeItemAmount(fixture.vaID, newAmount: 1600))
        XCTAssertTrue(fixture.viewModel.changeMonthlySavingsGoal(0))
        let after = fixture.viewModel.scenarioEndMonthCashFlow().remaining
        XCTAssertEqual(after - before, -1000, "the Savings Goal release no longer offsets anything inside this period card — only the $1,000 income reduction moves Remaining")
    }

    func testExactDatesVAReducedAloneChangesEndMonthByExactlyOneThousand() {
        let fixture = makeExactDatesCombineFixture(vaAmount: 2600, monthlySavingsGoal: 1000)
        let before = fixture.viewModel.currentEndMonthCashFlow().remaining
        XCTAssertTrue(fixture.viewModel.changeItemAmount(fixture.vaID, newAmount: 1600))
        let after = fixture.viewModel.scenarioEndMonthCashFlow().remaining
        XCTAssertEqual(before - after, 1000)
    }

    // Part 12/15: Scott and Lisa, each Every-2-Weeks with one real anchor date, must produce ONE
    // Contributor row PER ACTUAL OCCURRENCE DATE — never a single row summing two deposits into
    // one amount, and never an assumption of exactly one deposit per person per month.
    func testExactDatesScottLisaContributorsListEachOccurrenceDateSeparately() {
        let month = DateInterval(start: day(2026, 8, 1), end: day(2026, 9, 1))
        let items = [
            ScenarioLineItem(id: UUID(), name: "Scott Paycheck", amount: 2000, frequency: .biweekly, timing: .beginningMonth, referenceDate: day(2026, 8, 7), isIncluded: true, isHypothetical: false, ledger: .income),
            ScenarioLineItem(id: UUID(), name: "Lisa Paycheck", amount: 1900, frequency: .biweekly, timing: .beginningMonth, referenceDate: day(2026, 8, 14), isIncluded: true, isHypothetical: false, ledger: .income)
        ]
        let breakdown = ScenarioCashFlowCalculator.endMonthCashFlow(items: items, month: month, planSettings: nil)
        let scottDates = Set(breakdown.incomeContributors.filter { $0.name == "Scott Paycheck" }.map(\.date))
        let lisaDates = Set(breakdown.incomeContributors.filter { $0.name == "Lisa Paycheck" }.map(\.date))
        XCTAssertEqual(scottDates, [day(2026, 8, 7), day(2026, 8, 21)], "Scott's two actual August deposits, 14 days apart")
        XCTAssertEqual(lisaDates, [day(2026, 8, 14), day(2026, 8, 28)], "Lisa's two actual August deposits, 14 days apart")
        XCTAssertEqual(breakdown.incomeContributors.filter { $0.name == "Scott Paycheck" }.count, 2, "two separate dated rows, never one row summing $4,000")
        XCTAssertEqual(breakdown.totalIncome, 2000 * 2 + 1900 * 2)
    }

    func testExactDatesContributorAmountIsPerDepositNeverSummed() {
        let month = DateInterval(start: day(2026, 8, 1), end: day(2026, 9, 1))
        let items = [ScenarioLineItem(id: UUID(), name: "Scott Paycheck", amount: 2000, frequency: .biweekly, timing: .beginningMonth, referenceDate: day(2026, 8, 7), isIncluded: true, isHypothetical: false, ledger: .income)]
