    }

    func testCorrectionsFixedBillsFilterTotalMatchesFilteredCollection() {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let all = [
            RecurringExpense(name: "Rent", amount: 1200, frequency: .monthly, timing: .beginningMonth),
