        XCTAssertEqual(MonthlyPlanCalculator.estimatedMonthlyFixedExpenses(midMonthOnly, in: month), 100, "the Mid-Month filter total must equal the sum of exactly the rows the filter shows")
        XCTAssertEqual(MonthlyPlanCalculator.estimatedMonthlyFixedExpenses(all, in: month), 1300, "the All total must equal the sum of every row")
