    // -- Part 6/7: Planned Monthly Spending / Additional Planned Savings / Projected Monthly Savings --

    func testCorrectionsPlannedMonthlySpendingIsWeeklyTimesFour() {
        XCTAssertEqual(MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: 692.25), 2769)
    }

    /// The task's own first required worked example: automatic $792.25/week → Projected Savings
    /// of exactly $1,000 (Planned Monthly Spending == Flexible Spending, so Additional Planned
    /// Savings is $0).
    func testCorrectionsWorkedExampleAutomaticProducesGoalOnlyProjection() {
        let flexible = Decimal(3169)
        let weekly = MonthlyPlanCalculator.automaticPlannedWeeklySpending(flexibleSpendingAvailable: flexible)
        XCTAssertEqual(weekly, Decimal(string: "792.25"))
        let monthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: weekly)
        XCTAssertEqual(monthly, flexible, "$792.25 × 4 = $3,169 exactly — automatic mode always spends every dollar of flexible spending")
        let additional = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: flexible, plannedMonthlySpending: monthly)
        XCTAssertEqual(additional, 0)
        let projected = MonthlyPlanCalculator.projectedMonthlySavingsFromPlan(monthlySavingsGoal: 1000, additionalPlannedSavings: additional)
        XCTAssertEqual(projected, 1000)
    }

    /// The task's own second required worked example: a $692.25/week custom plan → $2,769
    /// planned monthly spending, $400 additional planned savings, $1,400 projected savings.
    func testCorrectionsWorkedExampleCustomWeeklyProducesFourteenHundred() {
        let flexible = Decimal(3169)
        let weekly = Decimal(string: "692.25")!
        let monthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: weekly)
        XCTAssertEqual(monthly, 2769)
        let additional = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: flexible, plannedMonthlySpending: monthly)
        XCTAssertEqual(additional, 400)
        let projected = MonthlyPlanCalculator.projectedMonthlySavingsFromPlan(monthlySavingsGoal: 1000, additionalPlannedSavings: additional)
        XCTAssertEqual(projected, 1400)
    }

    /// Part 7's required above-limit example: $900/week plan exceeds $3,169 flexible spending —
    /// Additional Planned Savings goes negative and is never clamped.
    func testCorrectionsAboveLimitPlannedSpendingProducesNegativeAdditionalSavings() {
        let flexible = Decimal(3169)
        let monthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: 900)
        XCTAssertEqual(monthly, 3600)
        let additional = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: flexible, plannedMonthlySpending: monthly)
        XCTAssertEqual(additional, -431)
        let projected = MonthlyPlanCalculator.projectedMonthlySavingsFromPlan(monthlySavingsGoal: 1000, additionalPlannedSavings: additional)
        XCTAssertEqual(projected, 569)
    }

    func testCorrectionsNegativeProjectedSavingsIsPreservedNeverClamped() {
        let projected = MonthlyPlanCalculator.projectedMonthlySavingsFromPlan(monthlySavingsGoal: 100, additionalPlannedSavings: -500)
        XCTAssertEqual(projected, -400, "a negative planning projection must be shown honestly, never floored at zero")
    }

    func testCorrectionsPlanningFormulasUseExactDecimalNoRoundingDrift() {
        // $3,169 ÷ 4 is not exactly representable with a terminating rounder if naively rounded —
        // Decimal division must produce the exact $792.25, not $792.25000...01 or a rounded
        // $792.00/$793.00.
        let weekly = MonthlyPlanCalculator.automaticPlannedWeeklySpending(flexibleSpendingAvailable: 3169)
        XCTAssertEqual(weekly, Decimal(string: "792.25"))
        XCTAssertEqual(MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: weekly), 3169, "weekly × 4 must exactly reconstruct the original flexible spending with no drift")
    }

