    func testCorrectionsScenarioPlannedWeeklySpendingCombinesWithSavingsGoalChange() {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let viewModel = MonthlyPlanScenarioViewModel(
            incomeSources: [IncomeSource(name: "Paycheck", amount: 4000, frequency: .monthly, nextPayDate: day(2026, 6, 1))],
            recurringExpenses: [], planSettings: MonthlyPlanSettings(monthlySavingsGoal: 1000), weeklyBudgetLimit: 0, transactions: [], month: month,
            weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)), weekStartsOnSunday: true, includePending: true, warningThreshold: 0.70
        )
        XCTAssertTrue(viewModel.changePlannedWeeklySpending(692.25))
        XCTAssertTrue(viewModel.changeMonthlySavingsGoal(0))
        // Flexible spending = income(4000) - expenses(0) - goal(0, scenario override) - buffer(0) = 4000.
        XCTAssertEqual(viewModel.scenarioSummary.flexibleSpendingAvailable, 4000)
        let plannedMonthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: 692.25)
        XCTAssertEqual(viewModel.scenarioPlannedMonthlySpending, plannedMonthly)
        let expectedAdditional = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: 4000, plannedMonthlySpending: plannedMonthly)
        XCTAssertEqual(viewModel.scenarioAdditionalPlannedSavings, expectedAdditional)
        XCTAssertEqual(viewModel.scenarioProjectedMonthlySavingsPlan, expectedAdditional, "goal is 0 in this scenario, so projected savings equals additional planned savings exactly")
    }

