    // -- Part 12: Income Remove control ordering --

    func testCorrectionsIncomeRemoveEntireIncomeAppearsBelowNewAmount() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanScenarioView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let currentRange = source.range(of: "\"Current Amount\""),
              let newAmountRange = source.range(of: "\"New Amount\"", range: currentRange.upperBound..<source.endIndex),
              let removeRange = source.range(of: "\"Remove Entire Income\"", range: newAmountRange.upperBound..<source.endIndex) else {
            return XCTFail("expected Current Amount, then New Amount, then Remove Entire Income, in that source order")
        }
        XCTAssertTrue(currentRange.upperBound < newAmountRange.lowerBound)
        XCTAssertTrue(newAmountRange.upperBound < removeRange.lowerBound)
    }

