            RecurringExpense(name: "Car Insurance", amount: 400, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "AT&T", amount: 220, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Xfinity", amount: 189, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Rooms 2 Go", amount: 60, frequency: .monthly, timing: .midMonth),
            RecurringExpense(name: "Best Buy", amount: 200, frequency: .monthly, timing: .midMonth)
        ]
