    func testUrgentEachDisplayedRowContributesItsVisibleAmount() {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let bills = makePhysicalDeviceMidMonthBills()
        let entries = FixedBillsReconciliation.entries(for: bills, in: month)
        XCTAssertEqual(entries.count, 9, "no row omitted")
        for (bill, entry) in zip(bills, entries) {
            XCTAssertTrue(entry.isIncluded, "\(bill.name) must be included")
            XCTAssertNil(entry.exclusionReason)
            XCTAssertEqual(entry.normalizedAmount, bill.amount, "\(bill.name) must contribute its exact visible amount, never $40 less")
        }
    }

