        XCTAssertEqual(MonthlyPlanCalculator.estimatedMonthlyFixedExpenses([bill], in: month), 25)
        bill.amount = 65
        XCTAssertEqual(MonthlyPlanCalculator.estimatedMonthlyFixedExpenses([bill], in: month), 65, "the total is computed fresh from the live object every time, never cached")
    }

    func testUrgentScenarioBillChangeImmediatelyUpdatesScenarioTotal() {
        let fixture = makeCashFlowFixture()
        let mortgage = fixture.viewModel.changeableFixedBills(timingFilter: nil).first { $0.name == "Mortgage" }!
        let before = fixture.viewModel.fixedBillsTotal(timingFilter: nil)
