        // elsewhere. Confirms the two totals are correctly independent.
        XCTAssertEqual(fixture.viewModel.fixedBillsTotal(timingFilter: nil), before, "the Fixed Bills SELECTOR total reflects real baseline data, unaffected by a Scenario-only change")
    }

    // -- Part 3: corrected Projected Monthly Savings on the Monthly Plan top card --

    /// The task's own required physical-device example: $4,169 flexible spending → automatic
    /// $1,042.25/week → $0 additional planned savings → $0 projected savings (goal $0), NOT
    /// $4,169.
    func testUrgentPhysicalDeviceExampleProducesZeroProjectedSavings() {
        let flexible = Decimal(4169)
        let weekly = MonthlyPlanCalculator.automaticPlannedWeeklySpending(flexibleSpendingAvailable: flexible)
        XCTAssertEqual(weekly, Decimal(string: "1042.25"))
        let monthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: weekly)
        XCTAssertEqual(monthly, flexible)
        let additional = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: flexible, plannedMonthlySpending: monthly)
        XCTAssertEqual(additional, 0)
        let projected = MonthlyPlanCalculator.projectedSavingsFromPlannedSpending(monthlySavingsGoal: 0, additionalPlannedSavings: additional)
        XCTAssertEqual(projected, 0, "must never show $4,169 when the user plans to spend their full flexible amount")
    }

    /// Part 7's custom-weekly example, restated with this phase's own numbers.
    func testUrgentCustomWeeklyExampleProducesFourHundred() {
        let flexible = Decimal(4169)
