        XCTAssertEqual(additional, 400)
        XCTAssertEqual(MonthlyPlanCalculator.projectedSavingsFromPlannedSpending(monthlySavingsGoal: 0, additionalPlannedSavings: additional), 400)
        XCTAssertEqual(MonthlyPlanCalculator.projectedSavingsFromPlannedSpending(monthlySavingsGoal: 1000, additionalPlannedSavings: additional), 1400)
    }

