        XCTAssertEqual(FixedBillsTimingFilter.displayedTotal(for: filtered + filtered), 1989 * 2)
        XCTAssertEqual(FixedBillsTimingFilter.displayedTotal(for: filtered), 1989, "and the ORIGINAL nine-row list alone is not itself double-counted")
    }

