    // -- The specific divergence class this phase corrects: non-monthly frequency and one-time
    // bills not due this month must still contribute their exact DISPLAYED amount, never a
    // frequency-converted or excluded one, since the row shows the raw amount unconditionally. --

    func testFixedBillsNonMonthlyFrequencyBillContributesItsDisplayedAmountNotAConvertedOne() {
        let quarterlyBill = RecurringExpense(name: "Quarterly Fee", amount: 60, frequency: .quarterly, timing: .midMonth)
        // The OLD total formula (MonthlyPlanCalculator.estimatedMonthlyFixedExpenses) would have
        // contributed 60/3 = $20 here — a $40 gap from the $60 the row actually displays. The
        // corrected shared helper must contribute the full displayed $60.
        XCTAssertEqual(FixedBillsTimingFilter.displayAmount(for: quarterlyBill), 60)
        XCTAssertEqual(FixedBillsTimingFilter.displayedTotal(for: [quarterlyBill]), 60)
        XCTAssertNotEqual(FixedBillsTimingFilter.displayedTotal(for: [quarterlyBill]), 20, "must never silently apply a frequency conversion the row doesn't show")
    }

    func testFixedBillsOneTimeBillNotDueThisMonthStillContributesIfVisible() {
        // A one-time bill dated in a different month is still an active, visible row in the
        // filtered list (RecurringExpenseRow has no due-date gate) — the total must include it,
        // never silently drop it while it remains on screen.
        let oneTimeBill = RecurringExpense(name: "Old One-Time Charge", amount: 40, frequency: .oneTime, timing: .midMonth, dueDate: day(2025, 1, 1))
        XCTAssertEqual(FixedBillsTimingFilter.displayedTotal(for: [oneTimeBill]), 40, "must not silently exclude a visible row because its one-time date is outside the current month")
    }

