    // MARK: - MONTHLY OUTLOOK + SCENARIO PERIOD-CASH-FLOW CORRECTION

    // -- Monthly Outlook: Budgeted / Actual / Projected Savings --

    func testOutlookCustomWeeklySixFiftyProducesBudgetedTwentySixHundred() {
        XCTAssertEqual(MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: 650), 2600)
    }

    func testOutlookAutomaticWeeklyProducesBudgetedAutomaticTimesFour() {
        let flexible = Decimal(4169)
        let automaticWeekly = MonthlyPlanCalculator.automaticPlannedWeeklySpending(flexibleSpendingAvailable: flexible)
        XCTAssertEqual(MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: automaticWeekly), flexible, "automatic mode always spends every dollar of flexible spending — Budgeted equals Flexible Spending exactly")
    }

    func testOutlookZeroOverrideProducesAutomaticBudgetedAmountNotZero() {
        // PLANNED WEEKLY AUTOMATIC/ZERO CORRECTION — a $0 override no longer produces a $0
        // budgeted amount; it falls back to Automatic.
        let effective = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: 0, flexibleSpendingAvailable: 4169)
        XCTAssertEqual(effective, 4169 / 4)
        XCTAssertEqual(MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: effective), (4169 / 4) * 4)
    }

    func testOutlookAutomaticModeEqualsZeroOverride() {
        // Supersedes the old "remains distinct" rule — nil and a $0 override are now the SAME
        // effective mode.
        let automatic = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: nil, flexibleSpendingAvailable: 4169)
        let zeroOverride = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: 0, flexibleSpendingAvailable: 4169)
        XCTAssertNotEqual(automatic, 0, "automatic mode with nonzero flexible spending must not equal $0")
        XCTAssertEqual(zeroOverride, automatic, "a $0 override must produce the exact same effective amount as no override at all")
    }

    // Required current example: $4,169 − $2,600 + $0 = $1,569.
    func testOutlookRequiredCurrentExampleProducesFifteenSixtyNine() {
        let flexible = Decimal(4169)
        let plannedMonthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: 650)
        XCTAssertEqual(plannedMonthly, 2600)
        let additional = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: flexible, plannedMonthlySpending: plannedMonthly)
        XCTAssertEqual(additional, 1569)
        let projected = MonthlyPlanCalculator.projectedSavingsFromPlannedSpending(monthlySavingsGoal: 0, additionalPlannedSavings: additional)
        XCTAssertEqual(projected, 1569, "must never display $4,169")
    }

    func testOutlookDoesNotUseLegacyActualSpendingProjection() {
        // The legacy formula would report income − fixedExpenses − actualSpent — for the
        // $4,169 flexible-spending scenario with $0 actual spending so far, that's $4,169. The
        // corrected planning formula must diverge from it whenever planned spending is less than
        // the full flexible amount.
        let legacy = MonthlyPlanCalculator.projectedSavingsFromActualSpending(income: 10400, fixedExpenses: 6231, actualSpentThisMonth: 0)
        XCTAssertEqual(legacy, 4169)
        let planned = MonthlyPlanCalculator.projectedSavingsFromPlannedSpending(monthlySavingsGoal: 0, additionalPlannedSavings: 1569)
        XCTAssertNotEqual(planned, legacy)
        XCTAssertEqual(planned, 1569)
    }

    func testOutlookDashboardEqualsMonthlyPlanPlanningOutputs() {
        // Part 4: Dashboard Budgeted/Projected Savings must equal Monthly Plan's own Planned
        // Weekly Spending × 4 / Projected Monthly Savings for the SAME inputs — proven by calling
        // the exact same MonthlyPlanCalculator functions with identical inputs from "both sides."
        let flexible = Decimal(4169)
        let override: Decimal? = 650
        let monthlyPlanWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: override, flexibleSpendingAvailable: flexible)
        let dashboardWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: override, flexibleSpendingAvailable: flexible)
        XCTAssertEqual(monthlyPlanWeekly, dashboardWeekly)
        let monthlyPlanBudgeted = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: monthlyPlanWeekly)
        let dashboardBudgeted = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: dashboardWeekly)
        XCTAssertEqual(monthlyPlanBudgeted, dashboardBudgeted)
    }

    func testOutlookUserAUserBBudgetedValuesRemainIsolated() {
        let userASettings = MonthlyPlanSettings(plannedWeeklySpendingOverride: 650)
        let userBSettings = MonthlyPlanSettings(plannedWeeklySpendingOverride: 300)
        let userAWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: userASettings.plannedWeeklySpendingOverride, flexibleSpendingAvailable: 4169)
        let userBWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: userBSettings.plannedWeeklySpendingOverride, flexibleSpendingAvailable: 4169)
        XCTAssertEqual(userAWeekly, 650)
        XCTAssertEqual(userBWeekly, 300)
        XCTAssertNotEqual(userAWeekly, userBWeekly)
    }

    func testOutlookSharedSecondaryMonthlyOutlookSourcedFromSameUpsertedFields() throws {
        // Confirms the Secondary path (SharedMonthlyOutlookSection) reads the same
        // monthlyOutlookBudgeted/ProjectedSavings server fields this phase corrected the PRIMARY
        // upload of — no separate Dashboard math, no backend/DTO shape change (Part 12).
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/Dashboard/DashboardView.swift")
        XCTAssertTrue(source.contains("summary.monthlyOutlookBudgeted"))
        XCTAssertTrue(source.contains("summary.monthlyOutlookProjectedSavings"))
    }

    // -- Period income classification --

    /// Scott/Lisa `.twiceMonthly` (first deposit lands Mid-Month, second lands End-of-Month —
    /// exactly the task's own worked example), VA `.monthly` at Last Day of Month (End-of-Month
    /// only). Bills: the corrected nine-row Mid-Month fixture ($1,989) plus a single End-of-Month
    /// bill ($4,282).
    private func makePeriodCorrectionFixture(monthlySavingsGoal: Decimal) -> (viewModel: MonthlyPlanScenarioViewModel, month: DateInterval) {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let income = [
            IncomeSource(name: "Scott Paycheck", amount: 2000, frequency: .twiceMonthly, twiceMonthlyFirstDayNumber: 1, twiceMonthlySecondDayIsLastDay: true),
            IncomeSource(name: "Lisa Paycheck", amount: 1900, frequency: .twiceMonthly, twiceMonthlyFirstDayNumber: 15, twiceMonthlySecondDayIsLastDay: true),
            IncomeSource(name: "VA Income", amount: 2600, frequency: .monthly, monthlyDepositDayIsLastDay: true)
        ]
        let expenses = makeNineRowMidMonthFixedBills() + [
            RecurringExpense(name: "Credit Card", amount: 4282, frequency: .monthly, timing: .endMonth)
        ]
        let settings = MonthlyPlanSettings(monthlySavingsGoal: monthlySavingsGoal)
        let viewModel = MonthlyPlanScenarioViewModel(
            incomeSources: income, recurringExpenses: expenses, planSettings: settings, weeklyBudgetLimit: 0, transactions: [],
            month: month, weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)), weekStartsOnSunday: true,
            includePending: true, warningThreshold: 0.70
        )
        return (viewModel, month)
    }

    func testPeriodMidMonthIncludesOnlyOccurrencesAssignedToThatPeriod() {
        let fixture = makePeriodCorrectionFixture(monthlySavingsGoal: 0)
        let breakdown = fixture.viewModel.currentMidMonthCashFlow()
        XCTAssertEqual(breakdown.totalIncome, 3900, "Scott's first ($2,000) + Lisa's first ($1,900)")
        XCTAssertEqual(Set(breakdown.incomeContributors.map(\.name)), Set(["Scott Paycheck", "Lisa Paycheck"]))
    }

    func testPeriodEndOfMonthExcludesMidMonthOccurrences() {
        let fixture = makePeriodCorrectionFixture(monthlySavingsGoal: 0)
        let breakdown = fixture.viewModel.currentEndMonthCashFlow()
        XCTAssertEqual(breakdown.totalIncome, 6500, "Scott's second ($2,000) + Lisa's second ($1,900) + VA ($2,600)")
        // Neither Scott's nor Lisa's FIRST deposit (already in the Mid-Month period) may appear
        // twice — each contributes exactly one occurrence to End-of-Month.
        XCTAssertEqual(breakdown.incomeContributors.filter { $0.name == "Scott Paycheck" }.count, 1)
