        XCTAssertTrue(source.contains("correctedFixedBillsTotal: correctedFixedBillsTotal"), "the MonthlyPlanHeroCard call site must pass the corrected total through")
        XCTAssertTrue(source.contains("correctedFlexibleSpendingAvailable: correctedFlexibleSpendingAvailable"))
    }

    /// The Planning section's "Average Monthly Flexible Spending" row, the Planned Weekly Spending
