    // MARK: - PHANTOM SCENARIO FIX — hasActiveScenario, no-active-Scenario presentation, and
    // activation/deactivation
    //
    // Reproduces Scott's exact physical-device fixture: `makeMonthlyPlanningFixture(monthlySavingsGoal:
    // 0, plannedWeeklySpendingOverride: 650)` with ZERO active engine actions — Monthly Available
    // After Bills $4,129, real custom Planned Weekly Spending $650. Before this fix,
    // `scenarioWeeklyRecommendationDisplay` computed `$4,129 ÷ 4 = $1,032.25` even though no
    // modification was active; `hasActiveScenario` and its downstream gating are what this section
    // verifies.

    // -- No active Scenario --

    func testHasActiveScenarioIsFalseWithZeroActions() {
        let fixture = makeMonthlyPlanningFixture(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        XCTAssertTrue(fixture.viewModel.engine.activeActions.isEmpty)
        XCTAssertFalse(fixture.viewModel.hasActiveScenario)
    }

    /// Baseline engine items (`engine.items`/`engine.baselineItems`) are always populated — that
    /// alone must never make `hasActiveScenario` true. This is the exact defect: `engine.items`
    /// equals the real Monthly Plan restated whenever no action is active, so item COUNT can never
    /// be the active-state signal.
    func testBaselineEngineItemsDoNotCountAsActiveModifications() {
        let fixture = makeMonthlyPlanningFixture(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        XCTAssertFalse(fixture.viewModel.engine.items.isEmpty, "baseline items are always present")
        XCTAssertFalse(fixture.viewModel.engine.baselineItems.isEmpty)
        XCTAssertFalse(fixture.viewModel.hasActiveScenario, "a non-empty item list must never itself imply an active Scenario")
    }

    /// THE EXACT REPORTED BUG: with no active Scenario, `scenarioWeeklyRecommendationDisplay` (the
    /// raw, still-internally-calculating property) is $1,032.25 for this fixture — but the
    /// presentation-facing `scenarioWeekByWeekComparisons` must show $0.00 instead, never the
    /// automatic baseline.
    func testScenarioWeeklyDisplaysZeroNotTheAutomaticBaselineWithNoActiveScenario() {
        let fixture = makeMonthlyPlanningFixture(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        XCTAssertFalse(fixture.viewModel.hasActiveScenario)
        XCTAssertEqual(fixture.viewModel.scenarioWeeklyRecommendationDisplay, Decimal(string: "1032.25"), "the raw calculation itself is unchanged and still available internally")
        XCTAssertEqual(fixture.viewModel.scenarioWeekByWeekComparisons.first!.recommendedLimit, 0, "but the presentation-facing week-by-week value must never show it while no Scenario is active")
    }

    func testCurrentPlannedWeeklyRemainsTheRealCustomAmountWithNoActiveScenario() {
        let fixture = makeMonthlyPlanningFixture(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        XCTAssertFalse(fixture.viewModel.hasActiveScenario)
        XCTAssertEqual(fixture.viewModel.currentPlannedWeeklySpending, 650, "Current must always reflect the real Monthly Plan, active Scenario or not")
    }

    func testResultsCardComparisonRowGatesScenarioAndDifferenceOnHasActiveScenario() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanScenarioView.swift")
        XCTAssertTrue(source.contains("let displayedScenario = viewModel.hasActiveScenario ? scenario : 0"), "every Results comparisonRow must force the displayed Scenario to $0.00 when no Scenario is active")
        XCTAssertTrue(source.contains("let difference = viewModel.hasActiveScenario ? (scenario - current) : 0"), "Difference must be forced to $0.00 directly, never computed as $0 − Current")
    }

    func testPeriodCardsGateScenarioOnlyLinesOnHasActiveScenario() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanScenarioView.swift")
        XCTAssertTrue(source.contains("cashFlowLineRow(label: \"Income This Period\", amount: viewModel.hasActiveScenario ? scenario.totalIncome : 0"), "the Period cards' own Scenario-only Income line must respect hasActiveScenario")
        XCTAssertTrue(source.contains("cashFlowLineRow(label: billsDueRowTitle, amount: viewModel.hasActiveScenario ? scenario.totalBills : 0"), "the Period cards' own Scenario-only Bills line must respect hasActiveScenario")
    }

    func testEmptyStateMessageExistsNearResultsSection() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/MonthlyPlan/MonthlyPlanScenarioView.swift")
        XCTAssertTrue(source.contains("No Scenario changes have been added."))
