    func testRemovingTheFinalActionProducesTheNoActiveScenarioState() {
        let fixture = makeMonthlyPlanningFixture(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        let modificationID = fixture.viewModel.engine.activeActions.isEmpty ? nil : fixture.viewModel.engine.activeActions.first?.id
