        XCTAssertTrue(fixture.viewModel.changeMonthlySavingsGoal(2500))
        XCTAssertTrue(fixture.viewModel.hasActiveScenario)
        let addedID = fixture.viewModel.engine.activeActions.first!.id
        fixture.viewModel.removeModification(addedID)
        XCTAssertFalse(fixture.viewModel.hasActiveScenario, "removing the last remaining active action must return to the no-active-Scenario state")
    }

    func testNoStaleScenarioValueRemainsAfterRemovalOrReset() {
        let fixture = makeMonthlyPlanningFixture(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        XCTAssertTrue(fixture.viewModel.changeMonthlySavingsGoal(2500))
        let activatedRecommendedLimit = fixture.viewModel.scenarioWeekByWeekComparisons.first!.recommendedLimit
        XCTAssertNotEqual(activatedRecommendedLimit, 0, "sanity: the Scenario is genuinely active and produces a real recommendation")
