    func testNoWeeklySpendingAvailableOnlyAppearsWhenScenarioWeeklyAmountIsGenuinelyNonPositive() {
        // Reuses the EXISTING, unmodified isDiscretionarySpendingUnavailable formula — this phase
        // changed nothing about when the per-week message is calculated, only whether the weekly
        // card list (which is the only place it can render) is ever reachable at all.
        let zeroSpend = MonthlyPlanCalculator.WeeklyPlanComparison(weekInterval: DateInterval(start: .now, end: .now.addingTimeInterval(1)), recommendedLimit: 0, actualSpent: 0, status: .good)
        XCTAssertTrue(ScenarioSummaryText.isDiscretionarySpendingUnavailable(zeroSpend))
        let positiveRecommendation = MonthlyPlanCalculator.WeeklyPlanComparison(weekInterval: zeroSpend.weekInterval, recommendedLimit: Decimal(string: "407.25")!, actualSpent: 0, status: .good)
        XCTAssertFalse(ScenarioSummaryText.isDiscretionarySpendingUnavailable(positiveRecommendation), "must not appear once the Scenario weekly amount is genuinely positive")
    }

