    // MARK: - WEEKLY SPENDING UNIFICATION
    //
    // Reproduces the exact physical-device fixture across every test: income $10,400 (Scott
    // $2,000 twiceMonthly + Lisa $1,900 twiceMonthly + VA $2,600 monthly), Fixed Bills $6,271
    // (the established nine-row Mid-Month $1,989 + Credit Card $4,282 End-of-Month), Custom
    // Planned Weekly Spending $650. Flexible Spending Available is $4,129 at Goal $0 and $3,629 at
    // Goal $500 — both exactly matching the task's own worked examples.

    private func makeWeeklyUnificationIncomeAndBills() -> (income: [IncomeSource], bills: [RecurringExpense]) {
        let income = [
            IncomeSource(name: "Scott Paycheck", amount: 2000, frequency: .twiceMonthly, twiceMonthlyFirstDayNumber: 1, twiceMonthlySecondDayIsLastDay: true),
            IncomeSource(name: "Lisa Paycheck", amount: 1900, frequency: .twiceMonthly, twiceMonthlyFirstDayNumber: 15, twiceMonthlySecondDayIsLastDay: true),
            IncomeSource(name: "VA Income", amount: 2600, frequency: .monthly, monthlyDepositDayIsLastDay: true)
        ]
        let bills = makeNineRowMidMonthFixedBills() + [RecurringExpense(name: "Credit Card", amount: 4282, frequency: .monthly, timing: .endMonth)]
        return (income, bills)
    }

    private func makeWeeklyUnificationSummary(monthlySavingsGoal: Decimal, plannedWeeklySpendingOverride: Decimal?, transactions: [FinanceTransaction] = []) -> MonthlyPlanCalculator.Summary {
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let (income, bills) = makeWeeklyUnificationIncomeAndBills()
        let settings = MonthlyPlanSettings(monthlySavingsGoal: monthlySavingsGoal, plannedWeeklySpendingOverride: plannedWeeklySpendingOverride)
        return MonthlyPlanCalculator.summary(
            month: month,
            incomeSources: income,
            recurringExpenses: bills,
            planSettings: settings,
            weeklyBudgetLimit: 0,
            transactions: transactions,
            weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)),
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70
        )
    }

    // -- Authoritative weekly amount --

    func testEffectiveWeeklyAutomaticEqualsFlexibleDividedByFour() {
        XCTAssertEqual(MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: nil, flexibleSpendingAvailable: 4129), Decimal(string: "1032.25"))
    }

    func testEffectiveWeeklyCustomEqualsStoredCustomAmount() {
        XCTAssertEqual(MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: 650, flexibleSpendingAvailable: 4129), 650)
    }

    func testEffectiveWeeklyZeroOverrideFallsBackToAutomatic() {
        // Supersedes the old "must never fall back" rule — a $0 override IS now the automatic ÷4
        // value, exactly like no override at all.
        XCTAssertEqual(MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: 0, flexibleSpendingAvailable: 4129), 4129 / 4, "a $0 override must fall back to the automatic ÷4 value")
        XCTAssertEqual(MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: 0, flexibleSpendingAvailable: 4129), MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: nil, flexibleSpendingAvailable: 4129))
    }

    func testEffectiveWeeklySwitchingAutomaticToCustomUpdatesImmediately() {
        let summary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: nil)
        XCTAssertEqual(summary.recommendedWeeklySpendingLimit, Decimal(string: "1032.25"))
        let customSummary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        XCTAssertEqual(customSummary.recommendedWeeklySpendingLimit, 650)
    }

    func testEffectiveWeeklySwitchingCustomToAutomaticUpdatesImmediately() {
        let customSummary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        XCTAssertEqual(customSummary.recommendedWeeklySpendingLimit, 650)
        let automaticSummary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: nil)
        XCTAssertEqual(automaticSummary.recommendedWeeklySpendingLimit, Decimal(string: "1032.25"))
    }

    func testEffectiveWeeklyUserAUserBRemainIsolated() {
        let userA = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        let userB = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: nil)
        XCTAssertEqual(userA.recommendedWeeklySpendingLimit, 650)
        XCTAssertEqual(userB.recommendedWeeklySpendingLimit, Decimal(string: "1032.25"), "each summary is built from its own independent MonthlyPlanSettings — no shared mutable state between them")
    }

