    func testManualSpendingOfTwentyFivePlusImportedEightyGivesActualOneOhFiveLeftFiveFortyFive() {
        let amex = FinanceTransaction(amount: 80, date: day(2026, 6, 10), type: .expense, source: .plaid, plaidAccountId: "amex-1")
        let manual = FinanceTransaction(amount: 25, date: day(2026, 6, 11), type: .expense, source: .manual)
        let summary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650, transactions: [amex, manual])
        let thisWeek = summary.weeklyComparisons.first { $0.weekInterval.contains(day(2026, 6, 10)) }!
