    func testATransactionCountsOnceOnly() {
        let amex = FinanceTransaction(amount: 80, date: day(2026, 6, 10), type: .expense, source: .plaid, plaidAccountId: "amex-1")
        let summary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650, transactions: [amex])
        let totalAcrossAllWeeks = summary.weeklyComparisons.reduce(Decimal.zero) { $0 + $1.actualSpent }
        XCTAssertEqual(totalAcrossAllWeeks, 80, "a single $80 transaction must contribute to exactly one week's total, never every week")
    }

    func testRefundBehaviorRemainsUnchanged() {
        let expense = FinanceTransaction(amount: 100, date: day(2026, 6, 10), type: .expense, source: .manual)
        let refund = FinanceTransaction(amount: 30, date: day(2026, 6, 11), type: .refund, source: .manual)
        let summary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650, transactions: [expense, refund])
        let thisWeek = summary.weeklyComparisons.first { $0.weekInterval.contains(day(2026, 6, 10)) }!
        XCTAssertEqual(thisWeek.actualSpent, 70, "a refund reduces Actual using its existing signed behavior, unchanged by this phase")
    }

    func testPendingBehaviorRemainsUnchanged() {
        let pending = FinanceTransaction(amount: 50, date: day(2026, 6, 10), type: .expense, source: .manual, isPending: true)
        let month = DateInterval(start: day(2026, 6, 1), end: day(2026, 7, 1))
        let (income, bills) = makeWeeklyUnificationIncomeAndBills()
        let settingsWithPending = MonthlyPlanSettings(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        let includingPending = MonthlyPlanCalculator.summary(month: month, incomeSources: income, recurringExpenses: bills, planSettings: settingsWithPending, weeklyBudgetLimit: 0, transactions: [pending], weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)), weekStartsOnSunday: true, includePending: true, warningThreshold: 0.70)
        let excludingPending = MonthlyPlanCalculator.summary(month: month, incomeSources: income, recurringExpenses: bills, planSettings: settingsWithPending, weeklyBudgetLimit: 0, transactions: [pending], weekInterval: DateRangeHelper.weekRangeContaining(day(2026, 6, 10)), weekStartsOnSunday: true, includePending: false, warningThreshold: 0.70)
        XCTAssertEqual(includingPending.weeklyComparisons.first { $0.weekInterval.contains(day(2026, 6, 10)) }!.actualSpent, 50)
        XCTAssertEqual(excludingPending.weeklyComparisons.first { $0.weekInterval.contains(day(2026, 6, 10)) }!.actualSpent, 0, "the existing Include Pending setting still gates pending transactions exactly as before")
    }

    func testMonthlyPlanDashboardAndWeeklyBudgetAgreeOnWeeklyActual() {
        let amex = FinanceTransaction(amount: 80, date: day(2026, 6, 10), type: .expense, source: .plaid, plaidAccountId: "amex-1")
        let summary = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650, transactions: [amex])
        let weekInterval = DateRangeHelper.weekRangeContaining(day(2026, 6, 10))
        let monthlyPlanAndDashboardWeeklyActual = summary.weeklyComparisons.first { $0.weekInterval.contains(day(2026, 6, 10)) }!.actualSpent
        let weeklyBudgetScreenActual = BudgetCalculator.weeklySpent([amex], in: weekInterval, includePending: true)
        XCTAssertEqual(monthlyPlanAndDashboardWeeklyActual, weeklyBudgetScreenActual, "Monthly Plan/Dashboard's per-week Actual and Weekly Budget's own spentThisWeek must agree exactly — both now route through BudgetCalculator.weeklySpent")
        XCTAssertEqual(monthlyPlanAndDashboardWeeklyActual, 80)
    }

