    func testHeroCardSwitchingAutomaticToCustomUpdatesAllThreeValues() {
        let automatic = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: nil)
        let automaticWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: nil, flexibleSpendingAvailable: automatic.flexibleSpendingAvailable)
        let custom = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        let customWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: 650, flexibleSpendingAvailable: custom.flexibleSpendingAvailable)
        XCTAssertNotEqual(automaticWeekly, customWeekly)
        let automaticMonthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: automaticWeekly)
        let customMonthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: customWeekly)
        XCTAssertNotEqual(automaticMonthly, customMonthly)
        let automaticAvailable = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: automatic.flexibleSpendingAvailable, plannedMonthlySpending: automaticMonthly)
        let customAvailable = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: custom.flexibleSpendingAvailable, plannedMonthlySpending: customMonthly)
        XCTAssertNotEqual(automaticAvailable, customAvailable)
    }

    func testHeroCardSwitchingCustomToAutomaticUpdatesAllThreeValues() {
        let customWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: 650, flexibleSpendingAvailable: 4129)
        let automaticWeekly = MonthlyPlanCalculator.effectivePlannedWeeklySpending(override: nil, flexibleSpendingAvailable: 4129)
