    func testHeroCardChangingSavingsGoalUpdatesFlexibleAvailableAndSavings() {
        let goalZero = makeWeeklyUnificationSummary(monthlySavingsGoal: 0, plannedWeeklySpendingOverride: 650)
        let goalFiveHundred = makeWeeklyUnificationSummary(monthlySavingsGoal: 500, plannedWeeklySpendingOverride: 650)
        XCTAssertEqual(goalZero.flexibleSpendingAvailable, 4129)
        XCTAssertEqual(goalFiveHundred.flexibleSpendingAvailable, 3629)
        let availableZero = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: goalZero.flexibleSpendingAvailable, plannedMonthlySpending: 2600)
        let availableFiveHundred = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: goalFiveHundred.flexibleSpendingAvailable, plannedMonthlySpending: 2600)
        XCTAssertEqual(availableZero, 1529)
        XCTAssertEqual(availableFiveHundred, 1029)
        let savingsZero = MonthlyPlanCalculator.projectedMonthlySavingsFromPlan(monthlySavingsGoal: 0, additionalPlannedSavings: availableZero)
        let savingsFiveHundred = MonthlyPlanCalculator.projectedMonthlySavingsFromPlan(monthlySavingsGoal: 500, additionalPlannedSavings: availableFiveHundred)
        XCTAssertEqual(savingsZero, 1529)
        XCTAssertEqual(savingsFiveHundred, 1529, "Projected Monthly Savings stays the same — the Savings Goal amount just moved from flexible spending into the explicit goal")
    }

