    @MainActor
    func testSavingsEntryPersistsAmountAndDateCorrectly() throws {
        let context = makeSavingsEntryContext()
        let date = Date(timeIntervalSince1970: 1_800_000_000)
        let entry = SavingsEntry(amount: 250, date: date)
        context.insert(entry)
        try context.save()

        let fetched = try context.fetch(FetchDescriptor<SavingsEntry>()).first
        XCTAssertEqual(fetched?.amount, 250)
        XCTAssertEqual(fetched?.date, date)
    }

    func testSavedThisMonthSumsCurrentMonthEntries() {
        let month = DateRangeHelper.currentMonthRange()
        let entries = [
            SavingsEntry(amount: 200, date: month.start.addingTimeInterval(3600)),
            SavingsEntry(amount: 300, date: month.start.addingTimeInterval(7200)),
        ]
        XCTAssertEqual(SavingsCalculator.savedThisMonth(entries, in: month), 500, "$200 + $300 = $500")
    }

    func testSavedThisMonthExcludesPriorMonthEntries() {
        let month = DateRangeHelper.currentMonthRange()
        let lastMonth = DateRangeHelper.lastMonthRange()
        let entries = [
            SavingsEntry(amount: 500, date: lastMonth.start.addingTimeInterval(3600)),
