        XCTAssertEqual(SavingsCalculator.savedThisMonth(entries, in: month), 0, "prior-month entries must not count toward the current month")
    }

    func testTotalSavingsToDateRemainsCumulativeAcrossMonths() {
        let month = DateRangeHelper.currentMonthRange()
        let lastMonth = DateRangeHelper.lastMonthRange()
        let entries = [
            SavingsEntry(amount: 500, date: lastMonth.start.addingTimeInterval(3600)),
            SavingsEntry(amount: 750, date: month.start.addingTimeInterval(3600)),
