        XCTAssertEqual(SavingsCalculator.totalSavingsToDate(entries), 1250, "prior-month entries remain included in the all-time total")
    }

    func testMonthRolloverProducesZeroCurrentMonthTotalWithoutNewEntries() {
        let month = DateRangeHelper.currentMonthRange()
        let lastMonth = DateRangeHelper.lastMonthRange()
        let entries = [SavingsEntry(amount: 500, date: lastMonth.start.addingTimeInterval(3600))]
        XCTAssertEqual(SavingsCalculator.savedThisMonth(entries, in: month), 0)
        XCTAssertEqual(SavingsCalculator.totalSavingsToDate(entries), 500, "the July entry remains stored and still counts toward the all-time total")
    }

