    @MainActor
    func testDeleteRemovesOnlyTheSelectedSavingsEntry() throws {
        let context = makeSavingsEntryContext()
        let keep = SavingsEntry(amount: 100)
        let remove = SavingsEntry(amount: 200)
        context.insert(keep)
        context.insert(remove)
        try context.save()

        context.delete(remove)
        try context.save()

        let remaining = try context.fetch(FetchDescriptor<SavingsEntry>())
        XCTAssertEqual(remaining.count, 1)
        XCTAssertEqual(remaining.first?.amount, 100)
    }

    @MainActor
    func testDeleteRecalculatesCurrentMonthAndAllTimeTotals() throws {
        let context = makeSavingsEntryContext()
        let month = DateRangeHelper.currentMonthRange()
        let a = SavingsEntry(amount: 200, date: month.start.addingTimeInterval(3600))
        let b = SavingsEntry(amount: 300, date: month.start.addingTimeInterval(7200))
        context.insert(a)
        context.insert(b)
        try context.save()

        var entries = try context.fetch(FetchDescriptor<SavingsEntry>())
        XCTAssertEqual(SavingsCalculator.savedThisMonth(entries, in: month), 500)

        context.delete(b)
        try context.save()
        entries = try context.fetch(FetchDescriptor<SavingsEntry>())
        XCTAssertEqual(SavingsCalculator.savedThisMonth(entries, in: month), 200, "current-month total must recalculate after delete")
        XCTAssertEqual(SavingsCalculator.totalSavingsToDate(entries), 200, "all-time total must recalculate after delete")
    }

