    func testOneThousandGoalNinetySevenFiftySpendingDoesNotProduceNineHundredTwoFifty() {
        // Direct algebraic proof of the bug the old formula produced, now unreachable: the new
        // Monthly Spend Remaining formula never simply subtracts spending from the goal.
        let oldBrokenFormula = BudgetCalculator.remaining(limit: 1000, spent: 97.50)
        XCTAssertEqual(oldBrokenFormula, 902.50, "confirms this IS the exact old broken calculation")

        let moneyAfterBills = MonthlyPlanCalculator.moneyAfterBills(income: 5000, fixedExpenses: 2000)
        let spendingBudget = MonthlyPlanCalculator.monthlySpendingBudget(moneyAfterBills: moneyAfterBills, savingsGoal: 1000, bufferAmount: 0)
        let correct = MonthlyPlanCalculator.monthlySpendRemaining(monthlySpendingBudget: spendingBudget, actualMonthlySpending: 97.50)
        XCTAssertNotEqual(correct, oldBrokenFormula, "the canonical Monthly Spend Remaining must never equal the old broken goal-minus-spending figure")
    }

