    // MARK: - Monthly Spend Remaining transaction-counting preservation (BudgetCalculator reuse)

    func testMonthlySpendRemainingUsesExistingExpenseCountingRules() {
        // Locks in that Monthly Spend Remaining's actual-spending input is the SAME
        // BudgetCalculator.monthlySpent used elsewhere — expenses add, per existing rules.
        let month = DateRangeHelper.currentMonthRange()
        let expense = FinanceTransaction(amount: 500, date: month.start.addingTimeInterval(3600), type: .expense)
        let spent = BudgetCalculator.monthlySpent([expense], in: month, includePending: true)
        XCTAssertEqual(spent, 500)
        let remaining = MonthlyPlanCalculator.monthlySpendRemaining(monthlySpendingBudget: 3000, actualMonthlySpending: spent)
        XCTAssertEqual(remaining, 2500)
    }

    func testMonthlySpendRemainingUsesExistingRefundCountingRules() {
        let month = DateRangeHelper.currentMonthRange()
        let expense = FinanceTransaction(amount: 500, date: month.start.addingTimeInterval(3600), type: .expense)
        let refund = FinanceTransaction(amount: 100, date: month.start.addingTimeInterval(7200), type: .refund)
        let spent = BudgetCalculator.monthlySpent([expense, refund], in: month, includePending: true)
        XCTAssertEqual(spent, 400, "a refund must reduce monthly spending per existing BudgetCalculator rules")
    }

    func testMonthlySpendRemainingExcludesTransfers() {
        let month = DateRangeHelper.currentMonthRange()
        let transfer = FinanceTransaction(amount: 500, date: month.start.addingTimeInterval(3600), type: .transfer)
        let spent = BudgetCalculator.monthlySpent([transfer], in: month, includePending: true)
        XCTAssertEqual(spent, 0, "transfers must never contribute to Monthly Spend Remaining's actual-spending input")
    }

    func testMonthlySpendRemainingExcludesIncome() {
        let month = DateRangeHelper.currentMonthRange()
        let income = FinanceTransaction(amount: 2000, date: month.start.addingTimeInterval(3600), type: .income)
        let spent = BudgetCalculator.monthlySpent([income], in: month, includePending: true)
        XCTAssertEqual(spent, 0, "income must never contribute to Monthly Spend Remaining's actual-spending input")
    }

    func testMonthlySpendRemainingRespectsCountsTowardMonthlySpending() {
        let month = DateRangeHelper.currentMonthRange()
        let excluded = FinanceTransaction(amount: 500, date: month.start.addingTimeInterval(3600), type: .expense, countsTowardMonthlySpending: false)
        let spent = BudgetCalculator.monthlySpent([excluded], in: month, includePending: true)
        XCTAssertEqual(spent, 0, "an expense opted out of monthly spending must not affect Monthly Spend Remaining")
    }

    func testMonthlySpendRemainingRespectsIsExcludedFromReports() {
        let month = DateRangeHelper.currentMonthRange()
        let excluded = FinanceTransaction(amount: 500, date: month.start.addingTimeInterval(3600), type: .expense, isExcludedFromReports: true)
        let spent = BudgetCalculator.monthlySpent([excluded], in: month, includePending: true)
        XCTAssertEqual(spent, 0, "a report-excluded expense must not affect Monthly Spend Remaining")
    }

    func testMonthlySpendRemainingRespectsIncludePendingTransactions() {
        let month = DateRangeHelper.currentMonthRange()
        let pending = FinanceTransaction(amount: 500, date: month.start.addingTimeInterval(3600), type: .expense, isPending: true)
        let spentIncludingPending = BudgetCalculator.monthlySpent([pending], in: month, includePending: true)
        let spentExcludingPending = BudgetCalculator.monthlySpent([pending], in: month, includePending: false)
        XCTAssertEqual(spentIncludingPending, 500)
        XCTAssertEqual(spentExcludingPending, 0, "pending exclusion must be controlled by includePendingTransactions, unchanged")
    }

    func testMonthlySpendRemainingIncludesBothManualAndConnectedAccountTransactions() {
        // BudgetCalculator.monthlySpent operates on plain FinanceTransaction rows regardless of
        // source — no filtering by manual vs. Plaid-connected origin.
        let month = DateRangeHelper.currentMonthRange()
        let manual = FinanceTransaction(amount: 200, date: month.start.addingTimeInterval(3600), type: .expense, source: .manual)
        let connected = FinanceTransaction(amount: 300, date: month.start.addingTimeInterval(7200), type: .expense, source: .plaid)
        let spent = BudgetCalculator.monthlySpent([manual, connected], in: month, includePending: true)
        XCTAssertEqual(spent, 500, "both manual and connected-account transactions must count toward Monthly Spend Remaining")
    }

