            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        XCTAssertTrue(source.contains("amountRow(title: \"Monthly Remaining\", amount: monthlyRemaining"), "the This Week card must show a fourth Monthly Remaining row")
    }

    func testDashboardMonthlyRemainingUsesCanonicalCalculation() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/Dashboard/DashboardView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let range = source.range(of: "private var monthlySpendRemaining: Decimal") else {
            XCTFail("monthlySpendRemaining not found"); return
        }
        let section = String(source[range.lowerBound...].prefix(900))
        // FIXED BILLS FORMULA UNIFICATION — `moneyAfterBills`/`monthlySpendingBudget` never applied
        // Bill Payment Variance at all (that was itself part of the reported bug), so
        // `monthlySpendRemaining` now derives its budget input from
        // `correctedFlexibleSpendingAvailableForOutlook` (which already applies variance) instead
        // of re-deriving via those two functions. `MonthlyPlanCalculator.monthlySpendRemaining`
        // itself is still the one canonical function actually applying the final clamp — never
        // duplicated here.
        XCTAssertTrue(section.contains("correctedFlexibleSpendingAvailableForOutlook"), "Dashboard must derive its spending budget from the corrected, variance-adjusted baseline")
        XCTAssertTrue(section.contains("MonthlyPlanCalculator.monthlySpendRemaining"), "Dashboard must reuse the canonical calculator, never duplicate the formula")
        XCTAssertTrue(section.contains("monthlyPlanSummary."), "Dashboard must source its inputs from the existing monthlyPlanSummary, never re-query independently")
    }

    func testSavingsGoalChangeRecalculatesMonthlyRemaining() {
        let goalA = MonthlyPlanCalculator.monthlySpendingBudget(moneyAfterBills: 4000, savingsGoal: 1000, bufferAmount: 0)
        let goalB = MonthlyPlanCalculator.monthlySpendingBudget(moneyAfterBills: 4000, savingsGoal: 1500, bufferAmount: 0)
        XCTAssertNotEqual(goalA, goalB, "a Savings Goal change must change Monthly Spending Budget and therefore Monthly Spend Remaining")
    }

    func testBufferChangeRecalculatesMonthlyRemaining() {
        let bufferA = MonthlyPlanCalculator.monthlySpendingBudget(moneyAfterBills: 4000, savingsGoal: 1000, bufferAmount: 0)
        let bufferB = MonthlyPlanCalculator.monthlySpendingBudget(moneyAfterBills: 4000, savingsGoal: 1000, bufferAmount: 200)
        XCTAssertNotEqual(bufferA, bufferB, "a Buffer change must change Monthly Spending Budget and therefore Monthly Spend Remaining")
    }

    func testActualMonthlySpendingChangeRecalculatesMonthlyRemaining() {
        let remainingBefore = MonthlyPlanCalculator.monthlySpendRemaining(monthlySpendingBudget: 3000, actualMonthlySpending: 0)
        let remainingAfter = MonthlyPlanCalculator.monthlySpendRemaining(monthlySpendingBudget: 3000, actualMonthlySpending: 500)
