    // MARK: - CONNECTED ACCOUNT REFRESH CONSISTENCY —
    // PlaidConnectionManager.refreshAccountBalanceAndTransactions (one Dashboard tap now updates
    // both balance and transactions, still exactly one claimed 2/day/account event)

    private final class FakeBalanceAndTransactionsPlaidBackendService: PlaidBackendService {
        var refreshResult: Result<ConnectedAccountRefreshResult, Error>
        var syncTransactionsResult: Result<PlaidSyncResult, Error> = .success(PlaidSyncResult(added: [], modified: [], removedExternalIds: []))
        var syncBalancesResult: Result<[PlaidAccountBalance], Error> = .success([])
        private(set) var refreshConnectedAccountCallCount = 0
        private(set) var syncTransactionsCallCount = 0
        private(set) var syncBalancesCallCount = 0
        private(set) var lastSyncTransactionsConnectionId: String?

        init(refreshResult: Result<ConnectedAccountRefreshResult, Error>) {
            self.refreshResult = refreshResult
        }

        func createLinkToken(daysRequested: Int?) async throws -> String { fatalError("not used in this test") }
        func createUpdateLinkToken(connectionId: String) async throws -> String { fatalError("not used in this test") }
        func exchangePublicToken(_ publicToken: String, institutionId: String?, institutionName: String) async throws -> PlaidExchangeResult { fatalError("not used in this test") }
        func syncTransactions(connectionId: String) async throws -> PlaidSyncResult {
            syncTransactionsCallCount += 1
            lastSyncTransactionsConnectionId = connectionId
            return try syncTransactionsResult.get()
        }
        func syncBalances(connectionId: String) async throws -> [PlaidAccountBalance] {
            syncBalancesCallCount += 1
            return try syncBalancesResult.get()
        }
        func refreshConnectedAccount(connectionId: String, accountId: String) async throws -> ConnectedAccountRefreshResult {
            refreshConnectedAccountCallCount += 1
            return try refreshResult.get()
        }
        func refreshAccounts(connectionId: String) async throws -> [PlaidAccountSummary] { fatalError("not used in this test") }
        func listConnections() async throws -> [PlaidConnectionStatus] { fatalError("not used in this test") }
        func disconnectAccount(connectionId: String) async throws { fatalError("not used in this test") }
        func debugResetCursor(connectionId: String) async throws { fatalError("not used in this test") }
    }

    @MainActor
    func testRefreshAccountBalanceAndTransactionsUpdatesBothBalanceAndTransactions() async throws {
        let manager = PlaidConnectionManager(defaults: makeIsolatedDefaults())
        manager.addOrUpdate(connectionId: "conn-1", institutionId: "ins_1", institutionName: "Some Bank")
        manager.updateCachedBalances(connectionId: "conn-1", balances: [makeBalance(accountId: "acc-A", current: 100)])

        let context = makePlaidSyncTestContext()
        let refreshedBalance = makeBalance(accountId: "acc-A", current: 250)
        let fake = FakeBalanceAndTransactionsPlaidBackendService(refreshResult: .success(ConnectedAccountRefreshResult(balance: refreshedBalance, remaining: 1)))
        fake.syncTransactionsResult = .success(PlaidSyncResult(added: [makePlaidDTO(id: "new-txn-1")], modified: [], removedExternalIds: []))

        let result = try await manager.refreshAccountBalanceAndTransactions(connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake)

        XCTAssertEqual(result.balance.currentBalance, 250, "the balance half must still update exactly as before")
        XCTAssertEqual(manager.connections.first?.cachedBalances?["acc-A"]?.currentBalance, 250)
        XCTAssertEqual(fake.syncTransactionsCallCount, 1, "one Dashboard tap must trigger exactly one transaction sync")
        let imported = try context.fetch(FetchDescriptor<FinanceTransaction>()).filter { $0.externalTransactionId == "new-txn-1" }
        XCTAssertEqual(imported.count, 1, "a newly available transaction must actually be imported by the same refresh action")
    }

    @MainActor
    func testRefreshAccountBalanceAndTransactionsConsumesExactlyOneManualRefreshQuotaEvent() async throws {
        // The 2/day/account server limit is enforced entirely inside refreshConnectedAccount's
        // own atomic claim (see refresh-connected-account/index.ts, unmodified by this task) —
        // this proves the combined method calls that ONE gated operation exactly once, never
        // twice, and that syncTransactions (which has no rate limit of its own) is never used to
        // work around it.
        let manager = PlaidConnectionManager(defaults: makeIsolatedDefaults())
        manager.addOrUpdate(connectionId: "conn-1", institutionId: "ins_1", institutionName: "Some Bank")
        let context = makePlaidSyncTestContext()
        let fake = FakeBalanceAndTransactionsPlaidBackendService(
            refreshResult: .success(ConnectedAccountRefreshResult(balance: makeBalance(accountId: "acc-A", current: 1), remaining: 1))
        )

        _ = try await manager.refreshAccountBalanceAndTransactions(connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake)

        XCTAssertEqual(fake.refreshConnectedAccountCallCount, 1, "must claim the rate-limited balance operation exactly once per Dashboard tap")
    }

    @MainActor
    func testRefreshAccountBalanceAndTransactionsPropagatesRateLimitedWithoutEverCallingTransactionSync() async {
        let manager = PlaidConnectionManager(defaults: makeIsolatedDefaults())
        manager.addOrUpdate(connectionId: "conn-1", institutionId: "ins_1", institutionName: "Some Bank")
        manager.updateCachedBalances(connectionId: "conn-1", balances: [makeBalance(accountId: "acc-A", current: 100)])
        let context = makePlaidSyncTestContext()
        let fake = FakeBalanceAndTransactionsPlaidBackendService(refreshResult: .failure(PlaidBackendError.rateLimited))

