    @MainActor
    func testRefreshAccountBalanceAndTransactionsFailurePreservesAlreadySuccessfulBalanceUpdate() async throws {
        // A transaction-sync failure AFTER a successful balance refresh must not be reported as
        // full success, but the balance update that already happened must never be rolled back.
        let manager = PlaidConnectionManager(defaults: makeIsolatedDefaults())
        manager.addOrUpdate(connectionId: "conn-1", institutionId: "ins_1", institutionName: "Some Bank")
        manager.updateCachedBalances(connectionId: "conn-1", balances: [makeBalance(accountId: "acc-A", current: 100)])
        let context = makePlaidSyncTestContext()
        let refreshedBalance = makeBalance(accountId: "acc-A", current: 250)
        let fake = FakeBalanceAndTransactionsPlaidBackendService(refreshResult: .success(ConnectedAccountRefreshResult(balance: refreshedBalance, remaining: 1)))
        fake.syncTransactionsResult = .failure(PlaidBackendError.server(status: 500, message: "sync failed"))

        do {
            _ = try await manager.refreshAccountBalanceAndTransactions(connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake)
            XCTFail("Expected the transaction-sync failure to propagate")
        } catch {
            // expected — the caller (Dashboard) must see this as a failure, not silent success
        }
        XCTAssertEqual(manager.connections.first?.cachedBalances?["acc-A"]?.currentBalance, 250, "a balance update that already succeeded must never be rolled back by a later transaction-sync failure")
    }

    @MainActor
    func testRefreshAccountBalanceAndTransactionsNeverDuplicatesAlreadyImportedTransactions() async throws {
        let manager = PlaidConnectionManager(defaults: makeIsolatedDefaults())
        manager.addOrUpdate(connectionId: "conn-1", institutionId: "ins_1", institutionName: "Some Bank")
        let context = makePlaidSyncTestContext()
        let fake = FakeBalanceAndTransactionsPlaidBackendService(
            refreshResult: .success(ConnectedAccountRefreshResult(balance: makeBalance(accountId: "acc-A", current: 1), remaining: 1))
        )
        fake.syncTransactionsResult = .success(PlaidSyncResult(added: [makePlaidDTO(id: "dup-txn-1")], modified: [], removedExternalIds: []))

        _ = try await manager.refreshAccountBalanceAndTransactions(connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake)
        // A second manual refresh where Plaid's cursor re-reports the SAME transaction as
        // "modified" (its normal behavior for an already-delivered row) must update, not duplicate.
        fake.syncTransactionsResult = .success(PlaidSyncResult(added: [], modified: [makePlaidDTO(id: "dup-txn-1", amount: 12.34)], removedExternalIds: []))
        _ = try await manager.refreshAccountBalanceAndTransactions(connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake)

        let matching = try context.fetch(FetchDescriptor<FinanceTransaction>()).filter { $0.externalTransactionId == "dup-txn-1" }
        XCTAssertEqual(matching.count, 1, "the same external transaction must never appear twice after repeated refreshes")
    }

    /// CONNECTED REFRESH ACTIVITY FOLLOW-UP — the proven root cause: `PlaidConnectionManager` is
    /// a plain `@Observable` class with no actor isolation of its own (unlike
    /// `ConnectedAccountsView.performSync`, implicitly MainActor via the `View` protocol), so a
    /// `nonisolated async` method here can resume off the MainActor after its first `await`,
    /// silently running `applySync`'s `context.save()` on the wrong actor — persistence succeeds
    /// but the MainActor-bound `@Query` that Activity/Dashboard read never observes it without an
    /// app restart. This is only reliably provable at the source level (a genuine cross-actor
    /// race isn't deterministically reproducible in a synchronous unit test); every OTHER test in
    /// this group already ran on `@MainActor` and so could never have caught this by construction
    /// — this test locks in the fix's actual mechanism, not just its symptom.
    func testRefreshAccountBalanceAndTransactionsIsMainActorIsolated() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Services/PlaidConnectionManager.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let range = source.range(of: "func refreshAccountBalanceAndTransactions") else {
            XCTFail("refreshAccountBalanceAndTransactions not found"); return
        }
        let preceding = String(source[..<range.lowerBound].suffix(120))
        XCTAssertTrue(preceding.contains("@MainActor"), "must be pinned to the MainActor so applySync's context.save() runs on the same actor Activity's @Query observes — see this test's own header for the real-device bug this fixes")
    }

    func testPlaidConnectionManagerIntroducesNoPollingOrTimer() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Services/PlaidConnectionManager.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        XCTAssertFalse(source.contains("Timer("), "must not introduce polling to keep balance/transactions fresh")
        XCTAssertFalse(source.contains("asyncAfter"))
        XCTAssertFalse(source.contains("Task.sleep"))
    }

    func testDashboardSharedConnectedAccountRowStillNeverGetsRefreshClosureAfterConsistencyFix() throws {
        // Re-confirms an already-locked invariant after this task's change: a shared (Secondary)
        // Dashboard row must still resolve onRefresh to nil — this task must never let a Secondary
        // trigger the Primary's Plaid source refresh (balance OR the new transaction sync).
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Views/Dashboard/DashboardView.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        XCTAssertTrue(source.contains("onRefresh: connectedAccountBalanceDisplays.contains(display) ? { refreshConnectedAccount(display) } : nil"), "onRefresh must remain gated to owned displays only — a shared display must never be given a refresh action of any kind")
    }

    // MARK: - Plaid connection warnings (Plaid onboarding — "Follow Link UI best practices").
    // `PlaidConnectionWarning.evaluate` is the pure decision `connectionCard(_:)` renders from —
    // this is where the "pending disconnect must win, never show both" priority rule actually
    // lives, so it's tested directly rather than through the (untestable) SwiftUI view body.

    func testPendingDisconnectTakesPriorityOverPendingExpiration() {
        let disconnectDate = Date(timeIntervalSince1970: 1_900_000_000)
        let expirationDate = Date(timeIntervalSince1970: 1_850_000_000)

        let warning = PlaidConnectionWarning.evaluate(pendingDisconnectAt: disconnectDate, pendingExpirationAt: expirationDate)

        XCTAssertEqual(warning, .pendingDisconnect(disconnectDate), "Pending disconnect must win whenever both are present — never both warnings at once")
    }

    func testPendingExpirationAloneProducesExpirationWarning() {
        let expirationDate = Date(timeIntervalSince1970: 1_850_000_000)

        let warning = PlaidConnectionWarning.evaluate(pendingDisconnectAt: nil, pendingExpirationAt: expirationDate)

        XCTAssertEqual(warning, .pendingExpiration(expirationDate))
    }

    func testPendingDisconnectAloneProducesDisconnectWarning() {
        let disconnectDate = Date(timeIntervalSince1970: 1_900_000_000)

        let warning = PlaidConnectionWarning.evaluate(pendingDisconnectAt: disconnectDate, pendingExpirationAt: nil)

        XCTAssertEqual(warning, .pendingDisconnect(disconnectDate))
    }

    func testNoPendingDatesProducesNoWarning() {
        let warning = PlaidConnectionWarning.evaluate(pendingDisconnectAt: nil, pendingExpirationAt: nil)

        XCTAssertEqual(warning, .none)
    }

    // MARK: - Removed Sandbox debug-reset-cursor UI (Plaid onboarding — "Follow Link UI best
    // practices": debug-reset-cursor was permanently deleted server-side; no UI path may still
    // reference it). Source-level assertions rather than behavioral ones, since there is nothing
    // left to exercise once a reference is removed — the test is that these strings genuinely
    // don't appear anywhere in the view file's source.

    func testNoSourceReferenceToRemovedDebugResetCursorUI() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
