    func testAnotherConnectedAccountIsExcludedFromSelectedAccountPopulation() {
        let amex = FinanceTransaction(amount: 10, type: .expense, source: .plaid, note: "", countsTowardWeeklyBudget: false, plaidAccountId: "acc-amex")
