    // MARK: - Phase 7: Account Related Options / Primary sharing controls

    private final class FakeHouseholdSharingService: HouseholdSharingService {
        var stateResponse: AccountRelatedOptionsResponse
        var initializeResult: Result<HouseholdStateResponse, Error>
        var invitationResult: Result<InvitationActionResponse, Error> = .success(InvitationActionResponse(invitationId: UUID(), revoked: nil, invitationUrl: nil))
        var sharingPermissionResult: Result<SharingPermissionUpdateResponse, Error> = .success(SharingPermissionUpdateResponse(sharingPermissionId: UUID()))

        var initializeCallCount = 0
        var getOptionsCallCount = 0
        var lastInvitationRequest: InvitationActionRequest?
        var lastSharingPermissionRequest: SharingPermissionUpdateRequest?

        /// Phase 7D regression hooks — invoked synchronously from inside the async network call,
        /// BEFORE it returns, so a test can assert on the view model's state while a mutation is
        /// still genuinely in flight (the exact moment the full-screen-flash bug used to corrupt
        /// `state`). Left `nil` by every pre-existing test, which is unaffected.
        var onBeforeUpdateSharingPermissionReturns: (() -> Void)?
        var onBeforeManageInvitationReturns: (() -> Void)?
        var onBeforeGetOptionsReturns: (() -> Void)?
        /// When set, `getAccountRelatedOptions` throws this instead of returning `stateResponse` —
        /// lets a test flip a SUBSEQUENT (e.g. post-write silent) refresh into failing without
        /// affecting the initial load that already succeeded.
        var getOptionsError: Error?

        /// CLIENT CORRECTION — refresh-coalescing regression hooks. When `holdGetOptions` is true,
        /// `getAccountRelatedOptions()` suspends indefinitely (via a real continuation, not a
        /// timer/sleep) after incrementing `getOptionsCallCount`, until the test calls
        /// `releaseGetOptions()`. This lets a test deterministically prove that a SECOND concurrent
        /// `refresh()` caller never triggers a second network call while the first is still
        /// genuinely in flight.
        ///
        /// HANG INVESTIGATION CORRECTION — this used to store `CheckedContinuation`s directly in a
        /// plain `[CheckedContinuation<Void, Never>]` on this non-actor, non-`@MainActor` class.
        /// `getAccountRelatedOptions()` is a `nonisolated` protocol requirement, so when called from
        /// `@MainActor`-isolated `AccountRelatedOptionsViewModel.performRefresh(callGeneration:)` it
        /// executes on whatever executor happened to be current at the call site with NO actor
        /// serializing access to that array — installing a continuation (inside
        /// `withCheckedContinuation`'s closure) and resuming it (from `releaseGetOptions()`, called
        /// directly from the test body) were two unsynchronized writers to the same shared mutable
        /// state. `ContinuationGate` below is a dedicated `actor` — the ONE serialization point for
        /// "install a waiter" vs. "release every waiter" — so a waiter can never be lost and a
        /// release can never be observed before its waiter is installed, by construction (an actor
        /// processes one call at a time; `wait()` fully installs its continuation before `release()`
        /// can run). This removes the whole class of race the investigation flagged (item 7: "the
        /// mock is resumed before a waiter is installed").
        private actor ContinuationGate {
            private var pending: [CheckedContinuation<Void, Never>] = []
            /// Guards against `release()` running before a *subsequent* `wait()` — e.g. a caller
            /// whose call to `getAccountRelatedOptions()` hasn't reached this gate yet at the
            /// moment `releaseGetOptions()` fires. Without this, that late waiter would install
            /// itself into `pending` after `release()` already ran and hang forever (the exact
            /// failure mode being corrected here) — matching the production `inFlightRefresh`
            /// coalescing contract, where every concurrent caller must complete once released.
            private var released = false

            func wait() async {
                if released { return }
                await withCheckedContinuation { continuation in
                    pending.append(continuation)
                }
            }

            func release() {
                released = true
                let continuations = pending
                pending = []
                for continuation in continuations { continuation.resume() }
            }
        }

        var holdGetOptions = false
        private let getOptionsGate = ContinuationGate()

        /// Synchronous on purpose (matches every existing call site, none of which `await` it) —
        /// hands the actual release off to the gate actor via a detached `Task`, which is still
        /// fully deterministic: the gate actor serializes `release()` against any `wait()` already
        /// installed or yet to install, so callers awaiting `_ = await first`/`_ = await second`
        /// simply suspend until that `Task` runs, exactly as they did with the prior synchronous
        /// (but unsynchronized) implementation.
        func releaseGetOptions() {
            Task { await getOptionsGate.release() }
        }

        init(stateResponse: AccountRelatedOptionsResponse) {
            self.stateResponse = stateResponse
            self.initializeResult = .success(HouseholdStateResponse(householdId: stateResponse.householdId, role: stateResponse.role, status: stateResponse.status))
        }

        func initializeHousehold() async throws -> HouseholdStateResponse {
            initializeCallCount += 1
            return try initializeResult.get()
        }

        func getAccountRelatedOptions() async throws -> AccountRelatedOptionsResponse {
            getOptionsCallCount += 1
            onBeforeGetOptionsReturns?()
            if holdGetOptions {
                await getOptionsGate.wait()
            }
            if let getOptionsError { throw getOptionsError }
            return stateResponse
        }

        func manageInvitation(_ request: InvitationActionRequest) async throws -> InvitationActionResponse {
            lastInvitationRequest = request
            onBeforeManageInvitationReturns?()
            return try invitationResult.get()
        }

        func updateSharingPermission(_ request: SharingPermissionUpdateRequest) async throws -> SharingPermissionUpdateResponse {
            lastSharingPermissionRequest = request
            onBeforeUpdateSharingPermissionReturns?()
            return try sharingPermissionResult.get()
        }

        var previewResult: Result<InvitationPreviewResponse, Error> = .success(
            InvitationPreviewResponse(found: false, status: nil, isExpired: nil, expiresAt: nil, primaryDisplayName: nil, invitedEmail: nil)
        )
        var acceptResult: Result<AcceptInvitationResponse, Error> = .success(
            AcceptInvitationResponse(householdId: UUID(), role: .secondary, status: .active)
        )
        var lastPreviewToken: String?
        var lastAcceptToken: String?

        func previewInvitation(token: String) async throws -> InvitationPreviewResponse {
            lastPreviewToken = token
            return try previewResult.get()
        }

        func acceptInvitation(token: String) async throws -> AcceptInvitationResponse {
            lastAcceptToken = token
            return try acceptResult.get()
        }

        var myPendingInvitationResult: Result<MyPendingInvitationResponse, Error> = .success(
            MyPendingInvitationResponse(found: false, invitationId: nil, status: nil, isExpired: nil, expiresAt: nil, primaryDisplayName: nil, invitedEmail: nil)
        )
        var lastAcceptInvitationId: UUID?
        var checkMyPendingInvitationCallCount = 0

        func checkMyPendingInvitation() async throws -> MyPendingInvitationResponse {
            checkMyPendingInvitationCallCount += 1
            return try myPendingInvitationResult.get()
        }

        func acceptInvitation(invitationId: UUID) async throws -> AcceptInvitationResponse {
            lastAcceptInvitationId = invitationId
            return try acceptResult.get()
        }

        var declineResult: Result<DeclineInvitationResponse, Error> = .success(
            DeclineInvitationResponse(invitationId: UUID(), status: "declined")
        )
        var lastDeclineInvitationId: UUID?
        var declineCallCount = 0

        func declineInvitation(invitationId: UUID) async throws -> DeclineInvitationResponse {
            declineCallCount += 1
            lastDeclineInvitationId = invitationId
            return try declineResult.get()
        }

        // MARK: Phase 9 — Primary-shared data reads

        var sharedConnectedAccountTransactionsResult: Result<SharedConnectedAccountTransactionsResponse, Error> = .success(
            SharedConnectedAccountTransactionsResponse(transactions: [])
        )
        /// PHASE B — per-account override, so a test can return DIFFERENT transactions for
        /// different `plaidAccountId`s (e.g. proving Actual sums across multiple shared
        /// accounts). Falls back to `sharedConnectedAccountTransactionsResult` when no override
        /// is set for the requested id.
        var sharedConnectedAccountTransactionsResultsByAccountId: [UUID: Result<SharedConnectedAccountTransactionsResponse, Error>] = [:]
        var lastSharedConnectedAccountTransactionsPlaidAccountId: UUID?
        var getSharedConnectedAccountTransactionsCallCount = 0
        var requestedSharedConnectedAccountTransactionIds: [UUID] = []
        var sharedManualAccountDataResult: Result<SharedManualAccountDataResponse, Error> = .success(
            SharedManualAccountDataResponse(account: nil)
        )
        /// PHASE B — same per-account override mechanism, for Manual Accounts.
        var sharedManualAccountDataResultsByAccountId: [UUID: Result<SharedManualAccountDataResponse, Error>] = [:]
        var lastSharedManualAccountId: UUID?
        var getSharedManualAccountDataCallCount = 0
        var requestedSharedManualAccountIds: [UUID] = []
        var sharedMonthlyPlanResult: Result<SharedMonthlyPlanResponse, Error> = .success(
            SharedMonthlyPlanResponse(plan: nil)
        )
        var lastSharedMonthlyPlanOwnerUserId: UUID?

        func getSharedConnectedAccountTransactions(plaidAccountId: UUID) async throws -> SharedConnectedAccountTransactionsResponse {
            getSharedConnectedAccountTransactionsCallCount += 1
            requestedSharedConnectedAccountTransactionIds.append(plaidAccountId)
            lastSharedConnectedAccountTransactionsPlaidAccountId = plaidAccountId
            if let override = sharedConnectedAccountTransactionsResultsByAccountId[plaidAccountId] {
                return try override.get()
            }
            return try sharedConnectedAccountTransactionsResult.get()
        }

        func getSharedManualAccountData(manualAccountId: UUID) async throws -> SharedManualAccountDataResponse {
            getSharedManualAccountDataCallCount += 1
            requestedSharedManualAccountIds.append(manualAccountId)
            lastSharedManualAccountId = manualAccountId
            if let override = sharedManualAccountDataResultsByAccountId[manualAccountId] {
                return try override.get()
            }
            return try sharedManualAccountDataResult.get()
        }

        func getSharedMonthlyPlan(ownerUserId: UUID) async throws -> SharedMonthlyPlanResponse {
            lastSharedMonthlyPlanOwnerUserId = ownerUserId
            return try sharedMonthlyPlanResult.get()
        }

        // MARK: CLIENT UI PHASE — Monthly Savings sharing

        var upsertSavingsSummaryResult: Result<UpsertSavingsSummaryResponse, Error> = .success(UpsertSavingsSummaryResponse(ok: true))
        var lastUpsertSavingsSummaryRequest: UpsertSavingsSummaryRequest?
        var upsertSavingsSummaryCallCount = 0
        var sharedMonthlySavingsSummaryResult: Result<SharedMonthlySavingsSummaryResponse, Error> = .success(
            SharedMonthlySavingsSummaryResponse(summary: nil)
        )
        var lastSharedMonthlySavingsSummaryOwnerUserId: UUID?
        var getMonthlySavingsSummaryCallCount = 0

        func upsertSavingsSummary(_ request: UpsertSavingsSummaryRequest) async throws -> UpsertSavingsSummaryResponse {
            upsertSavingsSummaryCallCount += 1
            lastUpsertSavingsSummaryRequest = request
            return try upsertSavingsSummaryResult.get()
        }

        func getMonthlySavingsSummary(ownerUserId: UUID) async throws -> SharedMonthlySavingsSummaryResponse {
            getMonthlySavingsSummaryCallCount += 1
            lastSharedMonthlySavingsSummaryOwnerUserId = ownerUserId
            return try sharedMonthlySavingsSummaryResult.get()
        }

        // MARK: USER B DASHBOARD PARITY — authoritative shared Dashboard aggregates

        var upsertDashboardSummaryResult: Result<UpsertDashboardSummaryResponse, Error> = .success(UpsertDashboardSummaryResponse(ok: true))
        var lastUpsertDashboardSummaryRequest: UpsertDashboardSummaryRequest?
        var upsertDashboardSummaryCallCount = 0
        var sharedDashboardSummaryResult: Result<SharedDashboardSummaryResponse, Error> = .success(
            SharedDashboardSummaryResponse(summary: nil)
        )
        var lastSharedDashboardSummaryOwnerUserId: UUID?
        var getDashboardSummaryCallCount = 0

        func upsertDashboardSummary(_ request: UpsertDashboardSummaryRequest) async throws -> UpsertDashboardSummaryResponse {
            upsertDashboardSummaryCallCount += 1
            lastUpsertDashboardSummaryRequest = request
            return try upsertDashboardSummaryResult.get()
        }

        func getDashboardSummary(ownerUserId: UUID) async throws -> SharedDashboardSummaryResponse {
            getDashboardSummaryCallCount += 1
            lastSharedDashboardSummaryOwnerUserId = ownerUserId
            return try sharedDashboardSummaryResult.get()
        }

        var myManualAccountsResult: Result<MyManualAccountsResponse, Error> = .success(MyManualAccountsResponse(accounts: []))
        var getMyManualAccountsCallCount = 0

        func getMyManualAccounts() async throws -> MyManualAccountsResponse {
            getMyManualAccountsCallCount += 1
            return try myManualAccountsResult.get()
        }
    }

    // MARK: - URGENT ACCOUNT-SWITCH FREEZE PHASE A — stale in-flight discovery cannot clobber reset

    /// `RootView.task` fires `Task { await accountRelatedOptionsViewModel.refresh() }` as a
    /// nested, unstructured `Task` that is NOT cancelled when `RootView`/the signed-out session
    /// goes away — the same class of "stale async work outlives the view/session that started it"
    /// bug already fixed for `AutoBackupManager`/`ManualDataCloudSyncManager`/
    /// `MonthlyPlanCloudSyncManager`, applied here to an unstructured `Task` instead of a
    /// `NotificationCenter` observer. Source-scan regression guard, matching this codebase's own
    /// established convention for proving a lifecycle fix is present and correctly wired at every
    /// call site that commits `state`.
    func testAccountRelatedOptionsViewModelResetInvalidatesInFlightRefresh() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Services/AccountRelatedOptionsViewModel.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let resetRange = source.range(of: "func reset()") else {
            XCTFail("reset() not found"); return
        }
        let resetSection = String(source[resetRange.lowerBound...].prefix(700))
        XCTAssertTrue(resetSection.contains("generation += 1"), "reset() must invalidate any refresh() already in flight")
        XCTAssertTrue(resetSection.contains("inFlightRefresh = nil"), "reset() must drop the in-flight refresh slot so the NEXT refresh() starts a fresh fetch instead of coalescing onto the outgoing user's task")

        // CLIENT CORRECTION — the generation-guarded state-committing logic now lives in
        // performRefresh(callGeneration:), which refresh() coalesces callers onto via
        // inFlightRefresh (see the dedicated coalescing tests below).
        guard let performRefreshRange = source.range(of: "func performRefresh(callGeneration: Int) async") else {
            XCTFail("performRefresh(callGeneration:) not found"); return
        }
        let performRefreshSection = String(source[performRefreshRange.lowerBound...].prefix(1600))
        let guardCount = performRefreshSection.components(separatedBy: "guard callGeneration == generation else { return }").count - 1
        XCTAssertEqual(guardCount, 4, "every state-committing branch (loading success/failure, background success/failure) must guard on the generation token")

        guard let refreshRange = source.range(of: "func refresh() async") else {
            XCTFail("refresh() not found"); return
        }
        let refreshSection = String(source[refreshRange.lowerBound...].prefix(800))
        XCTAssertTrue(refreshSection.contains("if let inFlightRefresh"), "refresh() must coalesce onto an already-in-flight request rather than starting a competing one")
        XCTAssertTrue(refreshSection.contains("await inFlightRefresh.value"))
    }

    // MARK: - CLIENT CORRECTION — refresh() coalescing (Secondary savings-card flash/race fix)

    /// `RootView.task` and the `scenePhase == .active` handler can both call `refresh()` near
    /// sign-in while `state` is still not `.loaded`. Proves a second concurrent caller never
    /// triggers a competing network request — both converge on the SAME in-flight call.
    @MainActor
    func testAccountRelatedOptionsRefreshCoalescesConcurrentCallers() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeSecondaryResponse(primaryMonthlySavingsShared: true))
        fake.holdGetOptions = true
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        async let first: Void = viewModel.refresh()
        // Wait until the first call has genuinely reached the (held) network call before starting
        // the second — guarantees `inFlightRefresh` is already set, no flakiness from scheduling
        // order between the two `async let` bindings.
        while fake.getOptionsCallCount == 0 { await Task.yield() }
        async let second: Void = viewModel.refresh()
        // Give the second caller a chance to actually run and observe the in-flight task.
        await Task.yield()
        await Task.yield()
        XCTAssertEqual(fake.getOptionsCallCount, 1, "a second concurrent refresh() must not start a competing network request")

        fake.releaseGetOptions()
        _ = await first
        _ = await second

        XCTAssertEqual(fake.getOptionsCallCount, 1, "still only one network call after both callers complete")
        XCTAssertEqual(viewModel.visibility, .secondary)
    }

    // MARK: - HANG INVESTIGATION CORRECTION — required behavioral proof (items 1-10)

    /// Item 3: three or more concurrent callers still coalesce onto exactly one network call.
    @MainActor
    func testAccountRelatedOptionsRefreshCoalescesThreeOrMoreConcurrentCallers() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeSecondaryResponse(primaryMonthlySavingsShared: true))
        fake.holdGetOptions = true
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        async let first: Void = viewModel.refresh()
        while fake.getOptionsCallCount == 0 { await Task.yield() }
        async let second: Void = viewModel.refresh()
        async let third: Void = viewModel.refresh()
        async let fourth: Void = viewModel.refresh()
        await Task.yield()
        await Task.yield()
        XCTAssertEqual(fake.getOptionsCallCount, 1, "four concurrent callers must still trigger only one network call")

        fake.releaseGetOptions()
        _ = await first
        _ = await second
        _ = await third
        _ = await fourth

        XCTAssertEqual(fake.getOptionsCallCount, 1, "still only one network call after all four callers complete")
        XCTAssertEqual(viewModel.visibility, .secondary, "every coalesced caller must observe the successful result")
    }

    /// Item 4: an underlying error reaches every waiting caller — none of them silently succeeds
    /// or hangs because it coalesced onto a request that ultimately failed.
    @MainActor
    func testAccountRelatedOptionsRefreshErrorReachesAllWaitingCallers() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makePrimaryResponse())
        fake.holdGetOptions = true
        fake.getOptionsError = HouseholdSharingError.unauthorized
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        async let first: Void = viewModel.refresh()
        while fake.getOptionsCallCount == 0 { await Task.yield() }
        async let second: Void = viewModel.refresh()
        await Task.yield()
        await Task.yield()

        fake.releaseGetOptions()
        _ = await first
        _ = await second

        XCTAssertEqual(fake.getOptionsCallCount, 1)
        if case .failed = viewModel.state {} else {
            XCTFail("both coalesced callers must observe the failure — state must be .failed, not .loaded or .idle")
        }
    }

    /// Item 5/6: `inFlightRefresh` clears after both success and failure, so the NEXT call to
    /// `refresh()` always starts a genuinely fresh request rather than being wedged forever onto a
    /// completed (or failed) task.
    @MainActor
    func testAccountRelatedOptionsRefreshInFlightStateClearsAfterSuccess() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makePrimaryResponse())
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        await viewModel.refresh()
        XCTAssertEqual(fake.getOptionsCallCount, 1)

        // A second, later (non-concurrent) call must start a genuinely new request — proving the
        // in-flight slot was cleared, not permanently coalesced onto the first, completed task.
        await viewModel.refresh()
        XCTAssertEqual(fake.getOptionsCallCount, 2, "in-flight state must clear after success so a later refresh() starts fresh")
    }

    @MainActor
    func testAccountRelatedOptionsRefreshInFlightStateClearsAfterFailure() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makePrimaryResponse())
        fake.getOptionsError = HouseholdSharingError.unauthorized
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        await viewModel.refresh()
        XCTAssertEqual(fake.getOptionsCallCount, 1)
        if case .failed = viewModel.state {} else { XCTFail("first call must fail") }

        fake.getOptionsError = nil
        fake.stateResponse = Self.makePrimaryResponse()
        await viewModel.refresh()
        XCTAssertEqual(fake.getOptionsCallCount, 2, "in-flight state must clear after failure so a later refresh() starts fresh")
        XCTAssertEqual(viewModel.visibility, .primary, "the later, successful call must be reflected once it completes")
    }

    /// Item 7: a later refresh, issued only after the prior one has fully completed (never
    /// concurrently), always performs its own independent network call — the coalescing path never
    /// interferes with strictly-sequential calls.
    @MainActor
    func testAccountRelatedOptionsRefreshLaterCallStartsNormallyAfterPriorCompletes() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makePrimaryResponse())
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        await viewModel.refresh()
        await viewModel.refresh()
        await viewModel.refresh()

        XCTAssertEqual(fake.getOptionsCallCount, 3, "three strictly-sequential calls must each perform their own network request")
    }

    /// Item 8: cancelling ONE waiting caller's own wrapper `Task` must never strand the other
    /// concurrent callers — `refresh()` coalesces onto a single SHARED `inFlightRefresh` task that
    /// is never a structured child of any individual caller, so cancelling one caller's task has no
    /// effect on that shared task or on any other caller awaiting it.
    @MainActor
    func testAccountRelatedOptionsRefreshCancellingOneWaiterDoesNotStrandOthers() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeSecondaryResponse(primaryMonthlySavingsShared: true))
        fake.holdGetOptions = true
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        let firstTask = Task { @MainActor in await viewModel.refresh() }
        while fake.getOptionsCallCount == 0 { await Task.yield() }
        let secondTask = Task { @MainActor in await viewModel.refresh() }
        await Task.yield()
        await Task.yield()

        secondTask.cancel()

        fake.releaseGetOptions()
        _ = await firstTask.value

        XCTAssertEqual(fake.getOptionsCallCount, 1, "cancelling the second caller must not have triggered a competing network request")
        XCTAssertEqual(viewModel.visibility, .secondary, "the first (uncancelled) caller must still observe the successful result")
    }

    /// `refresh()` must still load normally (exactly one network call, one result) when no request
    /// is already active — the coalescing path must never interfere with the ordinary case.
    @MainActor
    func testAccountRelatedOptionsRefreshLoadsNormallyWhenNotAlreadyInFlight() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makePrimaryResponse())
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        await viewModel.refresh()

        XCTAssertEqual(fake.getOptionsCallCount, 1)
        XCTAssertEqual(viewModel.visibility, .primary)
    }

    /// A sign-out (`reset()`) that happens WHILE a `refresh()` is still genuinely in flight must
    /// win — the stale, pre-reset response must never repopulate `state` once it finally arrives.
    @MainActor
    func testAccountRelatedOptionsResetDuringInFlightRefreshPreventsStaleWrite() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makePrimaryResponse())
        fake.holdGetOptions = true
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        async let inFlight: Void = viewModel.refresh()
        while fake.getOptionsCallCount == 0 { await Task.yield() }

        // Sign-out happens while the network call above is still suspended.
        viewModel.reset()
        XCTAssertEqual(viewModel.visibility, .hidden)

        // The stale, pre-reset call finally resolves — it must be a no-op.
        fake.releaseGetOptions()
        _ = await inFlight

        XCTAssertEqual(viewModel.visibility, .hidden, "a stale in-flight refresh from before reset() must never repopulate state afterward")
        if case .idle = viewModel.state {} else {
            XCTFail("state must remain .idle after reset(), even once the stale in-flight response arrives")
        }
    }

    /// No timer/sleep/polling mechanism was introduced by the coalescing fix — it relies entirely
    /// on structured `Task`/`await`, matching this project's own standing "no sleep/asyncAfter/
    /// timers/polling" constraint.
    func testAccountRelatedOptionsViewModelIntroducesNoPollingOrTimers() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Services/AccountRelatedOptionsViewModel.swift")
        XCTAssertFalse(source.contains("Timer("))
        XCTAssertFalse(source.contains("asyncAfter"))
        XCTAssertFalse(source.contains("Thread.sleep"))
        XCTAssertFalse(source.contains("Task.sleep"))
    }

    /// User A → User B: after `reset()`, the very next `refresh()` must reflect ONLY the new
    /// user's server response — never anything left over from User A.
    @MainActor
    func testAccountRelatedOptionsUserSwitchNeverReflectsPriorUsersResponse() async {
        let fake = FakeHouseholdSharingService(stateResponse: Self.makePrimaryResponse())
        let viewModel = AccountRelatedOptionsViewModel(backend: fake)

        await viewModel.refresh()
        XCTAssertEqual(viewModel.visibility, .primary)

        viewModel.reset()
        XCTAssertEqual(viewModel.visibility, .hidden)
        XCTAssertNil(viewModel.response)

        // User B signs in — the same backend/view-model instance now serves a different identity.
        fake.stateResponse = Self.makeSecondaryResponse(primaryMonthlySavingsShared: true)
        await viewModel.refresh()

        XCTAssertEqual(viewModel.visibility, .secondary)
        XCTAssertEqual(viewModel.response?.primaryMonthlySavingsShared, true, "must reflect User B's own fresh response, never User A's")
    }

    /// Same class of fix as above, for `PendingInvitationPopupViewModel`'s own unstructured
    /// `Task { await pendingInvitationPopupViewModel.checkForPendingInvitation() }` in
    /// `RootView.task`.
    func testPendingInvitationPopupViewModelResetInvalidatesInFlightCheck() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Services/PendingInvitationPopupViewModel.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let resetRange = source.range(of: "func reset()") else {
            XCTFail("reset() not found"); return
        }
        let resetSection = String(source[resetRange.lowerBound...].prefix(600))
        XCTAssertTrue(resetSection.contains("generation += 1"), "reset() must invalidate any checkForPendingInvitation() already in flight")

        guard let checkRange = source.range(of: "func checkForPendingInvitation() async") else {
            XCTFail("checkForPendingInvitation() not found"); return
        }
        let checkSection = String(source[checkRange.lowerBound...].prefix(600))
        XCTAssertTrue(checkSection.contains("let callGeneration = generation"), "checkForPendingInvitation() must capture the generation at entry")
        let guardCount = checkSection.components(separatedBy: "guard callGeneration == generation else { return }").count - 1
        XCTAssertEqual(guardCount, 2, "both the success and failure branch must guard on the generation token")
    }

    private static func makeNoHouseholdResponse() -> AccountRelatedOptionsResponse {
        AccountRelatedOptionsResponse(
            householdId: nil, role: nil, status: nil,
            secondaryMember: nil, pendingInvitation: nil,
            sharingPermissions: [], connectedAccounts: [], manualAccounts: []
        )
    }

    private static func makeSecondaryResponse(
        sharingPermissions: [SharingPermissionDTO] = [],
        connectedAccounts: [ConnectedAccountShareDTO] = [],
        manualAccounts: [ManualAccountShareDTO] = [],
        primaryUserId: UUID? = nil,
        primarySharedConnectedAccounts: [SharedConnectedAccountDTO] = [],
        primarySharedManualAccounts: [SharedManualAccountDTO] = [],
        primaryMonthlyPlanShared: Bool = false,
        primaryMonthlySavingsShared: Bool = false
    ) -> AccountRelatedOptionsResponse {
        AccountRelatedOptionsResponse(
            householdId: UUID(), role: .secondary, status: .active,
            secondaryMember: nil, pendingInvitation: nil,
            sharingPermissions: sharingPermissions, connectedAccounts: connectedAccounts, manualAccounts: manualAccounts,
            primaryUserId: primaryUserId,
            primarySharedConnectedAccounts: primarySharedConnectedAccounts,
            primarySharedManualAccounts: primarySharedManualAccounts,
            primaryMonthlyPlanShared: primaryMonthlyPlanShared,
            primaryMonthlySavingsShared: primaryMonthlySavingsShared
        )
    }

    private static func makePrimaryResponse(
        sharingPermissions: [SharingPermissionDTO] = [],
        connectedAccounts: [ConnectedAccountShareDTO] = [],
        manualAccounts: [ManualAccountShareDTO] = [],
        pendingInvitation: PendingInvitationDTO? = nil,
        secondaryMember: SecondaryMemberDTO? = nil
    ) -> AccountRelatedOptionsResponse {
        AccountRelatedOptionsResponse(
            householdId: UUID(), role: .primary, status: .active,
            secondaryMember: secondaryMember, pendingInvitation: pendingInvitation,
            sharingPermissions: sharingPermissions, connectedAccounts: connectedAccounts, manualAccounts: manualAccounts
        )
    }

