    // MARK: Response decoding — wire-format parity with the Edge Function's JSON

    func testAccountRelatedOptionsResponseDecodesFullPrimaryPayload() throws {
        let json = """
        {
          "household_id": "11111111-1111-1111-1111-111111111111",
          "role": "primary",
          "status": "active",
          "secondary_member": {
            "user_id": "22222222-2222-2222-2222-222222222222",
            "email": "secondary@example.com",
            "status": "active",
            "joined_at": "2026-07-01T12:00:00Z"
          },
          "pending_invitation": null,
          "sharing_permissions": [
            {"category": "connectedAccounts", "item_id": null, "is_shared": true}
          ],
          "connected_accounts": [
            {"plaid_account_id": "33333333-3333-3333-3333-333333333333", "account_id": "plaid_abc", "name": "Checking", "mask": "1234"}
          ],
          "manual_accounts": [
            {"id": "44444444-4444-4444-4444-444444444444", "name": "Cash", "account_type": "cash"}
          ]
        }
        """.data(using: .utf8)!

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let response = try decoder.decode(AccountRelatedOptionsResponse.self, from: json)

        XCTAssertEqual(response.role, .primary)
        XCTAssertEqual(response.status, .active)
        XCTAssertEqual(response.secondaryMember?.email, "secondary@example.com")
        XCTAssertNil(response.pendingInvitation)
        XCTAssertEqual(response.sharingPermissions.first?.isShared, true)
        XCTAssertEqual(response.connectedAccounts.first?.mask, "1234")
        XCTAssertEqual(response.manualAccounts.first?.accountType, "cash")
    }

    /// PHASE B SHARED CONNECTED ACCOUNT REGRESSION DEBUG — the definitive end-to-end regression
    /// test. Decodes the FULL `AccountRelatedOptionsResponse` (not `SharedConnectedAccountDTO` in
    /// isolation) using the EXACT byte-for-byte JSON shape live-captured from Preview's currently-
    /// deployed `get-account-related-options` for a real Secondary with one shared Connected
    /// Account: Postgres's own default `timestamptz::text` format
    /// (`"2026-07-26 11:40:48.400987+00"` — space-separated, short `+00` offset, no colon), a
    /// string-encoded decimal balance, and every field migration 0017 added. If this ever throws
    /// again, `primarySharedConnectedAccounts` disappearing from Dashboard/Activity/Settings
    /// simultaneously is the guaranteed symptom (see `SharedTimestampDecoding`'s own header for
    /// why a single bad field fails the entire response decode).
    func testAccountRelatedOptionsResponseDecodesRealSecondarySharedConnectedAccountPayload() throws {
        let json = """
        {
          "household_id": "12639c8b-3472-48a4-a18f-e98c15fec2e3",
          "role": "secondary",
          "status": "active",
          "secondary_member": null,
          "pending_invitation": null,
          "sharing_permissions": [],
          "connected_accounts": [],
          "manual_accounts": [],
          "primary_user_id": "d6b20822-3142-42ad-b42d-5ab75ff7ff9b",
          "primary_shared_connected_accounts": [
            {
              "mask": "1111",
              "name": "RegressionDebug Checking",
              "type": "depository",
              "updated_at": "2026-07-26 11:40:48.400987+00",
              "credit_limit": null,
              "current_balance": "1250.55",
              "plaid_account_id": "147547e0-96dd-4110-bb81-d1950e85c09a",
              "available_balance": "1250.55"
            }
          ],
          "primary_shared_manual_accounts": [],
          "primary_monthly_plan_shared": false
        }
        """.data(using: .utf8)!

        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        let response = try decoder.decode(AccountRelatedOptionsResponse.self, from: json)

        XCTAssertEqual(response.role, .secondary)
        XCTAssertEqual(response.primarySharedConnectedAccounts.count, 1)
        let account = try XCTUnwrap(response.primarySharedConnectedAccounts.first)
        XCTAssertEqual(account.name, "RegressionDebug Checking")
        XCTAssertEqual(account.currentBalance, Decimal(string: "1250.55"))
        XCTAssertEqual(account.availableBalance, Decimal(string: "1250.55"))
        XCTAssertNil(account.creditLimit)
        XCTAssertEqual(account.accountType, "depository")
        XCTAssertNotNil(account.updatedAt, "the Postgres-default timestamp format must still decode, not throw")
    }

    /// The same regression, proven at the `AccountRelatedOptionsViewModel` level (not just raw
    /// JSON decode) — confirms the account actually reaches `response`/presentation state after a
    /// `refresh()`, matching what Dashboard/Activity/Settings all read from.
    @MainActor
    func testAccountRelatedOptionsViewModelPresentsSharedConnectedAccountWithRealTimestampFormat() async {
        let sharedAccount = SharedConnectedAccountDTO(
            plaidAccountId: UUID(), name: "RegressionDebug Checking", mask: "1111",
