        await viewModel.refresh()

        XCTAssertEqual(viewModel.response?.primarySharedConnectedAccounts.count, 1)
        XCTAssertEqual(viewModel.response?.primarySharedConnectedAccounts.first?.currentBalance, Decimal(string: "1250.55"))
    }

