        XCTAssertFalse(viewModel.isShared(category: "connectedAccounts", itemId: nil), "the failed toggle rolls back to the server-confirmed value")
        XCTAssertTrue(viewModel.isShared(category: "manualAccounts", itemId: nil), "an unrelated control's value is never touched by another control's rollback")
        XCTAssertNotNil(viewModel.actionError)
    }

