    // MARK: - Phase 8F follow-up: stale-invitation-id acceptance bug fix
    //
    // Reproduces the real Production bug report: the Primary revokes+resends (e.g. tapping
    // "Resend", or Revoke followed by re-Invite) while a Secondary's popup is already showing an
    // OLDER discovered invitation — `resend_invitation` (migration 0008) always revokes the
    // currently-pending row and creates a brand-new one with a DIFFERENT id, by design. Before
    // this fix, `state` never re-fetched once `.found` (see `PendingInvitationPopupViewModel`'s
    // own header), so every subsequent Accept attempt kept resubmitting the now-revoked id
    // forever — and once "Not Now" (the only thing that happened to force a fresh re-check) is
    // removed, there was no way out at all.

    @MainActor
    func testAcceptFailureAgainstASupersededInvitationRefreshesToTheCurrentOne() async {
        struct StaleInvitationError: Error {}
        let staleInvitationId = UUID()
        let freshInvitationId = UUID()
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        fake.myPendingInvitationResult = .success(MyPendingInvitationResponse(
            found: true, invitationId: staleInvitationId, status: "pending", isExpired: false,
            expiresAt: Date().addingTimeInterval(600), primaryDisplayName: "Scott", invitedEmail: "b@example.com"
        ))
        let popup = PendingInvitationPopupViewModel(backend: fake)
        await popup.checkForPendingInvitation()
        guard case .found(let discovered) = popup.state else {
            XCTFail("expected the stale invitation to be discovered first"); return
        }
        XCTAssertEqual(discovered.invitationId, staleInvitationId)

        // The Primary resends in the interim — the server now has a genuinely different pending
        // invitation, and the stale one this popup is already showing gets rejected.
        fake.acceptResult = .failure(StaleInvitationError())
        fake.myPendingInvitationResult = .success(MyPendingInvitationResponse(
            found: true, invitationId: freshInvitationId, status: "pending", isExpired: false,
            expiresAt: Date().addingTimeInterval(600), primaryDisplayName: "Scott", invitedEmail: "b@example.com"
        ))

        await popup.accept()

        XCTAssertFalse(popup.didAccept)
        XCTAssertNotNil(popup.acceptanceError, "the failed attempt's error must still be shown")
        XCTAssertTrue(popup.shouldPresentPopup, "must never silently dismiss on failure")
        guard case .found(let refreshed) = popup.state else {
            XCTFail("expected state to refresh to the current invitation"); return
        }
        XCTAssertEqual(refreshed.invitationId, freshInvitationId, "a retry must now target the CURRENT invitation, not the stale one")
        XCTAssertEqual(fake.lastAcceptInvitationId, staleInvitationId, "the failed attempt itself must have submitted the stale id it actually had")

        // Retrying now succeeds against the fresh id.
        fake.acceptResult = .success(AcceptInvitationResponse(householdId: UUID(), role: .secondary, status: .active))
        await popup.accept()

        XCTAssertTrue(popup.didAccept)
        XCTAssertEqual(fake.lastAcceptInvitationId, freshInvitationId)
    }

    @MainActor
    func testAcceptFailureWithNoReplacementInvitationLeavesStateUntouched() async {
        // The Primary simply revoked with no resend — nothing is pending anymore. Must NOT
        // dismiss the popup or blank out the invitation the user was looking at (locked Phase 8D
        // "a failed Accept or Decline must NOT silently dismiss the invitation" contract).
        struct GoneError: Error {}
        let invitationId = UUID()
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        fake.myPendingInvitationResult = .success(MyPendingInvitationResponse(
            found: true, invitationId: invitationId, status: "pending", isExpired: false,
            expiresAt: Date().addingTimeInterval(600), primaryDisplayName: nil, invitedEmail: nil
        ))
        let popup = PendingInvitationPopupViewModel(backend: fake)
        await popup.checkForPendingInvitation()

        fake.acceptResult = .failure(GoneError())
        fake.myPendingInvitationResult = .success(MyPendingInvitationResponse(found: false, invitationId: nil, status: nil, isExpired: nil, expiresAt: nil, primaryDisplayName: nil, invitedEmail: nil))

        await popup.accept()

        XCTAssertTrue(popup.shouldPresentPopup, "no replacement invitation exists — must not silently dismiss")
        guard case .found(let stillShowing) = popup.state else {
            XCTFail("state must remain .found"); return
        }
        XCTAssertEqual(stillShowing.invitationId, invitationId, "must keep showing the original invitation, not blank out")
    }

    @MainActor
    func testDeclineFailureAgainstASupersededInvitationRefreshesToTheCurrentOne() async {
        struct StaleInvitationError: Error {}
        let staleInvitationId = UUID()
        let freshInvitationId = UUID()
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        fake.myPendingInvitationResult = .success(MyPendingInvitationResponse(
            found: true, invitationId: staleInvitationId, status: "pending", isExpired: false,
            expiresAt: Date().addingTimeInterval(600), primaryDisplayName: nil, invitedEmail: nil
        ))
        let popup = PendingInvitationPopupViewModel(backend: fake)
        await popup.checkForPendingInvitation()

        fake.declineResult = .failure(StaleInvitationError())
        fake.myPendingInvitationResult = .success(MyPendingInvitationResponse(
            found: true, invitationId: freshInvitationId, status: "pending", isExpired: false,
            expiresAt: Date().addingTimeInterval(600), primaryDisplayName: nil, invitedEmail: nil
        ))

        await popup.decline()

        XCTAssertFalse(popup.didDecline)
        XCTAssertNotNil(popup.declineError)
        XCTAssertTrue(popup.shouldPresentPopup)
        guard case .found(let refreshed) = popup.state else {
            XCTFail("expected state to refresh to the current invitation"); return
        }
        XCTAssertEqual(refreshed.invitationId, freshInvitationId)
    }

