    // MARK: - Phase 9: Secondary read-only shared-data — discovery payload decode

    private func decode<T: Decodable>(_ type: T.Type, from json: String) throws -> T {
        let decoder = JSONDecoder()
        decoder.dateDecodingStrategy = .iso8601
        return try decoder.decode(T.self, from: Data(json.utf8))
    }

    func testDecodeSecondaryDiscoveryPayload() throws {
        let json = """
        {
          "household_id": "\(UUID().uuidString)",
          "role": "secondary",
          "status": "active",
          "secondary_member": null,
          "pending_invitation": null,
          "sharing_permissions": [],
          "connected_accounts": [],
          "manual_accounts": [],
          "primary_user_id": "\(UUID().uuidString)",
          "primary_shared_connected_accounts": [],
          "primary_shared_manual_accounts": [],
          "primary_monthly_plan_shared": true
        }
        """
        let response = try decode(AccountRelatedOptionsResponse.self, from: json)
        XCTAssertNotNil(response.primaryUserId)
        XCTAssertTrue(response.primaryMonthlyPlanShared)
    }

    func testDecodePrimaryResponseMissingPhase9FieldsDoesNotThrow() throws {
        // The real Primary-branch response never includes any primary_* key at all (see
        // get-account-related-options's own Primary branch, unmodified by Phase 9) — must decode
        // cleanly with safe defaults, never throw.
        let json = """
        {
          "household_id": "\(UUID().uuidString)",
          "role": "primary",
          "status": "active",
          "secondary_member": null,
          "pending_invitation": null,
          "sharing_permissions": [],
          "connected_accounts": [],
          "manual_accounts": []
        }
        """
        let response = try decode(AccountRelatedOptionsResponse.self, from: json)
        XCTAssertNil(response.primaryUserId)
        XCTAssertTrue(response.primarySharedConnectedAccounts.isEmpty)
