    // MARK: - PHASE B REFRESH — shared Manual Account RE-FETCH

    /// The Refresh control must call the SAME already-authorized read (`load()`), never a
    /// mutation — proving RE-FETCH semantics, not a hidden write.
    @MainActor
    func testSharedManualAccountRefreshReFetchesWithoutMutation() async {
        let account = SharedManualAccountDTO(id: UUID(), name: "Wells Fargo Checking", accountType: "checking")
        let detail = SharedManualAccountDetailDTO(
            id: account.id, name: account.name, accountType: account.accountType, currentBalance: 100,
            institutionName: "Wells Fargo", lastFourDigits: "1234", showsInRecentActivity: true,
            updatedAt: .now, transactions: []
        )
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        fake.sharedManualAccountDataResult = .success(SharedManualAccountDataResponse(account: detail))
        let viewModel = SharedManualAccountViewModel(account: account, backend: fake)

        await viewModel.load()
        XCTAssertEqual(fake.getSharedManualAccountDataCallCount, 1)
        guard case .loaded(let first?) = viewModel.state else { return XCTFail("expected initial load to succeed") }
        XCTAssertEqual(first.currentBalance, 100)

        // Simulate the Primary having updated their balance server-side between loads.
        let updatedDetail = SharedManualAccountDetailDTO(
            id: account.id, name: account.name, accountType: account.accountType, currentBalance: 250,
            institutionName: "Wells Fargo", lastFourDigits: "1234", showsInRecentActivity: true,
            updatedAt: .now, transactions: []
        )
        fake.sharedManualAccountDataResult = .success(SharedManualAccountDataResponse(account: updatedDetail))

        // A second load() call is exactly what the Refresh button triggers.
        await viewModel.load()
        XCTAssertEqual(fake.getSharedManualAccountDataCallCount, 2, "Refresh must re-call the same read endpoint, not something new")
        guard case .loaded(let second?) = viewModel.state else { return XCTFail("expected refresh to succeed") }
        XCTAssertEqual(second.currentBalance, 250, "refresh must reflect the newest server data")
    }

    /// The refresh-in-progress state must never blank already-loaded content — matches
    /// `AccountRelatedOptionsViewModel.refresh()`'s own established "no full-screen flash after
    /// initial load" convention.
    @MainActor
    func testSharedManualAccountRefreshDoesNotBlankAlreadyLoadedState() async {
        let account = SharedManualAccountDTO(id: UUID(), name: "Wells Fargo Checking", accountType: "checking")
        let detail = SharedManualAccountDetailDTO(
            id: account.id, name: account.name, accountType: account.accountType, currentBalance: 100,
            institutionName: "Wells Fargo", lastFourDigits: "1234", showsInRecentActivity: true,
            updatedAt: .now, transactions: []
        )
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        fake.sharedManualAccountDataResult = .success(SharedManualAccountDataResponse(account: detail))
        let viewModel = SharedManualAccountViewModel(account: account, backend: fake)
        await viewModel.load()

        XCTAssertFalse(viewModel.isRefreshing)
        let refreshTask = Task { await viewModel.load() }
        // `state` must remain `.loaded` throughout — never `.loading` — for a refresh after the
        // first successful load. We can't observe the exact mid-flight instant deterministically
        // without a hook, but the FakeHouseholdSharingService's call is synchronous-enough here
        // that asserting immediately after await still verifies the end state never regressed.
        await refreshTask.value
        guard case .loaded = viewModel.state else { return XCTFail("state must still be .loaded after a refresh, never .loading/.failed") }
        XCTAssertFalse(viewModel.isRefreshing, "isRefreshing must reset to false once the refresh completes")
    }

    /// A failed refresh (e.g. transient network error) must leave the last-known-good `state`
    /// untouched — the screen keeps showing the previously-loaded data, not an error/blank state.
    @MainActor
    func testSharedManualAccountFailedRefreshPreservesLastKnownGoodState() async {
        struct DummyError: Error {}
        let account = SharedManualAccountDTO(id: UUID(), name: "Wells Fargo Checking", accountType: "checking")
        let detail = SharedManualAccountDetailDTO(
            id: account.id, name: account.name, accountType: account.accountType, currentBalance: 100,
            institutionName: "Wells Fargo", lastFourDigits: "1234", showsInRecentActivity: true,
            updatedAt: .now, transactions: []
        )
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        fake.sharedManualAccountDataResult = .success(SharedManualAccountDataResponse(account: detail))
        let viewModel = SharedManualAccountViewModel(account: account, backend: fake)
        await viewModel.load()

        fake.sharedManualAccountDataResult = .failure(DummyError())
        await viewModel.load()

        guard case .loaded(let stillDetail?) = viewModel.state else {
            return XCTFail("a failed silent refresh must never clear a previously-loaded state")
        }
        XCTAssertEqual(stillDetail.currentBalance, 100)
    }

    /// RE-FETCH must never call Plaid — proves this by source inspection of the view model that
    /// backs the Refresh button: it may only ever reference the existing
    /// `getSharedManualAccountData` read, never a Plaid-related type/function name.
    func testSharedManualAccountRefreshNeverCallsPlaid() throws {
