    @MainActor
    func testSharedMonthlySavingsViewModelClearsOnRevocation() async {
        let primaryUserId = UUID()
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        fake.sharedMonthlySavingsSummaryResult = .success(SharedMonthlySavingsSummaryResponse(
            summary: SharedMonthlySavingsSummaryDTO(savedThisMonth: 500, totalSavingsToDate: 1650, updatedAt: Date())
        ))
        let viewModel = SharedMonthlySavingsViewModel(primaryUserId: primaryUserId, backend: fake)
        await viewModel.load()
        guard case .loaded(.some) = viewModel.state else { return XCTFail("expected an initially-loaded summary") }

        // Primary revokes — the server now returns `summary: null`, matching the anti-enumeration
        // contract this project uses everywhere else.
        fake.sharedMonthlySavingsSummaryResult = .success(SharedMonthlySavingsSummaryResponse(summary: nil))
        await viewModel.load()

        guard case .loaded(let summary) = viewModel.state else { return XCTFail("expected .loaded") }
        XCTAssertNil(summary, "revocation must clear the previously-held summary on the very next load")
    }

