    /// Builds a `SharedMonthlyOutlookViewModel` fixture: one active income source (so
    /// `flexibleSpendingAvailable`/`recommendedWeeklySpendingLimit` are non-zero), no recurring
    /// expenses/savings goal, backed by a `FakeHouseholdSharingService`.
    private func makeOutlookFixture(
        incomeAmount: Decimal = 4000,
        savingsGoal: Decimal = 0
    ) -> (viewModel: SharedMonthlyOutlookViewModel, fake: FakeHouseholdSharingService, primaryUserId: UUID) {
        let primaryUserId = UUID()
        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        let income = SharedIncomeSourceDTO(
            id: UUID(), name: "Paycheck", amount: incomeAmount, frequency: "monthly",
            isActive: true, nextPayDate: nil, note: nil
        )
        let plan = SharedMonthlyPlanDTO(
            monthlySavingsGoal: savingsGoal, bufferAmount: nil, autoUpdateWeeklyBudgetFromPlan: false,
            updatedAt: Date(), incomeSources: [income], recurringExpenses: []
        )
        fake.sharedMonthlyPlanResult = .success(SharedMonthlyPlanResponse(plan: plan))
        let viewModel = SharedMonthlyOutlookViewModel(primaryUserId: primaryUserId, backend: fake)
        return (viewModel, fake, primaryUserId)
    }

    private func makeConnectedTransaction(amount: Decimal, date: Date = .now) -> SharedConnectedAccountTransactionDTO {
        SharedConnectedAccountTransactionDTO(
            id: UUID(), transactionId: UUID().uuidString, pendingTransactionId: nil,
            originalDescription: "TEST", merchantName: nil, amount: amount,
            authorizedDate: nil, postedDate: nil, transactionDate: date, isPending: false,
            createdAt: date, updatedAt: date
        )
    }

    private func makeManualDetail(accountId: UUID, name: String, amount: Decimal, date: Date = .now) -> SharedManualAccountDetailDTO {
        let transaction = SharedManualTransactionDTO(
            id: UUID(), amount: amount, transactionType: "expense",
            transactionDate: date, note: "Test", categoryName: nil, isPending: false, updatedAt: date
        )
        return SharedManualAccountDetailDTO(
            id: accountId, name: name, accountType: "checking", currentBalance: nil,
            institutionName: nil, lastFourDigits: nil, showsInRecentActivity: true,
            updatedAt: date, transactions: [transaction]
        )
    }

