    /// Revoking a shared Connected Account: the NEXT authorized `load()` (passing an account list
    /// that no longer includes it) must still query only the currently-authorized set, and its
    /// contribution to Actual Monthly Spending must drop out along with it.
    @MainActor
    func testSharedMonthlyOutlookRevocationRemovesConnectedAccountContribution() async {
        let (viewModel, fake, _) = makeOutlookFixture()
        let revoked = SharedConnectedAccountDTO(plaidAccountId: UUID(), name: "Delta", mask: "1111")
        let stillShared = SharedConnectedAccountDTO(plaidAccountId: UUID(), name: "Chase", mask: "2222")
        fake.sharedConnectedAccountTransactionsResultsByAccountId[revoked.plaidAccountId] = .success(
            SharedConnectedAccountTransactionsResponse(transactions: [makeConnectedTransaction(amount: 42)])
        )
        fake.sharedConnectedAccountTransactionsResultsByAccountId[stillShared.plaidAccountId] = .success(
            SharedConnectedAccountTransactionsResponse(transactions: [makeConnectedTransaction(amount: 10)])
        )

        await viewModel.load(connectedAccounts: [revoked, stillShared], manualAccounts: [])
        guard case .loaded(let before?) = viewModel.state else { return XCTFail("expected a loaded summary") }
        XCTAssertEqual(before.actualSpentThisMonth, 52, "both shared connected accounts must contribute — 42 + 10")
        XCTAssertEqual(Set(fake.requestedSharedConnectedAccountTransactionIds), [revoked.plaidAccountId, stillShared.plaidAccountId])

        // The Primary revoked `revoked` — the caller (SharedMonthlyPlanView) now supplies a list
        // that no longer contains it, exactly as AccountRelatedOptionsViewModel.response would
        // reflect after its own next authorized refresh.
        await viewModel.load(connectedAccounts: [stillShared], manualAccounts: [])
        guard case .loaded(let after?) = viewModel.state else { return XCTFail("expected a loaded summary") }
        XCTAssertEqual(after.actualSpentThisMonth, 10, "only the still-shared account's contribution remains")
        XCTAssertFalse(fake.requestedSharedConnectedAccountTransactionIds.suffix(1).contains(revoked.plaidAccountId), "the revoked account must no longer be queried at all")
    }

