        XCTAssertNil(dto.availableBalance)
        XCTAssertNil(dto.creditLimit)
        XCTAssertNil(dto.accountType)
        XCTAssertNil(dto.updatedAt)
    }

    /// PHASE B PARITY FIX, STEP 1 — the actual behavioral proof: a shared account's computed
    /// Dashboard `Display` must carry the SAME `primaryRow` (via the SAME `PlaidBalanceFormatter`)
    /// an owned account with equivalent Plaid data would show, including correct credit-card
    /// terminology ("Balance Owed", not "Current Balance"), and the DTO's own `updatedAt`.
    func testSharedConnectedAccountDisplayComputesSameBalanceRowAsOwned() {
        let sharedCredit = SharedConnectedAccountDTO(
            plaidAccountId: UUID(), name: "Delta SkyMiles® Reserve Card", mask: "2000",
            currentBalance: 482.17, availableBalance: 1517.83, creditLimit: 2000,
            accountType: "credit", updatedAt: Date(timeIntervalSince1970: 1_800_000_000)
        )
        let ownedEquivalent = PlaidAccountBalance(
            accountId: "acct-1", name: "Delta SkyMiles® Reserve Card", officialName: nil, mask: "2000",
            type: "credit", subtype: nil, currentBalance: 482.17, availableBalance: 1517.83,
            creditLimit: 2000, isoCurrencyCode: nil, unofficialCurrencyCode: nil
        )
        let sharedBalance = PlaidAccountBalance(
            accountId: sharedCredit.plaidAccountId.uuidString, name: sharedCredit.name, officialName: nil,
            mask: sharedCredit.mask, type: sharedCredit.accountType, subtype: nil,
            currentBalance: sharedCredit.currentBalance, availableBalance: sharedCredit.availableBalance,
            creditLimit: sharedCredit.creditLimit, isoCurrencyCode: nil, unofficialCurrencyCode: nil
        )
        XCTAssertEqual(PlaidBalanceFormatter.rows(for: sharedBalance), PlaidBalanceFormatter.rows(for: ownedEquivalent))
        XCTAssertEqual(PlaidBalanceFormatter.rows(for: sharedBalance).first?.label, "Balance Owed")
    }

