    @MainActor
    func testSharedActivityAggregatorNeverTouchesSwiftDataOrCalculationInputs() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack/Services/SharedPrimaryDataViewModels.swift")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        guard let range = source.range(of: "final class SharedActivityViewModel") else {
            XCTFail("SharedActivityViewModel not found"); return
        }
        // PHASE B added `SharedMonthlyOutlookViewModel` later in this same file, which
        // deliberately DOES construct transient `FinanceTransaction` instances (see its own
        // header) — bounded here so this test only ever inspects `SharedActivityViewModel`
        // itself, never a later, intentionally-different type.
        let sectionEnd = source.range(of: "\n/// POST-PHASE-10 CORRECTION", range: range.upperBound..<source.endIndex)?.lowerBound ?? source.endIndex
        let section = String(source[range.lowerBound..<sectionEnd])
        // Checks for actual type construction/usage, not a bare substring — this type's own doc
        // comment legitimately names `FinanceTransaction` by name when explaining why it's unused.
        XCTAssertFalse(section.contains("FinanceTransaction("), "must never construct the owned SwiftData transaction type")
        XCTAssertFalse(section.contains(": FinanceTransaction"), "must never type anything here as the owned SwiftData transaction type")
        XCTAssertFalse(section.contains("BudgetCalculator."), "shared activity must never feed User B's spending calculations")
        XCTAssertFalse(section.contains("ModelContext("))
        XCTAssertFalse(section.contains("modelContext.insert"))
    }

