    @MainActor
    func testDebugBypassRefreshUpdatesBalanceAndTransactionsWithoutClaimingQuota() async throws {
        let manager = PlaidConnectionManager(defaults: makeIsolatedDefaults())
        manager.addOrUpdate(connectionId: "conn-1", institutionId: "ins_1", institutionName: "Some Bank")
        let context = makePlaidSyncTestContext()
        let fake = FakeBalanceAndTransactionsPlaidBackendService(
            refreshResult: .success(ConnectedAccountRefreshResult(balance: makeBalance(accountId: "acc-A", current: 1), remaining: 1))
        )
        fake.syncBalancesResult = .success([makeBalance(accountId: "acc-A", current: 500)])
        fake.syncTransactionsResult = .success(PlaidSyncResult(added: [makePlaidDTO(id: "debug-txn-1")], modified: [], removedExternalIds: []))

        let returned = try await manager.refreshAccountBalanceAndTransactionsIgnoringDevelopmentQuota(
            connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake
        )

        XCTAssertEqual(returned?.currentBalance, 500)
        XCTAssertEqual(manager.connections.first?.cachedBalances?["acc-A"]?.currentBalance, 500)
        XCTAssertEqual(fake.refreshConnectedAccountCallCount, 0, "the DEBUG bypass must never call the quota-claiming endpoint")
        XCTAssertEqual(fake.syncBalancesCallCount, 1, "must use the unlimited syncBalances operation exactly once")
        let imported = try context.fetch(FetchDescriptor<FinanceTransaction>()).filter { $0.externalTransactionId == "debug-txn-1" }
        XCTAssertEqual(imported.count, 1, "must still import the newly available transaction")
