    @MainActor
    func testDebugBypassRefreshNeverDuplicatesTransactionsAcrossRepeatedCalls() async throws {
        let manager = PlaidConnectionManager(defaults: makeIsolatedDefaults())
        manager.addOrUpdate(connectionId: "conn-1", institutionId: "ins_1", institutionName: "Some Bank")
        let context = makePlaidSyncTestContext()
        let fake = FakeBalanceAndTransactionsPlaidBackendService(
            refreshResult: .success(ConnectedAccountRefreshResult(balance: makeBalance(accountId: "acc-A", current: 1), remaining: 1))
        )
        fake.syncBalancesResult = .success([makeBalance(accountId: "acc-A", current: 500)])
        fake.syncTransactionsResult = .success(PlaidSyncResult(added: [makePlaidDTO(id: "debug-dup-1")], modified: [], removedExternalIds: []))

        _ = try await manager.refreshAccountBalanceAndTransactionsIgnoringDevelopmentQuota(connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake)
        // Repeated DEBUG-unlimited refresh, matching the whole point of this feature — must never
        // duplicate a transaction Plaid re-reports as "modified".
        fake.syncTransactionsResult = .success(PlaidSyncResult(added: [], modified: [makePlaidDTO(id: "debug-dup-1", amount: 12.34)], removedExternalIds: []))
        _ = try await manager.refreshAccountBalanceAndTransactionsIgnoringDevelopmentQuota(connectionId: "conn-1", accountId: "acc-A", context: context, backend: fake)

        let matching = try context.fetch(FetchDescriptor<FinanceTransaction>()).filter { $0.externalTransactionId == "debug-dup-1" }
        XCTAssertEqual(matching.count, 1, "repeated DEBUG-unlimited refreshes must never duplicate the same transaction")
    }

