    /// 3/4/5 — monthlySpendRemaining/monthlySpendingBudget/actualSpentThisMonth remain formula-derived
    /// as before; TEST-ONLY fixture amounts — see `testProductionSourceContainsNoHardcodedExampleFinancialLiterals`.
    @MainActor
    func testPrimaryDashboardSummarySyncMatchesDashboardViewsOwnMonthlyRemainingFormula() async {
        let calendar = Self.calendar(timeZoneIdentifier: "America/New_York")
        // Root cause of a prior flaky failure here: `month`/`week` were derived from the LIVE
        // current date (`currentMonthRange`/`currentWeekRange`), and the fixture below places its
        // transaction at `month.start` expecting it to fall OUTSIDE the current week — true most
        // days, but false whenever "now" is close enough to the 1st of the month that the current
        // week actually reaches back to include the 1st (e.g. "now" = August 1st, whose
        // Sunday-start week begins July 26th and therefore already contains August 1st). Fixed by
        // anchoring both intervals to a FIXED mid-month date (the 15th) instead of the live "now":
        // a 7-day week centered anywhere from the 9th to the 21st of a month can never reach back
        // to the 1st, so `month.start` is guaranteed to fall outside `week` for any month length or
        // week-start convention — not just most calendar dates.
        let anchor = day(2026, 6, 15, calendar: calendar)
        let month = DateRangeHelper.monthRangeContaining(anchor, calendar: calendar)
        let week = DateRangeHelper.weekRangeContaining(anchor, weekStartsOnSunday: true, calendar: calendar)
        let incomeAmount: Decimal = 10200
        let fixedAmount: Decimal = 6859
        let savingsGoal: Decimal = 1000
        let actualAmount: Decimal = 97.50
        let account = Account(name: "General", type: .checking)
        let expense = FinanceTransaction(amount: actualAmount, date: month.start.addingTimeInterval(3600), type: .expense, source: .manual, account: account)

        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        await PrimaryDashboardSummarySyncService.sync(
            transactions: [expense],
            incomeSources: [makeIncome(amount: incomeAmount)],
            recurringExpenses: [RecurringExpense(name: "Bills", amount: fixedAmount, frequency: .monthly)],
            planSettings: MonthlyPlanSettings(monthlySavingsGoal: savingsGoal, bufferAmount: nil, autoUpdateWeeklyBudgetFromPlan: false),
            authoritativeWeeklyLimit: 777.77,
            monthlyOutlookBudgeted: nil,
            currentWeekIndex: nil,
            weekInterval: week,
            monthInterval: month,
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70,
            backend: fake
        )

        let expectedBudget = incomeAmount - fixedAmount - savingsGoal
        let expectedRemaining = expectedBudget - actualAmount

        guard let request = fake.lastUpsertDashboardSummaryRequest else { return XCTFail("expected an upsert call") }
        XCTAssertEqual(Decimal(string: request.actualSpentThisMonth), actualAmount)
        XCTAssertEqual(Decimal(string: request.monthlySpendRemaining), expectedRemaining)
        XCTAssertEqual(request.actualSpentThisWeek, "0")
    }

    /// USER B WEEKLY PARITY — the pushed `weeklySpendingLimit`/`weeklyRemaining` must come from the
    /// SUPPLIED `authoritativeWeeklyLimit` (the same value `DashboardView.weeklyLimit` currently
    /// displays), never a fresh `monthlySpendRemaining / 4` recomputation. The fixture income/
    /// expenses/savings-goal are chosen so `monthlySpendRemaining / 4` would produce a DIFFERENT
    /// number than the supplied limit — proving the pushed value's actual SOURCE, not an arithmetic
    /// coincidence.
    @MainActor
    func testPrimaryDashboardSummarySyncUsesSuppliedAuthoritativeWeeklyLimitNotRecomputedOne() async {
        let calendar = Self.calendar(timeZoneIdentifier: "America/New_York")
        let month = DateRangeHelper.currentMonthRange(calendar: calendar)
        let week = DateRangeHelper.currentWeekRange(weekStartsOnSunday: true, calendar: calendar)
        let account = Account(name: "General", type: .checking)
        let weekSpent: Decimal = 10.00
        let weekExpense = FinanceTransaction(amount: weekSpent, date: week.start.addingTimeInterval(3600), type: .expense, source: .manual, account: account)
        // monthlySpendRemaining here = 10200 - 6859 - 1000 - 10 = 2331, so monthlySpendRemaining / 4
        // = 582.75 — deliberately different from the supplied authoritativeWeeklyLimit below, so a
        // test failure here can only mean the service reverted to recomputing instead of using the
        // supplied value.
        let suppliedWeeklyLimit: Decimal = 560.875

        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        await PrimaryDashboardSummarySyncService.sync(
            transactions: [weekExpense],
            incomeSources: [makeIncome(amount: 10200)],
            recurringExpenses: [RecurringExpense(name: "Bills", amount: 6859, frequency: .monthly)],
            planSettings: MonthlyPlanSettings(monthlySavingsGoal: 1000, bufferAmount: nil, autoUpdateWeeklyBudgetFromPlan: false),
            authoritativeWeeklyLimit: suppliedWeeklyLimit,
            monthlyOutlookBudgeted: nil,
            currentWeekIndex: nil,
            weekInterval: week,
            monthInterval: month,
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70,
            backend: fake
        )

        guard let request = fake.lastUpsertDashboardSummaryRequest else { return XCTFail("expected an upsert call") }
        XCTAssertEqual(Decimal(string: request.weeklySpendingLimit), suppliedWeeklyLimit, "must use the supplied authoritative limit, never monthlySpendRemaining / 4")
        XCTAssertNotEqual(Decimal(string: request.weeklySpendingLimit), 582.75, "the recomputed-from-scratch value must never appear")
        // weeklyRemaining = authoritative supplied limit − actualSpentThisWeek, via the existing
        // canonical BudgetCalculator.remaining helper — proven with a deliberately non-round result.
        XCTAssertEqual(Decimal(string: request.actualSpentThisWeek), weekSpent)
        XCTAssertEqual(Decimal(string: request.weeklyRemaining), suppliedWeeklyLimit - weekSpent, "550.875 — supplied limit minus actual spent this week, via BudgetCalculator.remaining")
    }

    func testSharedDashboardSummaryResponseDecodesDollarStringsAsDecimals() throws {
        let json = """
        {"summary":{"actual_spent_this_month":"97.50","monthly_spend_remaining":"2243.50","weekly_spending_limit":"560.875","actual_spent_this_week":"0","weekly_remaining":"560.875","monthly_spending_budget":"2341","updated_at":"2026-07-29T09:41:22.985528+00:00"}}
