        // MONTHLY OUTLOOK + SCENARIO PERIOD-CASH-FLOW CORRECTION: `BudgetSettings.monthlyGoal`
        // mirrors the Savings Goal, not planned spending — that was the exact root cause of the
        // $0.00 Budgeted defect when the Savings Goal was $0. Updated to check the corrected,
        // planning-based figure (Planned Weekly Spending × 4).
        XCTAssertTrue(section.contains("monthlyOutlookBudgeted: plannedMonthlySpendingForOutlook"), "must upload Planned Monthly Spending as the Budgeted figure")
        XCTAssertFalse(section.contains("monthlyOutlookBudgeted: settings?.monthlyGoal"), "must never upload the Savings-Goal-mirroring field as Budgeted")
    }

    /// 2 — the pushed Monthly Outlook Actual/Projected Savings/Status are the SAME
    /// `MonthlyPlanCalculator.summary` figures `DashboardView.monthlyPlanSummary` itself uses —
    /// never a second, independently-computed value. TEST-ONLY fixture amounts.
    @MainActor
    func testPrimaryDashboardSummarySyncUploadsCanonicalMonthlyOutlookActualProjectedSavingsStatus() async {
        let calendar = Self.calendar(timeZoneIdentifier: "America/New_York")
        let month = DateRangeHelper.currentMonthRange(calendar: calendar)
        let week = DateRangeHelper.currentWeekRange(weekStartsOnSunday: true, calendar: calendar)
        let incomeAmount: Decimal = 9000
        let fixedAmount: Decimal = 5000
        let savingsGoal: Decimal = 800
        let actualAmount: Decimal = 250.75
        let account = Account(name: "General", type: .checking)
        let expense = FinanceTransaction(amount: actualAmount, date: month.start.addingTimeInterval(3600), type: .expense, source: .manual, account: account)
        let expectedSummary = MonthlyPlanCalculator.summary(
            month: month, incomeSources: [makeIncome(amount: incomeAmount)],
            recurringExpenses: [RecurringExpense(name: "Bills", amount: fixedAmount, frequency: .monthly)],
            planSettings: MonthlyPlanSettings(monthlySavingsGoal: savingsGoal, bufferAmount: nil, autoUpdateWeeklyBudgetFromPlan: false),
            weeklyBudgetLimit: 0, transactions: [expense], weekInterval: week, weekStartsOnSunday: true,
            includePending: true, warningThreshold: 0.70
        )

        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        await PrimaryDashboardSummarySyncService.sync(
            transactions: [expense],
            incomeSources: [makeIncome(amount: incomeAmount)],
            recurringExpenses: [RecurringExpense(name: "Bills", amount: fixedAmount, frequency: .monthly)],
            planSettings: MonthlyPlanSettings(monthlySavingsGoal: savingsGoal, bufferAmount: nil, autoUpdateWeeklyBudgetFromPlan: false),
            authoritativeWeeklyLimit: 123.45,
            monthlyOutlookBudgeted: 1000,
            currentWeekIndex: nil,
            weekInterval: week,
            monthInterval: month,
            weekStartsOnSunday: true,
            includePending: true,
            warningThreshold: 0.70,
            backend: fake
        )

        // MONTHLY OUTLOOK + SCENARIO PERIOD-CASH-FLOW CORRECTION — Projected Savings/Status are
        // now the planning-based figures, not `expectedSummary.projectedMonthlySavings`/
        // `.projectedStatus` (the legacy actual-spending formula, still correct for its own
        // unrelated consumers but no longer what this sync uploads). income(9000) −
        // fixed(5000) − goal(800) − buffer(0) = flexible 3200; automatic weekly = 800;
        // planned monthly = 3200; additional = 3200 − 3200 = 0; projected = 800 + 0 = 800.
        let automaticWeekly = MonthlyPlanCalculator.automaticPlannedWeeklySpending(flexibleSpendingAvailable: expectedSummary.flexibleSpendingAvailable)
        let plannedMonthly = MonthlyPlanCalculator.plannedMonthlySpending(plannedWeeklySpending: automaticWeekly)
        let additional = MonthlyPlanCalculator.additionalPlannedSavings(flexibleSpendingAvailable: expectedSummary.flexibleSpendingAvailable, plannedMonthlySpending: plannedMonthly)
        let expectedProjected = MonthlyPlanCalculator.projectedSavingsFromPlannedSpending(monthlySavingsGoal: expectedSummary.monthlySavingsGoal, additionalPlannedSavings: additional)
        let expectedStatus = MonthlyPlanCalculator.monthlyPlanStatus(projectedSavings: expectedProjected, savingsGoal: expectedSummary.monthlySavingsGoal)

        guard let request = fake.lastUpsertDashboardSummaryRequest else { return XCTFail("expected an upsert call") }
        XCTAssertEqual(request.monthlyOutlookBudgeted.flatMap { Decimal(string: $0) }, 1000)
        XCTAssertEqual(request.monthlyOutlookActual.flatMap { Decimal(string: $0) }, expectedSummary.actualSpentThisMonth)
        XCTAssertEqual(request.monthlyOutlookProjectedSavings.flatMap { Decimal(string: $0) }, expectedProjected)
        XCTAssertEqual(request.monthlyOutlookStatus, SpendingStatusWireCoding.wireValue(expectedStatus))
    }

    /// 3 — the uploaded current-plan-week index must be whichever week actually contains today,
    /// even when that is NOT index 0 — proving the service never silently substitutes the first
    /// week. Skips gracefully if the current fixture month happens to only have one week.
    @MainActor
    func testCurrentWeekIndexUploadedVerbatimEvenWhenNotZero() async throws {
        let calendar = Self.calendar(timeZoneIdentifier: "America/New_York")
        let month = DateRangeHelper.currentMonthRange(calendar: calendar)
        let week = DateRangeHelper.currentWeekRange(weekStartsOnSunday: true, calendar: calendar)
        let expectedSummary = MonthlyPlanCalculator.summary(
            month: month, incomeSources: [makeIncome(amount: 4000)], recurringExpenses: [],
            planSettings: nil, weeklyBudgetLimit: 0, transactions: [], weekInterval: week,
            weekStartsOnSunday: true, includePending: true, warningThreshold: 0.70
        )
        let comparisons = expectedSummary.weeklyComparisons
        guard let currentIndex = comparisons.firstIndex(where: { $0.weekInterval.contains(.now) }), comparisons.count > 1 else {
            throw XCTSkip("current fixture month has only one week — cannot prove non-zero index selection")
        }

        let fake = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        await PrimaryDashboardSummarySyncService.sync(
            transactions: [], incomeSources: [makeIncome(amount: 4000)], recurringExpenses: [],
            planSettings: nil, authoritativeWeeklyLimit: 100,
            monthlyOutlookBudgeted: nil, currentWeekIndex: currentIndex,
            weekInterval: week, monthInterval: month, weekStartsOnSunday: true,
            includePending: true, warningThreshold: 0.70, backend: fake
        )

        guard let request = fake.lastUpsertDashboardSummaryRequest else { return XCTFail("expected an upsert call") }
        XCTAssertEqual(request.currentPlanWeekIndex, currentIndex)
        XCTAssertEqual(request.currentPlanWeekNumber, currentIndex + 1)
        let expectedComparison = comparisons[currentIndex]
        XCTAssertEqual(request.currentPlanWeekRecommended.flatMap { Decimal(string: $0) }, expectedComparison.recommendedLimit)
        XCTAssertEqual(request.currentPlanWeekActual.flatMap { Decimal(string: $0) }, expectedComparison.actualSpent)
    }

