    /// 17 — date-only current-plan-week fields never shift across timezones: encoded via the SAME
    /// established `bareDateString`/`parseBareDate` helpers (never a `DateFormatter` with its own
    /// timezone), a date built in one timezone and decoded in a completely different one still
    /// yields the identical Y/M/D.
    func testCurrentPlanWeekDatesNeverShiftAcrossTimezones() throws {
        let sourceCalendar = Self.calendar(timeZoneIdentifier: "Pacific/Kiritimati") // UTC+14
        let start = sourceCalendar.date(from: DateComponents(year: 2026, month: 3, day: 1))!
        let end = sourceCalendar.date(from: DateComponents(year: 2026, month: 3, day: 7))!
        let currentPlanWeek = UpsertDashboardSummaryRequest.CurrentPlanWeek(
            index: 0, number: 1, startDate: start, endDate: end,
            recommended: 100, actual: 0, remaining: 100, status: .good, calendar: sourceCalendar
        )
        let request = UpsertDashboardSummaryRequest(
            actualSpentThisMonth: 0, monthlySpendRemaining: 0, weeklySpendingLimit: 0,
            actualSpentThisWeek: 0, weeklyRemaining: 0, currentPlanWeek: currentPlanWeek
        )
        XCTAssertEqual(request.currentPlanWeekStartDate, "2026-03-01")
        XCTAssertEqual(request.currentPlanWeekEndDate, "2026-03-07")

        let destinationCalendar = Self.calendar(timeZoneIdentifier: "Etc/GMT+12") // UTC-12
        guard let decodedStart = BackendTransactionDTO.parseBareDate(request.currentPlanWeekStartDate!, calendar: destinationCalendar) else {
            return XCTFail("expected a decodable bare date")
        }
        let decodedComponents = destinationCalendar.dateComponents([.year, .month, .day], from: decodedStart)
        XCTAssertEqual(decodedComponents.year, 2026)
        XCTAssertEqual(decodedComponents.month, 3)
        XCTAssertEqual(decodedComponents.day, 1, "the calendar day must never shift, regardless of source/destination timezone")
    }

    /// 18 — non-round decimal currency (cents) is preserved exactly through the upload wire format.
    func testCurrentPlanWeekDecimalCurrencyPreservesCentsThroughUpload() throws {
        let calendar = Self.calendar(timeZoneIdentifier: "America/New_York")
        let start = calendar.date(from: DateComponents(year: 2026, month: 7, day: 26))!
        let end = calendar.date(from: DateComponents(year: 2026, month: 8, day: 1))!
        let currentPlanWeek = UpsertDashboardSummaryRequest.CurrentPlanWeek(
            index: 4, number: 5, startDate: start, endDate: end,
            recommended: 468.20, actual: 10.00, remaining: 458.20, status: .good, calendar: calendar
        )
        let request = UpsertDashboardSummaryRequest(
            actualSpentThisMonth: 0, monthlySpendRemaining: 0, weeklySpendingLimit: 0,
            actualSpentThisWeek: 0, weeklyRemaining: 0, currentPlanWeek: currentPlanWeek
        )
        XCTAssertEqual(request.currentPlanWeekRecommended, "468.2")
        XCTAssertEqual(request.currentPlanWeekActual, "10")
        XCTAssertEqual(request.currentPlanWeekRemaining, "458.2")
        XCTAssertEqual(request.currentPlanWeekRecommended.flatMap { Decimal(string: $0) }, 468.20, "the cents must round-trip exactly even though Decimal's string form omits a trailing zero")
    }

