    /// 6 — the Release build configuration must never define `SPENDSMART_PREVIEW_BACKEND` anywhere
    /// in the generated project, independent of and in addition to the source-level `#if DEBUG`
    /// guard above — two independent reasons Release can never resolve to Preview, not one.
    func testReleaseConfigurationNeverDefinesPreviewBackendFlag() throws {
        let sourceURL = URL(fileURLWithPath: #filePath)
            .deletingLastPathComponent()
            .appendingPathComponent("../FinanceTrack.xcodeproj/project.pbxproj")
            .standardized
        let source = try String(contentsOf: sourceURL, encoding: .utf8)
        var releaseConfigCount = 0
        var searchRange = source.startIndex..<source.endIndex
        while let match = source.range(of: "name = Release;", range: searchRange) {
            releaseConfigCount += 1
            let blockStart = source.range(of: "isa = XCBuildConfiguration;", options: .backwards, range: source.startIndex..<match.lowerBound)?.lowerBound ?? source.startIndex
            let block = source[blockStart..<match.upperBound]
            XCTAssertFalse(block.contains("SPENDSMART_PREVIEW_BACKEND"), "no Release XCBuildConfiguration block may define SPENDSMART_PREVIEW_BACKEND")
            searchRange = match.upperBound..<source.endIndex
        }
        XCTAssertGreaterThan(releaseConfigCount, 0, "sanity check: must have found at least one Release configuration block to inspect")
        XCTAssertTrue(source.contains("SPENDSMART_PREVIEW_BACKEND"), "sanity check: the flag must exist SOMEWHERE (the Debug Preview config) or this test proves nothing")
    }

