    // MARK: - Favorites Bar

    /// 1 — a freshly-created `FavoritesSettings` (the same "created on demand if none exists"
    /// pattern `BudgetSettings`/`FavoritesConfigurationView.favoritesSettings` already use) starts
    /// with zero favorites.
    func testFavoritesSettingsDefaultStateHasZeroFavorites() {
        let settings = FavoritesSettings()
        XCTAssertTrue(settings.orderedDestinationIDs.isEmpty)
        XCTAssertTrue(settings.validDestinationIDs.isEmpty)
    }

    /// 2/3/4 — the Dashboard bar's own visibility is `!favoriteDestinations.isEmpty` (see
    /// `DashboardView.favoritesBarSection`'s own `if` check) — `validDestinationIDs` (its
    /// underlying data source before eligibility filtering) is the exact proxy this test exercises
    /// directly: empty at zero favorites, non-empty the moment the first is added, empty again the
    /// moment the last is removed.
    func testFavoritesBarVisibilityProxyTracksSelectionCount() {
        let settings = FavoritesSettings()
        XCTAssertTrue(settings.validDestinationIDs.isEmpty, "zero favorites must mean the bar is hidden")

        XCTAssertTrue(settings.addFavorite(.monthlyPlan))
        XCTAssertFalse(settings.validDestinationIDs.isEmpty, "adding the first favorite must make the bar visible")

        settings.removeFavorite(.monthlyPlan)
        XCTAssertTrue(settings.validDestinationIDs.isEmpty, "removing the final favorite must hide the bar again")
    }

    /// 5 — favorites are stored, and read back, in the exact order added.
    func testFavoritesRetainSelectionOrder() {
        let settings = FavoritesSettings()
        settings.addFavorite(.backup)
        settings.addFavorite(.monthlyPlan)
        settings.addFavorite(.insights)
        XCTAssertEqual(settings.validDestinationIDs, [.backup, .monthlyPlan, .insights])
    }

    /// 6 — reordering (the same `Array.move` semantics `.onMove` hands `moveFavorites` in
    /// `FavoritesConfigurationView`) persists the new order.
    func testReorderingFavoritesPersistsNewOrder() {
        let settings = FavoritesSettings(orderedDestinationIDs: [
            FavoriteDestinationID.monthlyPlan.rawValue,
            FavoriteDestinationID.backup.rawValue,
            FavoriteDestinationID.insights.rawValue,
        ])
        settings.moveFavorites(fromOffsets: IndexSet(integer: 2), toOffset: 0)
        XCTAssertEqual(settings.validDestinationIDs, [.insights, .monthlyPlan, .backup])
    }

    /// 7 — adding an already-selected destination is a no-op: no duplicate entry, existing order
    /// unchanged.
    func testDuplicateFavoriteIDsCannotBeStored() {
        let settings = FavoritesSettings()
        XCTAssertTrue(settings.addFavorite(.monthlyPlan))
        XCTAssertFalse(settings.addFavorite(.monthlyPlan), "adding an already-selected destination must be rejected")
        XCTAssertEqual(settings.orderedDestinationIDs, [FavoriteDestinationID.monthlyPlan.rawValue])
    }

    /// 8 — a stale/unrecognized raw string (e.g. a destination removed in a future app version, or
    /// corrupted data) is silently dropped by `validDestinationIDs`, never crashes, never surfaces
    /// as a broken row.
    func testStaleOrUnknownFavoriteIDsAreHandledSafely() {
        let settings = FavoritesSettings(orderedDestinationIDs: [
            FavoriteDestinationID.monthlyPlan.rawValue,
            "some-destination-removed-in-a-future-version",
            FavoriteDestinationID.backup.rawValue,
        ])
        XCTAssertEqual(settings.validDestinationIDs, [.monthlyPlan, .backup], "an unrecognized id must be dropped, never crash, never appear as a resolved destination")
    }

    /// 13/14 — reaching the maximum blocks another addition, and the rejection leaves every
    /// existing favorite completely unchanged (never a silent replacement of the oldest one, never
    /// a reorder).
    func testMaximumCapacityBlocksAdditionAndLeavesExistingFavoritesUnchanged() {
        let settings = FavoritesSettings(orderedDestinationIDs: [
            FavoriteDestinationID.monthlyPlan.rawValue,
            FavoriteDestinationID.backup.rawValue,
        ])
        let before = settings.orderedDestinationIDs
        let added = settings.addFavorite(.insights, maximumCount: 2)
        XCTAssertFalse(added, "adding beyond the maximum must be rejected")
        XCTAssertEqual(settings.orderedDestinationIDs, before, "a rejected addition must leave the existing list completely unchanged")
    }

    /// 15 — removing one favorite after hitting capacity immediately allows another addition.
    func testRemovingOneFavoriteAfterCapacityAllowsAnotherAddition() {
        let settings = FavoritesSettings(orderedDestinationIDs: [
            FavoriteDestinationID.monthlyPlan.rawValue,
            FavoriteDestinationID.backup.rawValue,
        ])
        XCTAssertFalse(settings.addFavorite(.insights, maximumCount: 2))

        settings.removeFavorite(.backup)
        XCTAssertTrue(settings.addFavorite(.insights, maximumCount: 2), "removing one favorite must immediately free capacity for another")
        XCTAssertEqual(settings.validDestinationIDs, [.monthlyPlan, .insights])
    }

    /// 16 — a role-ineligible destination (`.accountSharing` before role resolution completes,
    /// mirroring the exact same `AccountRelatedOptionsViewModel.Visibility.hidden` gate
    /// `SettingsView`'s own Account Related Options row already uses) is not eligible.
    func testIneligibleRoleSpecificDestinationsAreUnavailable() {
        XCTAssertFalse(FavoriteDestinationID.isEligible(.accountSharing, accountRelatedOptionsVisibility: .hidden))
        XCTAssertTrue(FavoriteDestinationID.isEligible(.accountSharing, accountRelatedOptionsVisibility: .primary))
        XCTAssertTrue(FavoriteDestinationID.isEligible(.accountSharing, accountRelatedOptionsVisibility: .secondary))
        XCTAssertTrue(FavoriteDestinationID.isEligible(.accountSharing, accountRelatedOptionsVisibility: .entryPoint))
        // Every other destination is unconditionally eligible today — no role restriction exists
        // for them (each destination view already self-adapts to Primary/Secondary internally).
        for destination in FavoriteDestinationID.allCases where destination != .accountSharing {
            XCTAssertTrue(FavoriteDestinationID.isEligible(destination, accountRelatedOptionsVisibility: .hidden))
        }
