    // MARK: - Favorites Bar layout (pure, testable geometry)

    /// TITLED REFINEMENT — content width grows predictably: the sum of each button's own
    /// (label-driven) width, plus `n - 1` fixed gaps. Uses the SAME label repeated for every
    /// button so each one's measured width is identical, letting the additive formula be asserted
    /// exactly (mirroring the pre-refinement uniform-width test's own structure).
    func testFavoritesBarContentWidthAtEachCount() {
        let label = "Sharing"
        let width = FavoritesBarLayout.buttonWidth(forLabel: label)
        XCTAssertEqual(FavoritesBarLayout.contentWidth(labels: []), 0)
        XCTAssertEqual(FavoritesBarLayout.contentWidth(labels: [label]), width)
        XCTAssertEqual(FavoritesBarLayout.contentWidth(labels: [label, label]), 2 * width + FavoritesBarLayout.spacing)
        XCTAssertEqual(FavoritesBarLayout.contentWidth(labels: [label, label, label]), 3 * width + 2 * FavoritesBarLayout.spacing)
        XCTAssertEqual(FavoritesBarLayout.contentWidth(labels: [label, label, label, label]), 4 * width + 3 * FavoritesBarLayout.spacing)
    }

    /// A button's real width is at least the tap-target floor, and grows to fit a wider label —
    /// proving `buttonWidth(forLabel:)` measures real text rather than returning a fixed constant.
    func testFavoriteButtonWidthIsAtLeastTheFloorAndGrowsForWiderLabels() {
        XCTAssertGreaterThanOrEqual(FavoritesBarLayout.buttonWidth(forLabel: "Backup"), FavoritesBarLayout.minimumTapTargetSize)
        XCTAssertGreaterThan(
            FavoritesBarLayout.buttonWidth(forLabel: "A very much longer label than any real destination uses"),
            FavoritesBarLayout.minimumTapTargetSize,
            "a sufficiently wide label must grow the button past the 44pt floor, never be clipped/shrunk to fit it"
        )
    }

    /// Equal leading/trailing capsule padding by construction: capsule width minus content width is
    /// always exactly twice the (single, shared) horizontal padding constant — never a different
    /// value on each side. Exercised at every real favorite count, 1 through the locked maximum,
    /// using the ACTUAL Dashboard labels (not placeholders) so this also stands in for "the icon
    /// group remains centered at every count" — equal padding on both sides of a content-sized
    /// `HStack` inside a centered outer frame is exactly what keeps it centered.
    func testFavoritesBarCapsulePaddingIsAlwaysEqualOnBothSides() {
        let allLabels = FavoriteDestinationID.allCases.map(\.dashboardLabel)
        for count in 1...FavoritesBarLayout.maximumFavoritesCount {
            let labels = Array(allLabels.prefix(count))
            let padding = FavoritesBarLayout.capsuleWidth(labels: labels) - FavoritesBarLayout.contentWidth(labels: labels)
            XCTAssertEqual(padding, 2 * FavoritesBarLayout.horizontalPadding, "leading and trailing padding must be equal at every count, including \(count)")
        }
    }

