        XCTAssertEqual(settings.orderedDestinationIDs.count, FavoritesBarLayout.maximumFavoritesCount)

        settings.removeFavorite(.insights)
        XCTAssertTrue(
            settings.addFavorite(.insights, maximumCount: FavoritesBarLayout.maximumFavoritesCount),
            "removing one favorite must immediately free capacity for adding an eligible destination again"
        )
    }

