    // MARK: - Corrective pass — canonical-record creation/dedup (proven real-device bug fix)

    private func makeInMemoryFavoritesContext() -> ModelContext {
        let config = ModelConfiguration(isStoredInMemoryOnly: true, cloudKitDatabase: .none)
        let container = try! ModelContainer(for: FavoritesSettings.self, configurations: config)
        return ModelContext(container)
    }

    /// ROOT-CAUSE REGRESSION 6/7/8/9 — with no existing row, `resolveCanonicalRecord` creates
    /// exactly one, inserts it into the given context, and saves it — proven by fetching from a
    /// FRESH `ModelContext` against the same container afterward (not just reading the in-memory
    /// object back), which only succeeds if the save actually reached the store.
    func testFavoritesSettingsResolveCanonicalRecordCreatesInsertsAndSavesWhenNoneExists() throws {
        let context = makeInMemoryFavoritesContext()
        let record = FavoritesSettings.resolveCanonicalRecord(existing: [], in: context)
        XCTAssertTrue(record.orderedDestinationIDs.isEmpty)

        let freshContext = ModelContext(context.container)
        let fetched = try freshContext.fetch(FetchDescriptor<FavoritesSettings>())
        XCTAssertEqual(fetched.count, 1, "the created record must be durably saved, not just held in memory")
        XCTAssertEqual(fetched.first?.id, record.id)
    }

    /// ROOT-CAUSE REGRESSION — when exactly one row already exists, `resolveCanonicalRecord` is a
    /// pure no-op: returns that SAME instance, mutates nothing. This is what makes it safe to call
    /// from every mutation call site (`.onAppear`, `toggle`, `moveSelected`) without creating a new
    /// row on every single access — the exact bug this correction fixes.
    func testFavoritesSettingsResolveCanonicalRecordIsIdempotentWhenExactlyOneRowExists() {
        let context = makeInMemoryFavoritesContext()
        let existing = FavoritesSettings(orderedDestinationIDs: [FavoriteDestinationID.monthlyPlan.rawValue])
        context.insert(existing)

        let resolved = FavoritesSettings.resolveCanonicalRecord(existing: [existing], in: context)
        XCTAssertTrue(resolved === existing, "must return the SAME existing instance, never create a second one")
        XCTAssertEqual(resolved.orderedDestinationIDs, [FavoriteDestinationID.monthlyPlan.rawValue])
    }

    /// ROOT-CAUSE REGRESSION 14/15 — reconciles pre-existing duplicate rows (exactly the state a
    /// real device could already be in after hitting the proven bug) into ONE canonical record,
    /// merging every distinct destination id from every duplicate, first-seen order, never silently
    /// discarding a valid favorite just because it landed on a different duplicate row.
    func testFavoritesSettingsResolveCanonicalRecordMergesDuplicatesPreservingFirstSeenOrder() throws {
        let context = makeInMemoryFavoritesContext()
        // Explicit, deterministic ids (never random `UUID()`) so the `.id.uuidString` sort below —
        // the SAME sort both real screens' `@Query`s use — has a fixed, known outcome. Using random
        // ids here would make "first-seen order" flaky: which row sorts first by UUID has no
        // relationship to which one was constructed/inserted first.
        let first = FavoritesSettings(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000000001")!,
            orderedDestinationIDs: [
                FavoriteDestinationID.monthlyPlan.rawValue,
                FavoriteDestinationID.backup.rawValue,
            ]
        )
        let second = FavoritesSettings(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000000002")!,
            orderedDestinationIDs: [
                FavoriteDestinationID.backup.rawValue, // duplicate of one already in `first`
                FavoriteDestinationID.insights.rawValue,
            ]
        )
        context.insert(first)
        context.insert(second)
        let sorted = [first, second].sorted { $0.id.uuidString < $1.id.uuidString }
        XCTAssertEqual(sorted.map(\.id), [first.id, second.id], "sanity check: `first` must sort before `second` given these explicit ids")

        let survivor = FavoritesSettings.resolveCanonicalRecord(existing: sorted, in: context)
        XCTAssertEqual(survivor.validDestinationIDs, [.monthlyPlan, .backup, .insights], "every distinct id from every duplicate must survive, in first-seen order, with no duplicate entry")

        let freshContext = ModelContext(context.container)
        let remaining = try freshContext.fetch(FetchDescriptor<FavoritesSettings>())
        XCTAssertEqual(remaining.count, 1, "exactly one canonical row must remain after dedup — the duplicates must be deleted, not merely ignored")
    }

    /// THE EXACT REAL-DEVICE SYMPTOM, reproduced directly — a favorite added through one
    /// `ModelContext` (standing in for `FavoritesConfigurationView`'s environment context) must be
    /// visible through a SECOND, INDEPENDENT `ModelContext` against the SAME container (standing in
    /// for `DashboardView`'s own `@Query`) without any relaunch, using the exact same
    /// deterministically-sorted `.first` resolution both real views now use.
    func testFirstFavoriteAddedInOneContextIsImmediatelyVisibleInAnotherContextSortedTheSameWay() throws {
        let config = ModelConfiguration(isStoredInMemoryOnly: true, cloudKitDatabase: .none)
        let container = try ModelContainer(for: FavoritesSettings.self, configurations: config)

        let settingsContext = ModelContext(container)
        let record = FavoritesSettings.resolveCanonicalRecord(existing: [], in: settingsContext)
        record.addFavorite(.monthlyPlan)
        try settingsContext.save()

        let dashboardContext = ModelContext(container)
        let dashboardDescriptor = FetchDescriptor<FavoritesSettings>(sortBy: [SortDescriptor(\.id)])
        let dashboardView = try dashboardContext.fetch(dashboardDescriptor)
        XCTAssertEqual(dashboardView.first?.validDestinationIDs, [.monthlyPlan], "the Dashboard's own independent, identically-sorted query must see the favorite immediately, with no relaunch and no polling")
    }

    /// Source-scan proof that `DashboardView` and `FavoritesConfigurationView` declare their
    /// `@Query` for `FavoritesSettings` with the SAME explicit deterministic sort — the other half
    /// of the fix (alongside dedup) for the proven "two screens disagree on which row is `.first`"
    /// failure mode.
    func testFavoritesQueriesInBothScreensUseTheSameDeterministicSort() throws {
        for path in ["../FinanceTrack/Views/Dashboard/DashboardView.swift", "../FinanceTrack/Views/Settings/FavoritesConfigurationView.swift"] {
            let source = try Self.monthlySavingsSourceFile(path)
            XCTAssertTrue(source.contains("@Query(sort: \\FavoritesSettings.id) private var favoritesSettingsList"), "\(path) must sort its FavoritesSettings query deterministically by id")
        }
    }

    /// Source-scan proof of the actual root-cause fix: `FavoritesConfigurationView` no longer
    /// inserts a new `FavoritesSettings` as a side effect of a passive read (the exact bug), and
    /// every mutation site instead resolves the canonical record explicitly.
    func testFavoritesConfigurationViewNoLongerCreatesRecordsDuringPassiveRead() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/Settings/FavoritesConfigurationView.swift")
        XCTAssertFalse(
            source.contains("if let existing = favoritesSettingsList.first {\n            return existing\n        }\n        let created = FavoritesSettings()\n        modelContext.insert(created)\n        return created"),
            "the old create-on-every-access computed property must be gone"
        )
        XCTAssertTrue(source.contains("private var favoritesSettings: FavoritesSettings? {\n        favoritesSettingsList.first\n    }"), "reads must be a pure array read, never an insert")
        XCTAssertEqual(
            source.components(separatedBy: "FavoritesSettings.resolveCanonicalRecord(existing: favoritesSettingsList, in: modelContext)").count - 1,
            3,
            "resolveCanonicalRecord must be called from exactly the three mutation sites: onAppear, toggle, moveSelected"
        )
    }

