    // MARK: - "Favorites" Dashboard section heading

    /// 1/2/3 — source-scan proof (this project's own established pattern for verifying otherwise-
    /// untestable SwiftUI view-body glue, e.g. `testFavoriteNavigationMappingResolvesToExistingCanonicalDestinations`)
    /// that the "Favorites" heading and the capsule are inside the exact SAME
    /// `if !favoriteDestinations.isEmpty` branch — never two separate conditions that could let one
    /// appear without the other. This one source fact is what makes requirements 1 ("heading
    /// present whenever ≥1 eligible favorite is shown"), 2 ("heading absent whenever the capsule is
    /// hidden"), and 3 ("heading and capsule share one visibility condition") all true together:
    /// there is exactly one `if`, so there is exactly one outcome for both.
    func testFavoritesHeadingAndCapsuleShareTheExactSameVisibilityCondition() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/Dashboard/DashboardView.swift")
        guard let range = source.range(of: "private var favoritesBarSection: some View {") else {
            XCTFail("favoritesBarSection not found")
            return
        }
        let sectionBody = String(source[range.lowerBound...].prefix(900))
        // Exactly one `if` inside this section — proves there is no second, independent
        // visibility check that could desync the heading from the capsule.
        let ifCount = sectionBody.components(separatedBy: "if !favoriteDestinations.isEmpty").count - 1
        XCTAssertEqual(ifCount, 1, "the heading and capsule must be gated by exactly ONE shared `if !favoriteDestinations.isEmpty` — never a separate condition for each")
        XCTAssertTrue(sectionBody.contains("Text(\"Favorites\")"), "the \"Favorites\" heading must be present")
        XCTAssertTrue(sectionBody.contains("FavoritesBarView(destinations: favoriteDestinations)"), "the capsule must be present")
        // The heading must textually precede the capsule within the same branch (heading ABOVE
        // the capsule, per the locked placement requirement).
        guard let headingRange = sectionBody.range(of: "Text(\"Favorites\")"),
              let capsuleRange = sectionBody.range(of: "FavoritesBarView(destinations: favoriteDestinations)")
        else {
            XCTFail("could not locate heading/capsule within favoritesBarSection")
            return
        }
        XCTAssertTrue(headingRange.lowerBound < capsuleRange.lowerBound, "the heading must appear ABOVE the capsule")
    }

    /// 4 — an ineligible favorite must never suppress unrelated eligible favorites. `favoriteDestinations`
    /// (the single array both the heading's `!isEmpty` check and the capsule's own content read
    /// from) is a per-item `.filter`, never an all-or-nothing gate — so one ineligible entry (today,
    /// only `.accountSharing` before role resolution) only ever removes ITSELF, never anything else.
    /// This is already independently proven at the pure-function level by
    /// `testIneligibleRoleSpecificDestinationsAreUnavailable`; this test additionally confirms
    /// `favoriteDestinations` itself (the property the heading's visibility is keyed to) is built
    /// from that same per-item filter, never a coarser check.
    func testIneligibleAccountSharingFavoriteDoesNotSuppressUnrelatedEligibleFavoritesOrTheHeading() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/Dashboard/DashboardView.swift")
        guard let range = source.range(of: "private var favoriteDestinations: [FavoriteDestinationID] {") else {
            XCTFail("favoriteDestinations not found")
            return
        }
        let propertyBody = String(source[range.lowerBound...].prefix(400))
        XCTAssertTrue(propertyBody.contains(".filter {"), "favoriteDestinations must filter per-item, never hide the whole list because one entry became ineligible")
        XCTAssertTrue(propertyBody.contains("FavoriteDestinationID.isEligible($0, accountRelatedOptionsVisibility: accountRelatedOptionsViewModel.visibility)"), "eligibility must be evaluated independently per destination, using the existing canonical isEligible rule")

        // Direct proof at the pure-function level: an ineligible `.accountSharing` alongside other
        // real destinations leaves every OTHER destination eligible, individually.
        for destination in FavoriteDestinationID.allCases where destination != .accountSharing {
            XCTAssertTrue(FavoriteDestinationID.isEligible(destination, accountRelatedOptionsVisibility: .hidden), "\(destination) must remain eligible even while .accountSharing is not")
        }
        XCTAssertFalse(FavoriteDestinationID.isEligible(.accountSharing, accountRelatedOptionsVisibility: .hidden))
    }

    /// No reserved empty gap at zero favorites — the whole `VStack` (heading + capsule) lives
    /// inside the `if` branch, so at zero eligible favorites NEITHER renders and the branch
    /// contributes nothing to the surrounding layout (matching the pre-existing, unchanged "no
    /// empty capsule" guarantee — this just confirms the heading was added the same way, not as a
    /// sibling that could render independently).
    func testFavoritesSectionContributesNothingToLayoutAtZeroFavorites() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/Dashboard/DashboardView.swift")
        guard let range = source.range(of: "private var favoritesBarSection: some View {") else {
            XCTFail("favoritesBarSection not found")
            return
        }
        let sectionBody = String(source[range.lowerBound...].prefix(900))
        XCTAssertTrue(sectionBody.contains("VStack(alignment: .leading, spacing: Theme.Spacing.sm) {"), "the heading and capsule must be wrapped in one VStack, matching every other Dashboard section's own header+content pattern")
        XCTAssertFalse(sectionBody.contains("EmptyView()"), "no placeholder/reserved-space view should be introduced for the zero-favorites case — the existing bare `if` with no `else` already contributes nothing to the layout")
    }

    /// CENTERED HEADING — the Favorites heading is a bespoke, CENTERED `Text("Favorites")`
    /// (`.frame(maxWidth: .infinity)`, default center alignment), deliberately NOT the leading-
    /// aligned `DashboardSectionHeader` component every OTHER Dashboard section still uses
    /// unchanged. Proves both halves of that requirement: Favorites diverges, nothing else does.
    func testFavoritesHeadingIsCenteredWhileOtherDashboardHeadingsStayLeadingAlignedViaDashboardSectionHeader() throws {
        let source = try Self.monthlySavingsSourceFile("../FinanceTrack/Views/Dashboard/DashboardView.swift")

        // Other Dashboard section headings are untouched (still leading-aligned) — Quick Stats
        // moved to its own inline HStack (to make room for its new info button, see
        // `testAddExpenseViewAllowsZeroAmountEntries`-style Dashboard info-button tests) but kept
        // the exact same leading-aligned Text styling; Connected Accounts still uses the shared
        // DashboardSectionHeader component unchanged.
        XCTAssertTrue(source.contains("Text(\"Quick Stats\")\n                    .font(Theme.headlineFont)\n                    .foregroundStyle(Theme.textPrimary)"), "sanity check: Quick Stats must still render as a leading-aligned heading with the same font/color as before")
        XCTAssertTrue(source.contains("DashboardSectionHeader(title: \"Connected Accounts\")"), "sanity check: Connected Accounts must still use the unchanged, leading-aligned DashboardSectionHeader")

        // The Favorites heading itself: same typography/color as DashboardSectionHeader, but
        // centered via its own full-width frame rather than a leading HStack.
        guard let range = source.range(of: "private var favoritesBarSection: some View {") else {
            XCTFail("favoritesBarSection not found")
            return
        }
        let sectionBody = String(source[range.lowerBound...].prefix(900))
        XCTAssertFalse(sectionBody.contains("DashboardSectionHeader"), "the Favorites heading must NOT use DashboardSectionHeader (that component is leading-aligned, never centered)")
        XCTAssertTrue(sectionBody.contains("Text(\"Favorites\")"), "the heading text must remain exactly \"Favorites\"")
        XCTAssertTrue(sectionBody.contains(".font(Theme.headlineFont)"), "must keep the same font as every other Dashboard section heading")
        XCTAssertTrue(sectionBody.contains(".foregroundStyle(Theme.textPrimary)"), "must keep the same color as every other Dashboard section heading")
        XCTAssertTrue(sectionBody.contains(".frame(maxWidth: .infinity)"), "the heading must be centered via a full-width frame — SwiftUI's Text default alignment within an expanded frame is centered")

        // The heading must precede its OWN `.frame(maxWidth: .infinity)` and share the exact same
        // horizontal padding constant the capsule directly below it uses — this is what keeps
        // both centered within the identical available width, so their centers align at every
        // favorite count.
        guard let headingTextRange = sectionBody.range(of: "Text(\"Favorites\")") else {
            XCTFail("could not locate the heading text")
            return
        }
        let afterHeading = String(sectionBody[headingTextRange.upperBound...].prefix(250))
        XCTAssertTrue(afterHeading.contains(".padding(.horizontal, Theme.Spacing.lg)"), "the heading must use the SAME horizontal padding constant as the capsule, so both center within the identical available width")
    }

    // MARK: - LOCAL DATA RESTORE — recovering Monthly Plan/Manual Accounts from Supabase after a
    // local wipe (fresh install/new device). See LocalDataRestoreService's own header for the full
    // upsert-by-id/known-gaps rationale.

    @MainActor
    private func makeRestoreTestContext() -> ModelContext {
        let schema = Schema([Account.self, FinanceTransaction.self, Category.self, IncomeSource.self, RecurringExpense.self, MonthlyPlanSettings.self])
        let config = ModelConfiguration(isStoredInMemoryOnly: true, cloudKitDatabase: .none)
        let container = try! ModelContainer(for: schema, configurations: [config])
        return ModelContext(container)
    }

    private func makeRestorePlanDTO(
        monthlySavingsGoal: Decimal = 500,
        incomeSources: [SharedIncomeSourceDTO] = [],
        recurringExpenses: [SharedRecurringExpenseDTO] = []
    ) -> SharedMonthlyPlanDTO {
        SharedMonthlyPlanDTO(
            monthlySavingsGoal: monthlySavingsGoal,
            bufferAmount: 100,
            autoUpdateWeeklyBudgetFromPlan: false,
            updatedAt: .now,
            incomeSources: incomeSources,
            recurringExpenses: recurringExpenses
        )
    }

    @MainActor
    func testRestoreCreatesMonthlyPlanSettingsWhenNoneExistsLocally() async throws {
        let context = makeRestoreTestContext()
        let userId = UUID()
        let backend = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        backend.sharedMonthlyPlanResult = .success(SharedMonthlyPlanResponse(plan: makeRestorePlanDTO(monthlySavingsGoal: 750)))

        let summary = try await LocalDataRestoreService.restore(context: context, userId: userId, backend: backend)

        XCTAssertTrue(summary.monthlyPlanRestored)
        let settings = try context.fetch(FetchDescriptor<MonthlyPlanSettings>())
        XCTAssertEqual(settings.count, 1)
        XCTAssertEqual(settings.first?.monthlySavingsGoal, 750)
        XCTAssertEqual(settings.first?.ownerUserID, userId)
    }

    @MainActor
    func testRestoreNeverOverwritesExistingLocalMonthlyPlanSettings() async throws {
        let context = makeRestoreTestContext()
        let userId = UUID()
        let existing = MonthlyPlanSettings(monthlySavingsGoal: 1234, ownerUserID: userId)
        context.insert(existing)
        try context.save()

        let backend = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        backend.sharedMonthlyPlanResult = .success(SharedMonthlyPlanResponse(plan: makeRestorePlanDTO(monthlySavingsGoal: 750)))

        let summary = try await LocalDataRestoreService.restore(context: context, userId: userId, backend: backend)

        XCTAssertFalse(summary.monthlyPlanRestored, "an existing local settings row must never be touched")
        let settings = try context.fetch(FetchDescriptor<MonthlyPlanSettings>())
        XCTAssertEqual(settings.count, 1)
        XCTAssertEqual(settings.first?.monthlySavingsGoal, 1234, "the pre-existing local value must survive untouched")
    }

