    func testRestoreRecreatesIncomeSourcesAndRecurringExpensesFromCloud() async throws {
        let context = makeRestoreTestContext()
        let userId = UUID()
        let incomeId = UUID()
        let expenseId = UUID()
        let backend = FakeHouseholdSharingService(stateResponse: Self.makeNoHouseholdResponse())
        backend.sharedMonthlyPlanResult = .success(SharedMonthlyPlanResponse(plan: makeRestorePlanDTO(
            incomeSources: [SharedIncomeSourceDTO(id: incomeId, name: "Paycheck", amount: 2000, frequency: "biweekly", isActive: true, nextPayDate: nil, note: nil)],
            recurringExpenses: [SharedRecurringExpenseDTO(id: expenseId, name: "Rent", amount: 1500, frequency: "monthly", isActive: true, dueDate: nil, isEssential: true, categoryName: nil, note: nil)]
        )))

        let summary = try await LocalDataRestoreService.restore(context: context, userId: userId, backend: backend)

        XCTAssertEqual(summary.incomeSourcesRestored, 1)
