    // MARK: - ICLOUD DAILY BACKUPS (CloudBackupManager) — day-collapsed filenames, 7-day retention.
    // See SpendSmartBackupService's own "iCloud daily backups" section header and
    // CloudBackupManager's own header for the full rationale.

    func testCloudBackupFilenameEncodesCalendarDayOnly() {
        let morning = day(2026, 8, 3)
        let evening = Calendar.current.date(byAdding: .hour, value: 20, to: morning)!
        XCTAssertEqual(
            SpendSmartBackupService.cloudBackupFilename(date: morning),
            SpendSmartBackupService.cloudBackupFilename(date: evening),
            "two writes on the same calendar day must produce the identical filename (overwrite, not accumulate)"
        )
    }

    func testCloudBackupFilenameDiffersAcrossCalendarDays() {
        let today = day(2026, 8, 3)
        let tomorrow = day(2026, 8, 4)
        XCTAssertNotEqual(SpendSmartBackupService.cloudBackupFilename(date: today), SpendSmartBackupService.cloudBackupFilename(date: tomorrow))
    }

    func testCloudBackupDateRoundTripsThroughFilename() {
        let original = day(2026, 8, 3)
        let filename = SpendSmartBackupService.cloudBackupFilename(date: original)
        let parsed = SpendSmartBackupService.cloudBackupDate(fromFilename: filename)
        XCTAssertNotNil(parsed)
        let calendar = Calendar(identifier: .gregorian)
        XCTAssertEqual(calendar.startOfDay(for: parsed!), calendar.startOfDay(for: original))
    }

    func testCloudBackupDateReturnsNilForForeignFilenames() {
        XCTAssertNil(SpendSmartBackupService.cloudBackupDate(fromFilename: "not-a-backup.json"))
        XCTAssertNil(SpendSmartBackupService.cloudBackupDate(fromFilename: "SpendSmart-AutoBackup-2026-08-03-120000.json"), "must not match the LOCAL auto-backup's own distinct filename shape")
    }

    func testIsCloudBackupExpiredKeepsExactlySevenDistinctDays() {
        let today = day(2026, 8, 10)
        // 0...6 days old = 7 distinct days (today plus 6 preceding) — none expired.
        for daysAgo in 0...6 {
            let filename = SpendSmartBackupService.cloudBackupFilename(date: Calendar.current.date(byAdding: .day, value: -daysAgo, to: today)!)
            XCTAssertFalse(
                SpendSmartBackupService.isCloudBackupExpired(filename: filename, referenceDate: today, retentionDays: 7),
                "day \(daysAgo) ago must be within the 7-day retention window"
            )
        }
        // 7+ days old = the 8th distinct day and beyond — expired.
        for daysAgo in 7...10 {
            let filename = SpendSmartBackupService.cloudBackupFilename(date: Calendar.current.date(byAdding: .day, value: -daysAgo, to: today)!)
            XCTAssertTrue(
                SpendSmartBackupService.isCloudBackupExpired(filename: filename, referenceDate: today, retentionDays: 7),
                "day \(daysAgo) ago must be outside the 7-day retention window"
            )
        }
    }

    func testIsCloudBackupExpiredNeverPrunesUnparseableFilenames() {
        XCTAssertFalse(SpendSmartBackupService.isCloudBackupExpired(filename: "some-other-file.json", referenceDate: day(2026, 8, 10), retentionDays: 7), "a foreign file must never be silently deleted by this rule")
    }

    func testCloudBackupFilenamesSortNewestFirst() {
        let names = [
            SpendSmartBackupService.cloudBackupFilename(date: day(2026, 8, 1)),
            SpendSmartBackupService.cloudBackupFilename(date: day(2026, 8, 3)),
            SpendSmartBackupService.cloudBackupFilename(date: day(2026, 8, 2)),
        ]
        XCTAssertEqual(names.sorted(by: >), [
            SpendSmartBackupService.cloudBackupFilename(date: day(2026, 8, 3)),
            SpendSmartBackupService.cloudBackupFilename(date: day(2026, 8, 2)),
            SpendSmartBackupService.cloudBackupFilename(date: day(2026, 8, 1)),
        ], "yyyy-MM-dd filenames must sort lexically identically to date order")
    }

    func testPruneExpiredCloudBackupsRemovesOnlyFilesOlderThanRetention() throws {
        let directory = FileManager.default.temporaryDirectory.appendingPathComponent("CloudBackupPruneTest-\(UUID().uuidString)", isDirectory: true)
        try FileManager.default.createDirectory(at: directory, withIntermediateDirectories: true)
        defer { try? FileManager.default.removeItem(at: directory) }

        let today = day(2026, 8, 10)
        let keptDate = Calendar.current.date(byAdding: .day, value: -6, to: today)!
        let prunedDate = Calendar.current.date(byAdding: .day, value: -7, to: today)!
        let keptURL = directory.appendingPathComponent(SpendSmartBackupService.cloudBackupFilename(date: keptDate))
        let prunedURL = directory.appendingPathComponent(SpendSmartBackupService.cloudBackupFilename(date: prunedDate))
        try Data("{}".utf8).write(to: keptURL)
        try Data("{}".utf8).write(to: prunedURL)

        CloudBackupManager.pruneExpiredCloudBackups(in: directory, referenceDate: today, retentionDays: 7)

        XCTAssertTrue(FileManager.default.fileExists(atPath: keptURL.path), "within-retention file must survive")
        XCTAssertFalse(FileManager.default.fileExists(atPath: prunedURL.path), "past-retention file must be removed")
    }

