    func testNormalizedRetentionDaysFallsBackToDefaultForNilZeroOrNegative() {
        XCTAssertEqual(CloudBackupManager.normalizedRetentionDays(nil), 7, "nil (never-migrated/never-set) must default to 7, not 0")
        XCTAssertEqual(CloudBackupManager.normalizedRetentionDays(0), 7, "0 must never mean 'delete every backup immediately' — it means 'use the default'")
        XCTAssertEqual(CloudBackupManager.normalizedRetentionDays(-3), 7)
        XCTAssertEqual(CloudBackupManager.normalizedRetentionDays(nil, fallback: 14), 14, "a custom fallback must be honored when explicitly passed")
