    // MARK: - CSV EXPORT

    private func csvDate(_ year: Int, _ month: Int, _ day: Int) -> Date {
        var components = DateComponents()
        components.year = year; components.month = month; components.day = day
        components.hour = 12
        return Calendar(identifier: .gregorian).date(from: components)!
    }

    private func csvTransaction(
        amount: Decimal,
        date: Date,
        type: TransactionType = .expense,
        note: String = "Test",
        isPending: Bool = false,
        category: FinanceTrack.Category? = nil,
        account: Account? = nil,
        transferDestinationAccount: Account? = nil
    ) -> FinanceTransaction {
        FinanceTransaction(
            amount: amount,
            date: date,
            type: type,
            source: .manual,
            note: note,
            isPending: isPending,
            account: account,
            category: category,
            transferDestinationAccount: transferDestinationAccount
        )
    }

